/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20181210-8","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"建設委員会","time":"午前１０時００分～午後 ２時３１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料について幾つかお伺いしたいのですけれども、この表面のほうですが、私は１１月１６日の決算特別委員会の総括質疑で、区長は国に面談に行かないのかと聞きました。それと今回、再三再四議会でも指摘しましたが、今回の面談の記録というものは公文書で残したのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"いつ、どのタイミングで決定ということは、ちょっと日時的なところはあれですが、１１月１６日の決算特別委員会でご質問をいただいたときは、その辺の詳細がまだ当然決まっていなかったということで、その旨回答したわけですが、その後。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"この委員会資料とかなり違う内容なのか、その辺を少しお伺いしたいということが１つあります。ぜひ資料としても提示していただきたいということが１つあります。伺いたいと思います。本会議での、おくの区議の一般質問で、区は区民の立場に立って地域の声をしっかり届けるというような答弁があったかと思うのですけれども、しっかり届けていないのではないかと思うのですが伺います。","respondent":"鈴木都市計画課長","answer":"区民理解、あるいは今委員からもいただいた反対の声があるというところにつきましては、これは区のほうでも教室型説明会、こうした実施が区民の方からも非常に声として大きいというところ、あるいは区民の意見もさまざまありますというところは。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"教室型説明会は今回改めて強く言ったということは、それは大事なことだと思いますけれども、区民意見がさまざまあるとおっしゃるのですが、多くの反対意見、これを届けない、届けていないということはなぜなのか、区民の中に多くの反対意見があるとは認めないということなのですか。ないものを伝えるわけにはいかないと、そういう立場なのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"やはり非常に声として大きい教室型説明会をしっかりやっていただいて、国の方が直接区に来ていただいて、品川区民に向けてこの計画案を説明していただいて、その場で区民の声をしっかり聞いていただきたいというところでやりとりをさせていただいたというところでございまして。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"伺いますけれども、この冊子のこの箇所というものを区は読んだことがないのですかということを伺いたいということが１つです。それともう一つ、「事業計画への位置づけが義務付けられた落下物対策基準についてその実効性の担保を示されたい」と要望されておりますけれども、この落下物対策基準の実効性というものが担保された場合、落下物はゼロになるのかということもあわせてお伺いします。","respondent":"鈴木都市計画課長","answer":"平成２８年になりますが、環境影響に配慮した取り組みの中で、これも騒音環境の低減に向けた取り組みをそれまで区が再三再四要望してきた中で、これは進入角度というよりも着陸飛行位置をさらに伸ばして高度が上がったという実績というか、国の対応があります。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと落下物対策も、やはりゼロになるとは言えない。ゼロになると言える立場にない。ですから、落下物対策の実効性ということを求めるのであれば、同時にこの密集市街地の上を飛ばすことをやめてくださいということが最大の落下物対策ですから、それを求めていただきたいのですけれども、落下物との関係でいかがですか。それが最大の落下物対策ではないのですかと伺います。一旦ここで終わります。","respondent":"鈴木都市計画課長","answer":"区のほうとしては、これまでお話ししてきたとおり、落下物対策については少しでもゼロに近づけるというところの中で、国に再三再四求めてきたところですので、そうした取り組みをさらに実効性あるものとしていけるように、引き続き国のほうに交渉していきたいです。","id":"exchange-005"},{"speaker":"筒井委員","kind":"確認","question":"観光にも重大な支障がある。大井競馬場の近くも通り、本当にそのレースにも影響が出るかもしれない。国がこの品川区に及ぶマイナスの状況を知っているか、知らないかということはまず非常に重要でして、国がこのような状況を知っていて、それでもあえて通そうとしているのか、そういったことを確認したいので、その国の、区のマイナスの状況についての認識はあるのかということをまずお聞きします。","respondent":"鈴木都市計画課長","answer":"何も区内の状況を１つも把握していないということではないと思いますし、ただ、先ほどおっしゃっていただいた土地の評価、これにつきましては国のほうからも伊丹や福岡の事例も挙げて、その直接的な因果関係は示されていないというところのお話があったところです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"品川区にとってマイナスな状況があるとわかっていても、やはり国としてはこの羽田新飛行ルート案、どうしてもやりたいというお立場なのでしょうか。","respondent":"鈴木都市計画課長","answer":"今、そのようなことも含めて国は実施するのかですが、これは品川区以外でも、ほかの区でも上空を飛ぶわけでございまして、そうした国のほうの説明は、やはり海外とのつながり、インバウンドを増やして海外とのつながりを強化して。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"ずっと申していますけれども、ほかの地方空港、茨城空港や、また新しい滑走路の実現など、そういったことも考えとしてはあり得なくはないと思うのですが、やはり影響が大きいからとか、住民の反対が大きいからとか、代替案も考えられるからほかの案もあり得ますねということは国は一言も一切発しなくて、まさにこの新ルート案だけというようなお考えだったのでしょうか。","respondent":"鈴木都市計画課長","answer":"そうした中で、ほかの空港を活用する考え方についても、これまで行ってきたフェーズの説明会の中で、あるいは資料の中で示されておりますが、そうしたさまざまな議論が行われてきた中で今の案が示されているですので、国としては。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問・要望","question":"国としてはそういったお考えなのでしょうけれども、今後説明会、特に教室型の説明会などでさまざまな区民のお声があると思います。それは要望で終わりますけれども、今回の、まず区長面談について、品川区としてまず常設型展示による情報発信というものを要望しているわけですが、まずこれについて国は何も回答されていないのですけれども、この常設型展示について国はどうお考えなのでしょうか。","respondent":"鈴木都市計画課長","answer":"ただ、区の捉え方としては、この２２日を迎えるまでの担当者レベルの打ち合わせの中では、常設型展示の設置についても、今会場を区のほうでも探していますし、国のほうでも探しているというところもかんがみますと、区としてはしっかり受けとめていただいて。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"担当者レベルでそのようなお話は進められているので、将来的には、いつかの段階では実施、実現に向かっているということでよろしいでしょうか。","respondent":"鈴木都市計画課長","answer":"この面談の中で、国のほうで具体的な常設型展示という言葉は出ませんでしたが、受けとめ方としては、これをぜひ実施していただくように、しっかり区のほうでも協議をさせていただいているです。","id":"exchange-010"},{"speaker":"筒井委員","kind":"確認","question":"その点、やはり区民の声で多いのは、最低限の防音措置というものをやってほしいと。特に学校施設や医療関係の施設だけではなくて、一般住宅まで防音措置というものをぜひやってほしいというお声が多いのですけれども、その点、品川区としてはお伝えはしているのかということと、お伝えしているのだとしたら、国はどのようなお考えなのか、それをお知らせください。","respondent":"鈴木都市計画課長","answer":"それから住宅への防音工事助成につきましては、これ防音助成につきましては、この新飛行ルート計画案が出される以前から、これは日本全国でもう防音工事助成というものは行われていまして、そういう意味では、この新飛行ルート案がもし実施された場合、住宅の場合。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"従前の法律でしたらそうなると思うのですけれども、やはりこの羽田新飛行ルートは品川区が一番大きな悪影響が出るところでありまして、また実際法律上の数値の基準ではなくて、体感的に非常に不快感をもたらすような騒音に対して、人体に本当に悪影響を及ぼすと思うのですが、ぜひ一番騒音被害がもたらされるこの羽田新飛行ルート、特に直下の地域については。","respondent":"鈴木都市計画課長","answer":"従前の法律の中でというお話を差し上げましたが、従前の法律を当てはめて、それで新ルート案で上空を飛んだ場合でこれに当てはめて、先ほどちょっと数字をお示しできませんでしたけれども、住宅であればＬｄｅｎ６２デシベル以上というところが対象になるわけです。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"その従前の法律というものは、なぜその基準値を設定したのかということはおわかりでしょうか。恐らく余り広げ過ぎると、莫大な費用がかかってくるとか、そういった理由だろうと思うのですけれども、わかれば教えてください。","respondent":"鈴木都市計画課長","answer":"これはもともとある環境基本法の中に、住居系の場合やその他の場合というところでいろいろ定めがありますので、そうした基準にのっとってこの数値は定められているというものです。その対象が広がるから、その数字を上げる、下げるという形で設定されているものではございません。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"学校の施設や医療施設はやってくださるということなのですか。それは法律の例外としてやってくれるということですか。","respondent":"鈴木都市計画課長","answer":"学校などといった施設については、今回示されているのが午後３時から７時、おおむねその中の３時間というところでございまして、その時間を区切った中での法改正が行われておりまして、その中でもともとは２４時間の中で均す形で騒音を測定していたものが。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"だからそれを例外として国が認めたということなのですね。これはもう品川区は一番最悪な被害を受けるところですから、それは、その程度は認めていただかないと、区民にとってもマイナスしかないと思いますので、品川区としても区民の安心・安全を最優先というのでしたら、ぜひともそこは一般住宅の防音措置もやっていただきたいのですけれども、その点を改めてよろしくお願いします。いかがお考えでしょうか。","respondent":"鈴木都市計画課長","answer":"住宅の場合は先ほどご説明したＬｄｅｎ６２デシベルですが、その他の施設についてはＬｄｅｎ５７デシベルと。この５７という数字は変わってございません。基本的にその時間を限定して対象を広げたです。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"それを２４時間で時間をならすという考えは、ぜひ国のほうに改めていただいて、今課長おっしゃられたように、従前からお願いしているということなのですけれども、ぜひこの後に至ってはさらに積極的に、一般住宅の防音措置ということを要請していっていただきたいと思います。その点もう一言、よろしくお願いします。","respondent":"鈴木都市計画課長","answer":"どういった形で住宅まで広がるかというところは、何度もこれはやりとりさせていただいて非常に難しいといいますか、もともと設定しているベースがございましたので、ただいろいろな場面、担当者レベルのやりとりの中では、その話はさせていただきたいというふうに考えてあります。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区長が国交省において航空局長と面談をされたという資料から、ちょっと確認を含めて質問させていただきたいのですが、順番からいうと常設型展示について、また高度の引き上げ、落下物対策基準ですね。それで質問としては、この４番目のゴーアラウンドについてのことなのですが、これ発生したときには適時的確な区への情報提供を図られたいというところでわざわざ要望されている、その背景。","respondent":"鈴木都市計画課長","answer":"これは当然ながら実施計画に位置づけたそれぞれの会社、航空会社でしっかり取り組んでいくですが、それをいかに国のほうでその取り組みを確認していくかという枠組みといいますか、そういったものがなければ、やはり実効性のあるものとなっていかないということの認識から。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと落下物対策基準について。これは答弁は結構です。それと、あとこの教室型説明会の実施についてなのですが、ここに周知方法として広報しながわ、ホームページ等とあるのですけれども、例えばそのチラシには、いわゆる教室型ではなくてオープンハウス、第５フェーズですか、しか載っていなかったのですが、これは載せられなかったのかという疑問、これについて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それからもう１点が、教室型説明会の周知ですが、区のほうでも事前にこの１２月上旬の新聞折り込みに入れるということは聞いておりましたので、ちょっとその交渉もしたのですが、なかなか間に合わなかったというところと、やはり大井第一地域センター管内。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"一歩前進かなとは思うのです、周知に関しても。一歩前進かなとは思うのですが、そのようなところでもう少し本気で国として周知をしていただけたらなと。はこの説明会において、私も自分の地域は、自分の地域ですから出たいと思っているのですが、当然ここには区の職員もいらっしゃるということでよろしいでしょうか。","respondent":"鈴木都市計画課長","answer":"説明していただくのは国のほうが前面に座って説明していただきますが、区のほうでもその会場には参加といいますか、当然いるようにしたいです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"「区議会公明党は国交省に対して品川区上空を飛行しないルートの再考を強く求めていきたいと考えている」ということだったので、大臣も公明党だということもありますので、ぜひこの再考を強く求めていきたいと思いますし、こういった説明会のことに関しても強く言っていただきたいのですけれども、この再考というものは求められたのか、その結果などはどうだったのかということをぜひ知りたいといいますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"意見","question":"はっきり言わせていただきますけれども、共産党とは我々ちょっとスタンスが違うので、先ほどから議会として一致しているとか、そのようなことは、すみません、そちらがそのように捉えるのは構いませんけれども、はっきり言えば我々としては区長選の党利党略であったり、選挙にこれを用いるような、区民の不安を利用するようなことは我々はくみしない、このように考えておりますので、それが全てです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"選挙に利用したこともないし、選挙というのは、選挙で政治を変えるということは当たり前の合い言葉になっていますから、私は今の批判がよくわからないと思うのですけれども、再考を強く求めていただいたのかということの答えがないのですが、答えられないということなのかわかりませんけれども、ぜひその辺は明らかにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"今のこちらに対する質問ですけれども、先ほど申し上げたとおりです。党利党略に利用されるつもりはありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"やめますけれども、別に党利党略のために聞いているわけではないということだけはご理解いただきたいと思います。いろいろ解釈の仕方というものはそれぞれ会派によってあるかもしれませんので、これ以上はやめます。成果だと思っています。それで当たり前のことなのですが、この主催は国なのか、区なのか伺いたい。これは間違いなのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区が要望して国に来ていただいて、そこで当然説明をしていろいろなご意見、質問を受けるのは事業を進める国ですから、そういった受けとめ方です。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"共催ということになるのでしょうか。ですから、共催なら共催と書いていただきたいと思います。これを作成してホームページへの掲載や希望者への配布や地域へのポスティングなど求めたいのですけれども、あとポスターですね。チラシを引き伸ばしたようなものでもいいと思うのですけれども、各地域センターに案内、ポスターなど、ぜひ掲示していただきたいのですが、それぞれいかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ただ、全てのマンションに掲示するなどということはなかなか現実的ではないのかなというところで、まずはやはり管内の町会の方に回覧をもってしっかり、あるいは区のホームページをもってしっかり周知をするです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"行政ですから。ポスターとポスティングについてはどうでしょうか。参加者の希望で延長を認めるべきだと思うのですけれども、延長不可能なのでしょうか。伺いたいと思います。その説明の内容なのですけれども、最小限にしていただいて、質疑の時間を十分確保すべきだと思うのですが、いかがでしょうか。ただ、質疑の時間を十分確保すべきだということについてはいかがなのかと。これも伺います。","respondent":"鈴木都市計画課長","answer":"その時間も、質問時間についても、今現在国のほうとは協議中ですが、どの程度説明に時間を要するか等も含めて、一定時間の質問時間のほうはとりたいというふうに区としても考えてありますので、その辺は国と協議してまいりたいです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ポスターのほうは、その強い意思を持って、同じ区の部署なのですから、地域センターには少なくとも最低限張るようにお願いしたいと思います。なぜ難しいのか伺います。ですから機械的にやらずに、ここは、例えば道路の説明会でも、区がやっていますよね、今。お尻のほうを書いていないのです。別に延長は当日なかったのですけれども、別にそのような要望もなかったから。その辺を少し確認したいと思います。","respondent":"鈴木都市計画課長","answer":"そうした方には、今国のほうともやりとりをしていますが、これはオープンハウス型でも手法として実施されておりますけれども、そういった声を書いていただいて国のほうに寄せていただくとか、そうしたところはしっかり考えていきたいというところでございまして。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、ごめんなさい。言い忘れました。チラシのほうはなぜ難しいのかということをお伺いしたいのですが、今決まっている内容について一定程度のチラシ配布というものは、それは区としての最低限の説明責任を果たしていくことになるのではないかと思うので、その周知がなければ説明会も空振りに終わってしまいますし、その辺なぜ難しいのかということを伺ったのでお答えいただきたいと思います。","respondent":"鈴木都市計画課長","answer":"先ほどのポスティングの話ですが、一定程度地域の中でポスティングを実施すべきというお話でございましたけれども、やはり今区のほうではホームページ、これはいろいろな事業、説明会実施に当たって、再開発などはそのエリア内にポスティングということもありますが。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"でもその届ける内容が非常に机上の空論といいますか、実態を捉えていないといいますか、さまざまな意見がある、反対もある、賛成もあるというぐらいではないですか。アンケートを自分でやらないで、どのようにしてその声を届けられるのですかと伺いました。区民の声をつかむ必要があるのではないですかということを伺いたい。そもそも区民の意向をつかむ必要があると区は考えていないのでしょうか。","respondent":"鈴木都市計画課長","answer":"区民の声につきましては、これまでもさまざまな機会を捉えて国のほうには伝えているところでございまして、その１つとして教室型説明会が今回実施されると。その中でも国のほうでしっかり説明いただいて、質疑の中でも地域の声をしっかり国のほうに届けていただくです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"国がやるべきと言いますけれども、国は東京都全体にこの計画をかぶせようとしているわけですよね。だからまずしっかりと区が住民の意向をつかむこのアンケート、これは必要だと思います。そもそも区民の意向をつかむ必要がないと区は考えていらっしゃるのですか。そのアンケートをやらなければ区民の意向はつかめませんよ、正直言って。区民の意向をつかむ気がないと、そのようなことなのでしょうか。","respondent":"鈴木都市計画課長","answer":"区民の意向を区が把握する必要がないということは、これまでも全く申してございません。それを実施していくのは、これは事業主体である国が行うべきというところを再三申し上げているところです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはつまり計画を容認してほしいということを求めてやっているわけです。ですから、何というのでしょう、私たちも、共産党区議団も２０１７年２月にアンケートをとりました。ですからこういったことを区がなぜやらないのか。届けられるのですか。区が今やると言っていることすらもやれないのではないでしょうか。アンケートの必要性についてどのように考えているのか、最後にもう一度伺います。","respondent":"鈴木都市計画課長","answer":"先ほど委員からもご紹介いただきましたが、これ説明するべきは国です。地域の理解を得ること、丁寧に説明していただくこと、これは事業主体である国がしっかり行っていただくと。","id":"exchange-031"},{"speaker":"大沢委員","kind":"質問","question":"これは区の範囲ではないかもわからないですけれども、ご存じであればそこのところを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"やはり区民の方から不安の声、あるいは何だったのでしょうかという問い合わせに対して、これは先ほどご紹介いただきましたが、国がしっかり、これは国のほうでもそうした窓口といいますか、電話番号を公表して窓口を設置しているというようなところもございまして、今。","id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"同じということで、では実際に他の自治体、他の空港に関しても、品川区と同様で情報の提供を図るということで終わっているという、このようなことでいいのですか。","respondent":"鈴木都市計画課長","answer":"結果としてほかの自治体も同じだと思うのですけれども、区民の方がなかなか空港に直接お問い合わせをするという思いに至ることはなくて、やはり自治体に直接問い合わせをするというところで、やはりそういったゴーアラウンドがあった場合はいろいろ事象を調べて。","id":"exchange-033"},{"speaker":"大沢委員","kind":"質問","question":"気象、気流等々で難しいと思うのですけれども、このゴーアラウンドについての決まった航路という、そのようなものはあるのですか、ないのですか。","respondent":"鈴木都市計画課長","answer":"基本的にはそこに待機している飛行機の数や、そのときの進入ルート等で判断するので、決まった定期ルートはないというところは聞いてあります。","id":"exchange-034"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、今後実施される教室型説明会について、先ほど課長はその対象地区の方を優先にされるというような旨のお話をされましたけれども、その点何か、その対象地域の人かどうかということを判断する方法というものは、どのようにお考えなのでしょうか。","respondent":"鈴木都市計画課長","answer":"それも今ちょっと国のほうと協議中なのですが、やはりどのような説明会もそうですけれども、まず一定お名前とご住所をお書きいただくと。","id":"exchange-035"},{"speaker":"筒井委員","kind":"意見","question":"次に請願内容についてなのですけれども、アンケート調査についてなのですが、先ほど国の責任においてやるべきというご答弁がありましたけれども、この請願の理由にも書いてあるとおり、昭和５１年の９月には区がやられておるのです。この場合は品川区が主体としてやったのですけれども、なぜ今回は国でやるべきというご主張なのか。","respondent":"鈴木都市計画課長","answer":"今質問として、当時と何が違うのだですが、今は、これは飛行ルート案について、事業主体の国のほうが行う事業として説明を行っているものですので、これは当然、もしアンケートをするのであれば、実施するべきは国のほうが行うべきというものです。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。ただ、今「国のほうが、国のほうが」とおっしゃいましたけれども、品川区としては国に対してそのようなアンケート調査をやるべきだということを求めているのかということと、また私は、品川区としてもこの区民のご意見、また要望というものを把握するためには、品川区でもそのアンケート調査をやったほうがいいと思うのですけれども、その点いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"やはりこれまで国のほうに求めているとおり、丁寧な周知、説明というものを今求めて、具体的な形として教室型説明会が実施されるです。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"それでこの間の、平成２８年９月１日の広報しながわに載っていますとおり、将来の技術進歩に応じた影響軽減や、また比較的影響の大きい地域への重点的配慮、コミュニティやまちづくり面での支援の検討、訪日外国人旅行者の区内誘致、空港の活力を地域に活かすための区政・地域と連携した取り組みの支援など、これ非常に羽田新飛行ルート、残念ながら通ってしまった場合において。","respondent":"鈴木都市計画課長","answer":"その具体的な内容をこれから行われる教室型説明会で国が行うかどうかは、やはりまず区民の方がどういったところをしっかりお聞きになりたいかというところもあろうかと思います。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"私が申したのは、今後実施される教室型説明会ではなくて、またそれとは別に品川区が主催でやる、教室型説明会で品川区関連事項の説明をやってはいかがですかというお話なのですけれども、この請願趣旨も「区が」ということが主語になっていますので、品川区が主催で、品川区関連事項のお話をするという説明会、この実施についてなのですが。","respondent":"鈴木都市計画課長","answer":"なかなか実施されなかった教室型説明会が今回これから実施されていくということで、この機会を捉えてというところと、今ご質問いただいた区独自にというところは、やはりこれはいろいろなお願いをしているところで。","id":"exchange-039"},{"speaker":"松永副委員長","kind":"確認","question":"私からは確認でご質問します。そこで確認ですが、その中で説明会での資料というものは十分に用意されるとは思うのですけれども、そこで多分ご質問等があるとは思うのですが、例えば録音や撮影は可能なのか、また、マスコミ等は初めてということで来られるのか、その状況についてお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"それからマスコミですね。マスコミについては、今のところ特段取材をしたいというところの問い合わせはございません。これもほかの地域も順次行っていきますので、マスコミについてもどう対応していくかについては、しっかり国のほうと協議をしていきたいです。","id":"exchange-040"}]},{"id":"topic-02","title":"平成３０年請願第１９号 特定整備路線 放射２号線 現状を見直し改善を求める請願","agenda":"平成３０年請願第１９号 特定整備路線 放射２号線 現状を見直し改善を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"現在の放射２号線の土地の買収率といいますか、取得率をお伺いすることと、それと資料の写真の中に車がとまっていると思うのですけれども、これは誰が使っているものなのか、わかれば教えてください。","respondent":"鈴木都市計画課長","answer":"それから写真ですが、これは地域の方に貸し出し、あるいは何か民間の団体に貸し出しということは聞いておりませんので、想定になりますけれども、確認がとれていなくて申しわけございませんが、都の職員等々がこちらに来て、この放射２号線関係で仕事をするに当たって。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"１９％程度ということなので、これは整備がかなり難しいと考えています。もともと必要ない道路でもある上、このように遊んでいる土地は有効活用すべきだとは思います。伺いますけれども、区内ではこのように暫定公園として活用されてきた例というものは結構あると思うのですが、このような将来の事業予定地ですね。それらがどこにどのような例があるのか、わかれば教えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"これまでさまざまなところで都市計画道路が進められ、都であったり、区であったりですが、過去の事例としては、一定程度の形がまとまったところは協議をして、そうした区民への貸し出し等のために、一定暫定的に使わせていただいたという事例はあります。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと請願項目の２番目のほうにかかわってくるのですけれども、ここに書いているとおり、区議会でも、区でも、これは都の事業なのだということにせず、やはり本当にこの道路に対して区民にどのような意向があるのか、あるいは必要なのかどうか、求められているのかどうかということをしっかりと、区民の代表としても、行政としましても、つかんだ上でチェックしていくということが私は必要だと思うのです。","respondent":"鈴木都市計画課長","answer":"先ほどの過去の活用の事例で、少し説明が不足していたところがあります。この請願にありますように、避難路として、あるいは避難空地として、例えば公園整備をして活用すると、そういった事例はこれまでは一切ございません。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"しかも都と連携しながら進めようと、進めてほしくないのですけれども、区が言っている事業のところなので、私はこれ可能なのではないかと思うのですが、もう一度伺います。このようなことで事業を進めていいのですか。それでまともな道路、まともな都市計画になるのですかと私は思うのですけれども、これでいいのでしょうか。伺いたいと思います。","respondent":"高梨木密整備推進課長、鈴木都市計画課長","answer":"あのような形で整備させていただいているのは、今後またさらに隣地との交渉状況においては、さらなる、いわゆる防災広場としての拡張が見込まれるといったようなことで、暫定的にあのような形で整備しているです。当然ながら今回事業決定するに当たっては、東京都において住民説明会、あるいは法に基づく公告縦覧など、しっかり手続きを踏んで計画が進められているです。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"私も放射２号線や２９号線の事業説明会には何度も参加しましたが、そこでの説明というものは、まず冒頭に「これは決定されました」ということが出されるのです。「何年に都市計画決定されました」というところから始まっているので、私が伺ったのは一度も計画の賛否を問われることなく、この計画が事業化されているということでいいのですかと伺いました。お答えください。","respondent":"鈴木都市計画課長","answer":"手続きの適否、あるいはいいのかどうかというところは、これは我々が判断するものではなくて、事業主体の東京都がしっかり手順を踏んで進めていっているですので、東京都のほうは、先ほど申しました延焼遮断帯の形成。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"本当に身近な自治体としてどうなのですか、そのスタンスは。請願の３つ目の理由について関連して伺うのですけれども、これは実際にこの道路というものは延焼遮断帯ということもありながら、避難ルートだというお話が、説明でもありました。伺います。この事業目的そのものが崩れているということにならないでしょうか。","respondent":"古巻防災課長、高梨木密整備推進課長","answer":"今、避難路のお話が出ましたので、少しお話をしますけれども、実際まだ道路として供用されているものではありませんので、そのときにどのような形になるのかということは想定以上の話はできないのですが。私からは、今このような道路予定地が囲われて、何の効果も発しないといったところについてご説明をします。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"この時点で。これからはそうした空き地になったところをどう市民のために活用するかということを考えていくのですとおっしゃっておりました。ですから、膨大な労力と膨大な経費と、そして犠牲を払って、このような道路を遮二無二つくっていくということは、私は見直すべきだと思います。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"大沢委員","kind":"質問","question":"公園について伺いたいのですけれども、あいた土地に公園をつくるとなると、やはり近隣の住民の方、近隣の隣接する家屋、住居について理解を得られなければいけないので、そのように簡単に公園というものはできるものではないと私は思っているのですけれども、そこのところをどのように考えているのか教えてください。","respondent":"溝口公園課長","answer":"そういった中、区の一定の方針としましては、町会内に公園がないところ、そういったところを重点的に整備していくように考えているところですので、引き続き公園の整備、そういったものには取り組んでいきたいと考えているところです。","id":"exchange-048"},{"speaker":"大沢委員","kind":"質問","question":"ここの今、資料に示されているあたりはやはり密集をしていて、公園が２つぐらい近隣にはあると思うので、私は必要性は感じていないのですけれども、実際地域からそのような声というものは、事業主体が都でありますが、説明などでは都と一緒に区も回られていたので、地元の自治体である品川区の皆さんが近隣の住民の方とお話をされている部分も多いと思うのですけれども。","respondent":"鈴木都市計画課長","answer":"個別具体の対応は東京都が行っているわけですが、具体的に地域の方から、この地域に公園が少ないので、暫定的といえどもこの空間を公園として整備してほしいなどという具体的なお話はいただいておりません。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出すで、会派の地元の議員にも確認をしてまいりましたが、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択です。計画そのものを見直すべきだということもあわせて、採択したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"筒井委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]},{"id":"topic-03","title":"平成３０年請願第２１号 都営地下鉄中延駅（東中延２丁目口）のエレベーターなどの設置に向け、品川区が東京都と連携して取り組むことを求める請願","agenda":"平成３０年請願第２１号 都営地下鉄中延駅（東中延２丁目口）のエレベーターなどの設置に向け、品川区が東京都と連携して取り組むことを求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"品川区は、中延駅のこの当該箇所へのエスカレーターまたはエレベーター設置について、東京都と意見交換をしたことがあるのか伺いたいと思います。あるとしたらどのような内容だったのでしょうか。Ａ３口の利用状況について、どのような結果だったのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今委員のほうから、東京都がこのエレベーター、この出入り口についてエレベーター設置の検討を行ってるという状況についても、具体的な内容については今現在報告のほうは受けていない状況です。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"この件で都議会のほうでも、１２月３日の公営企業委員会のほうで請願が出て審査されたようなのです。この流動調査を行ったと。お伺いしたいのですけれども、この駅利用者数の推移というのですか、そしてこのＡ３口の利用割合というものはどれぐらいなのか、教えてください。それと、区としてはこのＡ３口へのエレベーター、またはエスカレーター設置の必要があると考えているのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"駅全体として、あるいは東京都交通局のほうがほかの駅も踏まえて、非常にこのような駅というものは都営地下鉄に限らず、ほかの駅でも出入り口が地下から地上に出ていますので、東京都としてどう考えるかというところもありますが、利用状況からいって。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから年々増えていると。Ａ４口のほうを私も現地で改めて確認したのですけれども、この写真にあるように、非常に歩道も狭いということもあり、なおかつ高齢者の方にとってはかなり歩くのです。ですから非常に、請願に書いているように、高齢者や障害者の方などにとっては、やはりＡ３出口にエレベーター、エスカレーターがないと、なかなかこれは大変な状況だということを現地で私も実感をいたしました。","respondent":"鈴木都市計画課長","answer":"その部分にエレベーター、エスカレーターをつけるというところは、現地も見ましたが、これは当然目視だけですけれども、いろいろ検討しなければいけないところが、もともと建物だけの部分で建てようとすると、なかなか技術的には難しいところがあるのかなというところは。","id":"exchange-055"},{"speaker":"安藤委員","kind":"確認","question":"技術的に難しいということですけれども、区としては技術的に無理だということはないと。設置不可能だということではないことでよろしいのか、確認をお願いします。","respondent":"鈴木都市計画課長","answer":"今申し上げましたように、目視ですので技術的な検証は全くしてございませんので、当然ながら技術的に検証を行うべきは東京都ですので、できるかどうかということは、ちょっとこの場ではお答えできないです。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"その辺はどうなのか。今言ったような課題というものは、区としては特に把握していないということなのか、もう一度お伺いします。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただいたように、周辺というか、そこの部分に都市計画道路補助３０号線、また国道のほうは放射１号線、都市計画道路が入っているというところは区としても承知していますが、今ご紹介した公式な資料、東京都の委員会での資料ですけれども、承知してございませんので。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"このように、まだ地元の自治体である区と都の、しかもその設置に当たっては３０号線という都市計画道路の計画などもかかわっていたりするので、ただ、設置されることによって利便性は向上するということですから、連携して、ぜひここに設置ができるような方向で、さまざまな議論が必要だと私は思いますし、今の議論を聞いてますます、若干生煮えの状況といいますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その上で私も地元の議員に確認をさせていただいて、確かに言われてみればこちらのほうにあったほうがいいのは決まっている話なので、先ほど安藤委員からもありましたけれども、ぜひ東京都のほうとこの件については東京都の見解、先ほど安藤委員はあえておっしゃられなかったのかもしれませんが、かなり否定的なご意見が出ていますけれども。","respondent":"鈴木都市計画課長","answer":"今、東京都の委員会におけるやりとりということでご紹介いただきましたが、その点についても含めて、区のほうでも、今ご紹介いただいたように、ワンルートは確保されていると、先ほど述べさせていただきましたが、やはり利便性が高まるということは間違いないですので。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"失礼しました。私、協議という言い方をして大変失礼申し上げたのですけれども、連携をとっていただいて、そこについては確認をしていただきたいということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"今、拡幅予定があるというお話が出ましたけれども、これ実際拡幅された場合は、逆にエレベーター、エスカレーターの設置は難しくなるのですか。それとも容易になる方向に行くのですか。どうでしょうか。","respondent":"鈴木都市計画課長","answer":"現在の出入り口が、先ほどご説明した第２京浜、またそれに交差する形の補助３０号線、その拡幅後のラインを避けた形で建ってあります。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。これは要望で終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"今のところは、この３０号線の予定があるということなのですけれども、この用地、３０号線の道路は区道の都市計画道路の予定ですが、そこの三角の土地である用地の所有者というものは、今現状どうなっているものなのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"その隅切り部分のことだと思いますが、その部分については東京都の所有地です。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"今東京都の用地ということなので、そこに都がエレベーターをつくるために、つくれるかどうかということを検討するために調査を行ったのですが、そこには区道の都市計画があるという構図なのです。ですから品川区が東京都と協議して、この計画線はあるにしてもエレベーターを設置するということは、私は区民の理解は得られると思いますし、必要なことだと思うのですけれども、いかがでしょうか。","respondent":"長尾建築課長、鈴木都市計画課長","answer":"計画道路におきましては、現状ですと建物ですと３階建てまで、地上１０ｍの高さまでということで、あと地下の構造物等はつくれないというところが制限になっておりまして、その一定の制限の中で建物を建てていただいているということが。今所管のほうで道路内の建築制限についてご説明差し上げましたが、基本的には通常の建物であればある一定程度は都市計画道路内に許可を受けて整備できるですけれども、どうしても今回地下構造物が伴うというところで。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"不可能と書いているわけではないのです。私が伺ったのは、地階を有しないことと書いているのですけれども、エレベーターというものがつくれないという法律的な根拠はあるのですかというか、その法律の内容を説明してほしいのですが、そこはちょっとしっかりとお知らせいただきたいと思います。ですから、ちょっとそれはおかしいということを言いたいと思います。","respondent":"長尾建築課長","answer":"都市計画道路内に仮にエレベーターをつくる、つくろうとした場合、こちらの中延駅の場合ですと、当然地下の駅にエレベーターを通過させるということは、地下の構造物をつくるということになりますので、都市計画法の第５３条の許可要件に合致してこないということになりまして。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"大崎駅にもありますが、それは１１５cmぐらいなのです。ただ、すごい人がここを通ってくるので、それでいいのですかという問題はあるかもしれないですけれども、例えばピーク時の時間帯には下り運行にするなど、運用の工夫でこういった混雑にも対応できるのではないかと。だからエスカレーターの設置というものは現状でも可能なのではないかと思うのですけれども、区のお考えがあればお伺いします。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただいた、やはり細い１人乗り用のエスカレーターを設置すれば、ある意味今の階段の幅が確保できずに、朝のラッシュ時にどういった影響を与えるかということも含めて、これは東京都がしっかり検討いただくことですけれども、その検討の中において。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問・要望","question":"利用者の利便性を向上するための取組みとして、さまざまなものの１つにエレベーター、エスカレーターの設置を求めるという声が請願として出てきておりますけれども、この駅の利便性を増すことについては、都との協議というか、やりとりをしていくということで、これ非常に前向きな今後の姿勢を感じることができましたことから、これは今後の成り行きを見ていきたいということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"松永副委員長","kind":"意見","question":"理由を述べします。しかし、乗降客や今後のことも考えますと、Ａ３出口を利用される方は約８割を超えておりますので、ぜひ東京都と今後協議をしていただき、それから議論をし、決めていかれることが望ましいと考えまして、この請願については継続とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"筒井委員","kind":"質問","question":"私は、先ほども課長からご答弁ありましたとおり、都と協議や話し合いをされていくということで、その都との話し合いの内容を、引き続きその推移を見守っていきたいと。それでまた議論していきたいということで、継続でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"私はこの書いているとおり、そうすべきだと思うのですけれども、区はそれぞれどのように考えているのか、またどのように検討していくお考えなのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"どういった形で検討を進めるのかというところもご質問いただきましたが、質問のご趣旨としては、検討会議体のことでよろしかったかと思うのですけれども、会議体につきましては平成２６年に設置しております地域交通検討会、この会議体を活用しながら。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"今の時点でどのように考えているのか、伺いたいと思います。それと検討会のほうはこれから聞こうと思っていたのですけれども、その前にちょっとごめんなさい。料金を低額にすべきということです。私もそうあるべきだと思うのですけれども、これについての区の考えは、現時点でどうなのか伺います。","respondent":"鈴木都市計画課長","answer":"それからあと、導入するに当たって区の基本的な考え方ですが、これも第３回定例会でご説明しましたけれども、例えば鉄道、バス等が区民の生活には本当に必要不可欠なインフラだというようには認識しています。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問・要望","question":"それ以外は１００円程度の低廉な料金にするようにということを会派としては求めたのですけれども、やはりなぜこの場で事業採算性という言葉が何度も出てくるのかと。このコミュニティバスというものは、採算をとることが目的ではなく、やはり区民の生活向上、そして移動する権利をしっかり保障するという観点から必要な事業なので、そこはなぜなのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"やはりそこは事業採算性という視点をバスの運行、状況によっては民間と協定を結ぶ等でやっていただく、あるいはどういったやり方があるかということもこれからですが、その中でこの視点を抜きにして進めるということは、当然ながらあり得ないわけでございまして。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問・要望","question":"その視点だけが突出しないようにといいますか、その視点を強調する余り、このコミュニティバスの本来の目的というのですか、それを外さないように、しっかりその辺は気をつけていただきたいと思います。その会議体の話で、先ほど平成２６年設置の検討会を活用しながらという話もありましたけれども、あの検討会というものは今開店休業状態ですが、これを再開するということなのですか。","respondent":"鈴木都市計画課長","answer":"これ行く行くは法定会議、導入する場合の法定会議体もありますので、おおむねそのメンバーは同じメンバーになりますが、しっかり国の運輸局と交渉していく中では、そうした法定会議体への移行が必要になってきますので。","id":"exchange-073"},{"speaker":"安藤委員","kind":"質問・要望","question":"そして私は、例えば各地域から満遍なく複数の公募の区民の参加というものも、しっかりと区内にある交通不便地域、駅からの距離だけにとどまらない、暮らしている方々や各地域からのニーズをくみ上げる点でも、八潮地域、品川地域、大崎地域というようになるのかはわからないのですけれども、各一定のエリアそれぞれから満遍なく、複数の公募区民の参加というものが必要だと思うのですが。","respondent":"鈴木都市計画課長","answer":"地域交通検討会のメンバーについてですが、現在学識が２名、それからバス事業者、タクシー事業者、それから住民または利用者の代表の方、それから交通管理者、道路管理者、区の職員が入っているというところが、今の会議体です。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"このようなものはやるべきだと思うのですけれども、いかがでしょうかということをもう一度お伺いしたいと思います。あわせてこの内容です。行きたいのだけれども行けない。ですから、区民ニーズが高い行き先、今述べたようなそれぞれについて、ニーズが高い行き先にアクセスしているバス停や鉄道の駅の位置、距離というものがどうなっているかという、このような基礎調査が必要なのではないかと。","respondent":"鈴木都市計画課長","answer":"それからルート等のところですが、その会議体において検討いただくための準備、資料づくり、これはいろいろ本当に断片的なところではなくて、しっかりご議論いただくように準備をして、よりよい形に進んでいくように、ご議論が活発になるように。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"しっかりここに書かれていること、請願の内容というものはやはり区民の願いを書いているとすごく思うのです。最後、ごめんなさい、１点だけ。自分で言うのもなんですけれども。行き先との関係での調査というものはしないと、そこの行き先と各エリアとの位置関係、ネットワーク関係、そういうもの、行き先との関係での調査というものはどうしても必要だと思うのですが、その点についてもう一度お伺いします。","respondent":"鈴木都市計画課長","answer":"今ご紹介いただいた内容も含めて、しっかり検討していきたいです。","id":"exchange-076"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、品川区としては地域公共交通会議等々で想定外の出来事がない限り、品川区としてコミュニティバスを運行させるという方向でよろしいのでしょうか。","respondent":"鈴木都市計画課長","answer":"基本的には実施していく方向で検討していきたいですが、まずはどういった枠組み、あるいはそういった事業採算性を含めて、ゼロベースというわけではございませんけれども、導入を見据えておりますが、やはり基礎的なところから積み上げていきたいと考えています。","id":"exchange-077"},{"speaker":"筒井委員","kind":"質問","question":"地域公共交通会議でいろいろとお話しされることだと思うのですけれども、まずこのコミュニティバスは完全に区営でやっていくのか、それとも民間委託でやっていくのか、その辺の方向性は今どの程度お考えなのでしょうか。","respondent":"鈴木都市計画課長","answer":"そこもしっかり検討していく予定なのですが、ほかの自治体の今までの事例を見ますと、区営でやっているということは余り、やはりノウハウ等もありますし、交通安全、バスの安全性の問題などといったところから、区が直営でやるということは。","id":"exchange-078"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。事業採算性というお話も出ております。いろいろアイデアやお考えはあると思いますけれども、ただ漫然とコミュニティバスを走らせるだけではなくて、走らせることによって、今言ったように防災や環境、シティプロモーションなど多分野にわたって効果があるようなものにしていったらいいのかなと思っていますが、その点品川区としてはいかがお考えでしょうか。","respondent":"鈴木都市計画課長","answer":"それにプラスアルファして、今ご紹介いただいた、そうしたプラスアルファといいますか、検討していく中で、経費削減として車両の小型化や維持管理費の削減、あるいは路線ごとの、これもまた具体的な話になりますが、その路線数や曜日での増減、そうした。","id":"exchange-079"},{"speaker":"筒井委員","kind":"質問","question":"特に今までの地域交通検討会ですと、町会の場合は町会連合会の会長だけしか参加されていないようですけれども、このコミュニティバスという性質上、やはり品川区の１３地区から代表を出して参加していただくことや、また、適宜区民アンケートやパブリックコメントというものをやっていかれて、幅広い区民のお声を聞いていったほうがいいかなと考えていますが、その点いかがお考えでしょうか。","respondent":"鈴木都市計画課長","answer":"地域交通検討会と、後に移行する法定会議体での、特に区民の方の参加の仕方については、平成２６年に設置して、一定程度時間もたってありますので、この会議体を基本に、まず来年度検討を開始したいところですが、そうしたメンバー、特に区民参加について、そこも含めて。","id":"exchange-080"},{"speaker":"大沢委員","kind":"質問・要望","question":"その中には他区がやっている、他自治体がやっているからとか、時流の中での雰囲気を感じてならないのですが、１回これ路線を走らせてしまうと、やめることはなかなかできないものですから、いろいろな課題もあると思いますけれども、そこのところはしっかりと、先ほど来お話に出ているように、１００円バスなどいろいろな名前、名称がありますが、採算性はある程度考えてやらないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"あくつ委員","kind":"提案","question":"継続ですが、一言意見を述べします。その上で私どもの会派で、まずこの法定の地域公共交通会議というものを設置して調査をしてみたらどうだというご提案をさせていただいて、区のほうでは法定ではないけれども、地域交通検討会というものをつくっていただいたのですが、２回開いて３年間とまっていたという事実もあります。私はこのように感じています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいのですけれども、やはりコミュニティバス導入ということは、切実な区民の暮らしの実態から出てくる声なのです。やはり世論と運動の結果だと私は思っております。この請願については、ここに書いてあることは非常に実効性ある、コミュニティバスを実現させるに当たっては必要な内容だと思いますので、私は採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"松永副委員長","kind":"意見","question":"我が会派は、継続とします。理由は前回と同様で、今後関連団体などと地域交通検討会で既存路線との競合などの議論を検討されていくということでしたので、その検討会の動向を見て、今後について考えていきたいと考えていますので、この請願に関しては継続とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択ですが、コミュニティバスの運行をしてくださいという内容なので、採択していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"}]},{"id":"topic-04","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"報告第２４号で、これ「同車の後輪等を破損した」ということで、損害賠償云々かんぬんで修理費等という、「等」には何が含まれるのですか。","respondent":"多並道路課長","answer":"それ以外に、この方は自転車で通勤されている方で、その修理に１日かかってしまった関係で、その関係での代替の交通費用も含めてということで、この方が碑文谷から通っている方でしたので、そのバスの費用と電車の費用ということで。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"現場の検証のようなものをしたと思うのですけれども、その状況から、なぜ街路樹が強風に耐えられなかったかなどの原因というものは判明したのでしょうか。報告第２４号は、こういったことで今回はパンクだということなのですけれども、歩行者や自転車の転倒、けがなどにつながる可能性もあるのかと思うのですが、同様の箇所がないかという点検の体制というものはどうなっているのかお伺いします。","respondent":"多並道路課長","answer":"それが風で、今回のこの９ｍぐらいの風でそれが落っこちてきたということが原因だと判断しておりますので、今後の対応といたしましては、やはり剪定作業や、あと定期的な点検の中で、そのようなことがないかということで、点検を徹底していきたいということで。","id":"exchange-087"},{"speaker":"筒井委員","kind":"質問","question":"この２件とも、過失というのは区の点検義務違反によるものだということ、そういった意味で過失とおっしゃったのでしょうか。","respondent":"多並道路課長","answer":"今委員のご指摘のとおり、我々の今までの事例と、あとは契約されている保険会社といろいろなほかの過去の事例などを勘案して協議させていただいて、ご本人と示談した結果、やはり区のほうが全体的に過失があるということで、このような結果となりました。","id":"exchange-088"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/602656?Template=document&Id=4250#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":62565,"voices":257}},{"id":"h30-20181210-9","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"文教委員会","time":"午前１０時００分～午後 ２時０３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","topics":[{"id":"topic-01","title":"第９２号議案、指定管理者の指定","agenda":"第９２号議案、指定管理者の指定","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"４の候補者選定経過のところの（１）、候補者を公募せず現在の指定管理者を候補者とするという、ここの品川区指定管理者制度活用に係る指針のところにかかわって教えていただきたいと思います。よろしくお願いします。","respondent":"吉田保育施設調整担当課長","answer":"ホームページでも公開しておりますけれども、品川区指定管理者制度活用に係る指針というのがございまして、その中で、一定程度、継続性とか、特殊な事情が必要なものにつきましては、候補者を公募しないで選定委員会を行っても構わないこととなっております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"１０月でしたか、モニタリングの総括があったのですが、そこの総括の改善の必要性のところで、１つ質問したのですけれども、保育士の確保が依然厳しい状況ということと、職員の定着化、離職・転職の防止、処遇改善という項目があったので、その辺をどう捉えていらっしゃるのかということと、第三者評価の率がとてもよいという報告があったので、第三者評価。","respondent":"吉田保育施設調整担当課長","answer":"職員の処遇の面ですけれども、キャリアアップ補助金、保育サービス推進費等を活用しまして、特別賞与を上げるなど、そのような対応を積極的に行っております。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"第三者評価のところも、やはり保育園のところだけ。ということは、３歳以上の、ここのＮＰＯ法人で行われています乳幼児の教育施設で、乳幼児のところの評価というのは、第三者評価的なものできちんと評価をされているのかどうか、そこをもう一回お伺いします。","respondent":"吉田保育施設調整担当課長","answer":"そこのところは、現行の仕組み自体がゼロ歳児から２歳児までが保育園でございまして、３歳児から５歳児までにつきましては幼児教育施設、認可外保育施設という形になっているところは、今も変わっておりません。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"今のところはすごく大事です。一般の幼稚園とか区立の幼稚園に勤めると経験年数が加算されるけれども、ぷりすくーるのここは加算されない。前からの課題だったと思うのですが、認定こども園に移行すれば、ここのところは改善されていくのかどうか、そこがとても気になっているので教えてください。","respondent":"吉田保育施設調整担当課長","answer":"認定こども園に移行した場合は、認定こども園という施設になりますので、認定こども園で働いたというキャリアになるところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よくわからないですが、認定こども園に移行すると、保育園のところも、乳幼児教育の幼稚園の部分も、両方きちんと経験年数としてカウントされるのかどうか、そこをもう一回お伺いしたいのと、この先の見通しが何かあるのだったら教えていただきたいと思います。だから、そういうところも含めて、改善がされて評価がされているのかというのを私は知りたいと思っているので、１点そこを教えてください。","respondent":"吉田保育施設調整担当課長","answer":"そこで例えばゼロ歳児から２歳までが保育園だというわけではなくて、認定こども園という枠組みの中では、あくまで就学前のゼロ歳から２歳までは保育を実施する、それから、それ以降のところでは教育を実施する。このようなイメージです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは、児童福祉法だけではなくて、子ども・子育ての法律ができたことでの一方の中身だと思って受けとめました。この間のモニタリングの総括の中で、幼保連携型の認定こども園の移行について、若干議論になったかと思うのですけれども、今の形から認定こども園に移行するに当たって、課題が何なのかをもう一回明確に教えてほしいのですが、この間、園庭が今の状態だと認定こども園にならない。","respondent":"吉田保育施設調整担当課長","answer":"幼保連携型認定こども園に移行するに当たっては、２点の問題があります。１点は、認定こども園につきましては、都で申請する際に、各年代層に何人いるか、それによって園庭が何平米要るかというところを細かく定めてあります。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"意見","question":"今、社会福祉法人化が平成３２年ということなのですけれども、指定管理が今回５年です。この途中でＮＰＯから法人になることについて、問題はないのかというお答えがなかったので、その辺の課題、何かクリアするような問題があるのかどうか、聞かせてください。","respondent":"吉田保育施設調整担当課長","answer":"答弁が漏れました。ＮＰＯ法人で今回受託して、その後、例えばＮＰＯ法人が社会福祉法人になった場合、そのまま継続して指定管理をするということについては、他の自治体でも例はありますので、特に問題がないと認識しております。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"園庭問題は、具体的に足りないのを、あそこの周りを見ても、どうするのかなと思ったのですけれども、それはどのように改善できるのか、何かめどがあるのかどうかを教えてほしいのと、途中で社会福祉法人に変わっていくことは問題ないということなのですけれども、社会福祉法人化されたらプロポーザル方式を使ったりとか、そういうことはないのか、今までどおり。","respondent":"吉田保育施設調整担当課長","answer":"プロポーザルとかをやるかどうかですけれども、今回、もしご承認いただけた場合、この５年間につきましては、ＮＰＯ法人が社会福祉法人化したことによるものですので、特にその間にプロポーザルをする等、そういうことは予定しておりません。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、もっと努力をしていただきたいと思っているのですけれども、その辺について、どういうふうに考えているのかというのが１つと、それから、一般的には公務員の保育士も、私立で働いてきた部分は２分の１加算というのがあります。そういうことが該当できるような工夫というのはないのかなと、さっきの質疑を聞いていて思ったのですけれども、その辺についてどうなのかを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"その制度として、例えば勤めたところが私立保育園でも認可保育園であれば、認可保育園に勤務したという経歴になりますし、ぷりすくーるの幼児教育部門であれば、幼児教育部門という対応になると考えております。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"できるだけ私は長く、４.４年にとどまらずに、１０年、１５年とその地に足をしっかりつけて、保育という仕事に専念していただきたいと思うわけです。しかし、平均ですけれども４.４年しか長く勤めてこられないという状況をなくしていくには、どうしたらいいかというところでの考え方を、区としてはどういうふうに持つのかという、そこのところをまず聞きたいと思っているのです。","respondent":"吉田保育施設調整担当課長","answer":"区としましては、例えば長く勤めていただくというのは、ある意味、質の向上につながるのかなと考えておりますので、キャリアアップ補助金とか、各種補助金とか、その辺を含めまして、できる支援を行っていくところです。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"そういうのもあるので、次のところに行くに当たって、キャリアにならないのだったら、短い期間で次に転職をしていったほうがいいのではないかというマインドが働くのは当然だと、あり得ると思うので、そういう点で私は、キャリアにしっかり定着できるように、カウントできるように、私立保育園の２分の１保障するということに、同じように該当させるべきではないかと思って。","respondent":"吉田保育施設調整担当課長","answer":"現行の制度上、いろいろなところに履歴書などを出す場合にも、次の採用される側がどう受けとめるかというところであると思います。一般的には、履歴書とかに書かれたところを受けとめて、どう評価するかというのは、採用する側の判断と考えております。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"そうであれば、長く定着することなど、あまり期待できないと思うのです。そういうときに、こういうＮＰＯで、他の働いていた期間が加算されないということになると、その人にとって不利益になるわけですから、そこはきちんと保障するということが大事であって、そういう方策を何らかの方向で検討するということが、今はとりわけ人材確保という点からも、必要なのではないかと思うのです。","respondent":"福島子ども未来部長","answer":"それともう一つ、キャリアという面では、認定こども園化も区としては支援していきたいと思います。ただ、どういった形での認定こども園になるかは、これから検討しますけれども、いずれにしましても、国から認められるような認定こども園化を目指す。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"社会福祉法人化の中で解消できるという話なのですけれども、それはそれとして受けとめたいと思っています。しかし、１５年間の間のその部分の不利益というところは、一定考慮していくべきではないかと思いますので、繰り返しますけれども、ぜひ検討していただきたいということを強くお願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"賛成します。意見を２点。今、職員の方の処遇のお話がありましたけれども、児童福祉法に子ども・子育て支援法と、新しい法律ができて、２つの法律の中で、私は保育園もすごく複雑な状況になっていると思いますけれども、新しい法律の中で社会福祉法人化が進めば、いろいろ改善されるところも出てくると思うので、ぜひその辺の支援を十分していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"意見","question":"賛成です。今の社会福祉法人化と認定こども園化を目指すということで、これを区として支援し続けるという部長のお話がありましたので、ぜひスピーディーに進めて、品川区の施設のさらなる発展のために、ぜひ区として支援をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"第９８号議案、訴訟上の和解","agenda":"第９８号議案、訴訟上の和解","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"品川区、また教育委員会の立場はおいておいて、当然６年前のことで中学生ですから、亡くなられた方も被告の方々も成人を迎えるようなお年ごろになって、これから生活を続けていただくわけですが、今回、和解がこのタイミングで、話し合われていたということで丁寧な説明をいただいたのだけれども、出てきたというのは、あくまでも聞きたいのは１つ、それを私たちも議会だから審議していかなければならなくて。","respondent":"有馬庶務課長","answer":"全体の補足ですけれども、裁判の関係は、この間３５回、いろいろ審議されたということですが、最終的に証人尋問が終わったのが平成３０年１月１０日ということで、これまでずっと審議が続いてきたということで、和解のタイミングもそこになったということです。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"わかりました。これは私たちも当然、賛成をしていくところですし、これ以上何を言うわけではありません。ただ、この先、品川区が義務教育学校を含め、小・中学校をずっとやっていく中で、こういう機会ですし、今後このような議案が出てこないことは当然なのだけれども、そういった意味で、これからいじめに対する取り組み、教育委員会の考え方を、一言ここで聞かせていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"これまでも、いじめはどの学校にも誰にでも起こり得るということを大前提として踏まえながら、早期発見をして、できることであれば未然に防止するため、今後とも対策チーム、またオール品川で、地域の方やさまざまな団体の方とも情報を常に共有しながら。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"今、渡部委員もおっしゃったけれども、本当につらい問題でした。本当に、いじめ防止のためのいろいろな仕組みをつくったにもかかわらず、そういう状況になってきているというところについて、この件とはちょっとそれますけれども、まずそこは伺っておかなければいけない問題だと思いますので、その点について、区の見解を伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"したがいまして、いじめを見逃したことにより命が失われてしまうという事案は、その後は起きていないと教育委員会事務局としては認識しています。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"何回か自死がありました。それは、今の答弁を聞くと、いじめではなかったのかなと思ったのですけれども、そういうふうに言い切ってしまっていいのですかということを伺いたいと思います。区としては、そこをどういうふうに思っているのか、見解を伺いたいと思います。それと、２ページを見ると、校長が、必ずしも調査が十分でなかったと裁判でおっしゃっているのでしょうか、ここに書いてありますから。","respondent":"塚本委員長、大関教育総合支援センター長、有馬庶務課長","answer":"かなり裁判の中身の非常に難しいところにも触れているので、答えられる範囲でということでお願いします。今後とも学校といたしましても、全校でストレスの出し方という部分は継続して子どもたちに指導してまいります。教員の対応が十分でなかったのではないかということについてということですけれども、今回、被告教諭・校長それぞれ、この和解文を確認していて。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"必ずしも十分でなかったと認めたと。具体的にどこが十分ではなかったのかというところは、はっきりさせなければいけないと思います。一般論で終わらせたら、再発する可能性があると私は思いますので、改めて具体的なところを、ぜひ指摘していただきたいと思います。それを全ていじめではないと思っていいということですか。最終的に確認をしたいと思います。","respondent":"大関教育総合支援センター長、有馬庶務課長、熊谷指導課長","answer":"いじめを起因とする事案はないと認識しております。いろいろ裁判所がこの間、事実関係を調査しましたけれども、最終的には、全体として和解するときにこのような表現になって。こちらの調査なのですけれども、調査報告書が不十分であるということではなくて、いじめがあるかどうかということについて。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"だから、私はむしろ、そういうところが問題だと思うわけです。そういうことをしてはいけないと指摘をして、改善を求めるという質問をしました。きちんと、どんなに忙しくても、命にかかわる問題だから、いの一番にその子どもの言っていることを聞いた結果、「何だ、こんなことか」と思うこともあるかもしれないけれども、しっかり聞く。しかし、そういうことが……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"簡潔です。人の命がかかっている問題だから、議案ですから言っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"もちろんです。わかりました。したがって、ぜひそういうことについての見解を伺いたいと。教員は普段忙しいですから、ついついということがないようにしてほしいということを強調したくて繰り返しましたので、よろしくお願いします。それと、この和解については両当事者の間の合意ですから、これについてどうこう言うつもりは全くありません。","respondent":"大関教育総合支援センター長","answer":"例えば相談を受けた担任が、１人で課題を抱え込んでしまうことのないように、学校が組織的に対応して、さらに教育委員会がそこを支援できるように、学校支援チーム、ＨＥＡＲＴＳも応援に当たっております。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"本議案については先ほど来、確認があったとおり、それぞれの原告・被告という形、裁判上ですけれども、そうなっている方々の和解ということで、それはそれとして、しっかりとこの委員会で、私としては受けとめ、そして対応していかなければいけないというところがある前提の中で、あえて言うと、そうしたことについて、この委員会の場で先ほどあったような言い争いで。","respondent":"大関教育総合支援センター長","answer":"品川区いじめ根絶協議会では、教育委員会だけではなく、地域の方あるいは関係各所の皆さんから、ご意見を毎年、毎回いただいておりますので、今後ともこれを継続して、二度とこのような悲しい事案を生まないように、努力を継続してまいります。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問","question":"亡くなった方も含めて、その思いをしっかりと受けとめながら、前に進んでいくという教育委員会、さらに現場の教員の方々の支援も含めて、児童・生徒が本当に明るい未来に進んでいけるように、私自身が当時の教育委員会をはじめ、教員の方々に育てていただいたから、今ここにこうやっていられるわけですから、そうした希望となる現場の教育の支援になることを、これからも一生懸命お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"原告のご両親の深い悲しみは、絶対薄れることはないだろうし、またこの間、どうして、なぜという思い、疑問がとれることもないと思っています。人の命がとても大事なのだということを本当に体感したところで、今後の人生に活かしてほしいと思っています。だから、教育委員会だけの問題ではありませんが、そういうのを発信する教育委員会に変わっていただきたいと思うのですが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"これは今も継続しておりますし、今後も続けていきたいと考えております。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子どもの権利条約の話をしましたけれども、本当に日本の教育全体についても、ぜひ発信をしていただきたい。なぜかというと、受験のストレスはとても多いし、教育要領が変わるたびに授業数が増えて忙しくなっている子どもたち。私は本当に日本の教育行政は、とても子どもにストレスを与えていると思うのです。そういった立場に立っての発信をしていただきたいと思うのですが、いかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"あるいは、中には直接教育総合支援センターに来て、学校生活について相談したいということで、ＨＥＡＲＴＳのカウンセラーのところへ直接来てくれた案件等もありますので、いろいろな形で子どもの意見というものは拾っていき、丁寧に対応していきたいと考えております。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"表面化していないところにも、ぜひ目を向けていただきたいという意味で、私は教育総合支援センターの部分をもっと充実させていただきたい。この間、名古屋に視察に行ったときは、いじめの問題とかそういった問題を、経験豊かな人たちが、独立したところで扱っているというのを聞いたので、ぜひ教育総合支援センターの充実をお願いして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"特に、被告側の子どもたちも、これを機に新しい人生というのを迎えるわけでありますので、ぜひ原告側・被告側両方の一歩を踏み出すときに何かあれば、それは教育委員会はじめ、品川区としてもサポートできることは、しっかりサポートを続けていっていただきたいと思いますが、その点について何かあれば、お聞かせください。","respondent":"大関教育総合支援センター長","answer":"教育委員会といたしましては、命に関するさまざまな、心のフリーダイヤルですとか、そういったところで専門の心理士が対応していますので、今回の件もまた、原告の方・被告の方それぞれ立場はあるかもしれませんが、何か相談という部分が入りましたら。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問","question":"それはなぜかというと、改めて今後の品川区の教育をこうしていくのだということを、きちんと示すことになるのだと思いますので、そのことについて。もう一つは、もしお答えできなければ全く構わないのですけれども、（７）の品川区が賠償をするという本件解決金ということなのですが、これは教諭と校長の監督責任といいますか、区立学校ということで、それを含めてということなのでしょうか。","respondent":"有馬庶務課長","answer":"教諭の部分については、教諭それぞれ考えていただくべきものかなと捉えてあります。今回の解決金については、品川区に関する内容ということになっているものです。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。公表に関することと、解決金の話ですけれども、そういったことも含め、今後の対応は未来につながるような形で、しっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"だから、子ども同士できちんとそれをキャッチして、大人にしっかり援助を求める態度というのは非常に大切だということを、かなり強調されていたのですが、それというのは、電話が来るのを待っているのではなくて、正規の授業でしっかりと援助希求的態度を自殺予防の一環として強調して、教育するべきだと思うのですが、今現在、教育されているのかと。","respondent":"大関教育総合支援センター長","answer":"ゲートキーパー研修をはじめ、大人の教育の部分ですが、これは保健予防課とも連携を進めておりまして、ゲートキーパー研修に各校教員が参加することもしておりますし、また、品川教育の日として、教育委員会主催の教員研修の中で、命の大切さ、今度は教員として。","id":"exchange-032"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"いじめというのは一部だけですから、その飛び飛びが一番すごく大切で、自殺するとみんなが不幸になりますから、その辺はもう少し高度な取り組みというのが必要なのではないかと常に思っているので、１つの希望も交えて、質問させていただきたい。","respondent":"大関教育総合支援センター長","answer":"保健予防課と教育委員会で、これまでも自殺予防について協議している中で、ＳＯＳカード等も生まれてきておりますが、今後につきましては、またご提案いただいたような医師ですとか専門家の方に助言をいただいたり、あるいは必要な内容について講義いただくなどの機会。","id":"exchange-033"}]},{"id":"topic-03","title":"平成３０年請願第２３号、学校給食の牛乳にプラスチックストローを使用しないことを求める請願","agenda":"平成３０年請願第２３号、学校給食の牛乳にプラスチックストローを使用しないことを求める請願","exchanges":[{"speaker":"南委員","kind":"確認","question":"企業が紙のストローを使用することにするということも新聞等々で報道されていますけれども、自治体が率先してそういうことをやっていくように、検討を始めるということが必要なのではないかと考えていますけれども、改めてその点について、先ほどの話ではなかなか難しいというのが先に立ってしまう答弁かなとは思うのですけれども、改めてその辺を確認したいと思います。","respondent":"篠田学務課長","answer":"かといって、このまま放置しておこうということではなくて、社会的な動きですとか、他自治体の動きですとか、さまざまなものを注視しながら、なかなか私どもの教育委員会が先行してということは考えていないですけれども、きちんとした対応を今後もとっていきたい。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"確かに先ほどの説明で、瓶のリユースを考えていくということも１つの方法だと思いますし、私も子どものときですから、はるか何十年も前ですけれども、瓶による牛乳が給食で出て、先のとがったものでふたを外して、その処理というのは新たにありますけれども、それで飲んでいたと。教育のところで、いろいろ議論はありますけれども、品川区の教育行政は、先行してやっているではないですか。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"いずれにしましても、先ほどの瓶の使用に関しましては、申し上げたようないろいろ解決しなければいけない課題がありますので、そういったものを踏まえまして、現状このままということではなくて、今後。今回、区内の小学校でストローに関する授業等は、マスコミ等の報道でも案内があったところですので、その学校だけでなく、ほかの学校でも、関心を持っている子どもたちは確実に増えていると思いますが、今、何が一番いいかということは。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、ここの請願では、品川区から都・学校給食会・乳業者の３者へ声を挙げて頂きたく要望させて頂きますという請願の内容なので、本当にそういう形で上げていけるような結論を、この委員会で導き出していく必要があるのではないかと私は思っているのですけれども、先ほどの説明の中では、関係機関に働きかけていくのは可能なことなのだという区の認識も紹介されましたので、私としてはぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"渡部委員","kind":"質問","question":"３者に伝えることは伝えられるというところなのだけれども、実際問題として、さまざまな取り組みがあるではないですか。例えば、ストローをまずやめることを考えて、つけてもらうのをやめて、コップを持ってきて飲みましょうとかというのは、みんなで話し合って、そこからやっていこうよとかというのは、難しいのか、簡単にできるような気もしないではないのだけれども、実際どうなのですか。","respondent":"篠田学務課長","answer":"大人であれば、あまり気にならないところも、お子さん方一人ひとり違っていますので、そういったところをどういった形で対応ができるのかということを考えざるを得ないと思っていますので、いろいろな形の提案はあろうかと思いますけれども、そういったものを踏まえながら。","id":"exchange-037"},{"speaker":"渡部委員","kind":"意見","question":"ただ、そうなっても、ＣＯ２の排出量がというところにもなっていくから、すごくイタチごっこというか、そういうところがあると思うので、ウミガメのおなかの中にとか、例えばマイクロプラスチックというのは、２３区の場合は私は事情が違うと思うのだけれども、世界的環境のことを考えると、やはりみんなで考えていかなければならないことなのかなというところも鑑みて、今回は採択していこうと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"つる委員","kind":"確認","question":"今、各委員からあった、至極そのとおりだと思います。幾つか確認で、先ほどご説明の中では、紙ストローが１０倍ぐらいになる様子である。逆にプラスチックストローの、学校に今、供給されているもので結構なのですが、プラスチックストローの単価というのはお幾らなのか、わかれば教えてください。","respondent":"篠田学務課長","answer":"ただ、一般的なところで調べたところ、給食で出されているようなストローが、市販でいくと１本当たり０.５円ぐらいで販売されていますので、当然、大量にメーカー等は仕入れていますから、それよりはるかに安い金額ではあるのだろうなと考えているところです。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"それはそれで、まだ単価が高いとかいろいろあるので、基本的には区としては、この請願にもあるとおり、特に乳業者か、製造メーカーというところになっていくのかわかりませんが、そうしたところに技術開発だとか、大きい部分では依頼したりとかという流れにはなるのかなと思うのですが、まず現状のもので、コップを持参してもらうとかということも含めてあるのですが、そもそも今。","respondent":"篠田学務課長","answer":"今、各学校で提供されている紙パックは、例えば５００ミリリットルとか１リットルの牛乳パックと同じような、頭が三角になったものが非常に小さくなってコンパクトになったような形で、その上の斜面のところをめくると穴があって。","id":"exchange-040"},{"speaker":"つる委員","kind":"質問","question":"当然、大前提はエコだとかというところであるそうなのですが、各地域によっては保護者の方から、マナーとか、衛生的にどうなのかとあるわけですが、基本的に各児童・生徒一人ひとりに配られる牛乳というのは、飲み切りサイズというか、２００ミリリットルぐらいになるのでしょうか。だから、まずマナーとか、また自分で飲み干すのだから、衛生的にどうだという、この辺の考え方を教えてください。","respondent":"篠田学務課長","answer":"ただ、１つは、ストローになれている地域の方から見ると、結構抵抗があるようですので、そういった形でのご理解、品川で実施した場合に、どういった形でご理解を得ていくかといったことが１つと、それからもう一つは、衛生的な部分とか取り扱いの部分で、おそらく小学校の中学年。","id":"exchange-041"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう社会的な動きも当然、もっともっと動いていただきたいというところがあるのですが、その部分で、あとは、これは可能性ですけれども、例えばお膝元の私たちの品川区で、実は来年の４月の製品発表に向けて、区内にある企業の方、紙コップの国内シェア最大の企業があって、そこが紙ストロー、それから紙のふたの製造販売を今、進めているということを確認できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（し）委員","kind":"質問","question":"東京都と学校給食会と乳業者がいて、品川区だけでプラスチックストローを使わないということが、現実的にできるのかどうかというのが、まず１点。できないのであれば、どうやったらそれが可能になるのか、その方法というのがあるのかどうか、まず教えてください。","respondent":"篠田学務課長","answer":"ただ、そうしたときには、その代替の手段がきちんと確立していないと、当然それは話ができませんから、その代替手段をどうするかという形で、先ほど来お話が出ていたような形で、利用していく必要があるのか考えていく必要があるところです。","id":"exchange-043"},{"speaker":"石田（し）委員","kind":"質問","question":"わかりました。ということは、逆に乳業者がメイン。要は、飲み口がついているパックというのが今はあるわけではないですか。既に市販であります。皆さん飲んだことありますよね。先ほどから直飲みの話も出ているけれども、ストローを使わないで、そっちでやりましょうというのは、契約上可能なのではないかと思うのですけれども、そういうやり方もできなくはないのかどうか、教えてください。","respondent":"篠田学務課長","answer":"ただいまご提案のありましたような形での、パックにプラスチックの飲み口、キャップがついている形のものです。そうしますと、容器の形態自体が変わりますので、１つはそういった形態のものが、学校給食用として業者が対応できるのかどうかという検討が必要になると思います。","id":"exchange-044"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それをコストだとか、どうこうとかという話ではなくて、本気で品川区の教育委員会として、子どもたちも巻き込んで、こういう環境教育を、肌でみんなで感じようよというアクションを持てるかどうかだと思うので、私はこれはぜひ進めていっていただきたいと思うし、ただ先ほど、可能か不可能かわからないけれども、そういったことを品川区から発信して、２３区でみんなでやろうよというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問","question":"そんなところで、都内の教育委員会の指導課には課長会があるとお聞きしているのですが、今みたいな形で、課長会の中でこういった話題は出たりしているのでしょうか。そこを伺います。","respondent":"篠田学務課長","answer":"ただ、せんだって学校給食の乳業者が集まる会があったとお聞きしていまして、そこの中では各校、一部そういった声が上がってきているという形ではあったようなのですけれども、具体的に乳業者にもアクションがあったということではないと伺っていますので、まだ全体として。","id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"意見","question":"何らかのそういったアクションが少しずつあるということはわかりました。ぜひ、先ほどのお話にもありましたけれども、品川区が先頭に立ってというところも期待したいと思います。それこそ直飲みに合うようなパックを考えつく方も、必ずいると思いますので、そっちの方向もいいかなと思ったりします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほかの委員から出ました直飲みというのも１つの考えだし、直飲みでこぼれてしまうのだったら、１年生などはコップを用意すればいいと思うのです。教育なので、現状のごみになったものがどうなるかというのも、しっかり教えてほしいと思っています。質問は、紙のパックとストローと包んである容器が、飲み終わった後、どういうふうに処理されているのかを教えてください。","respondent":"篠田学務課長","answer":"こちらに関しては、まとめて廃棄をして、品川区内では燃えるごみとして扱われますので、焼却処分がされているというものです。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は周りの袋は容器なのかなと思って。廃プラスチックを燃やすと地球の温暖化につながっていくという、そういうところも含めて、利用するところから後の処理のところまで、きちんと子どもたちに伝えていきながら、どうしたらこの地球環境を守れるのかという立場で、身近な問題ですが奥の深い問題なので、ぜひ教育に役立てていただきたいと思うのですが、その点はいかがでしょうか。","respondent":"大関教育総合支援センター長","answer":"実際に自分たちが出したごみがどのように処理されているのか、子どもたちは見ておりますので、極力ごみは出さないようにしようと品川の子どもたちは自分で考えだしていると認識しています。","id":"exchange-049"}]},{"id":"topic-04","title":"平成３０年陳情第２２号、すまいるスクールの利用者ニーズ把握のためのアンケート調査の実施を求める陳情","agenda":"平成３０年陳情第２２号、すまいるスクールの利用者ニーズ把握のためのアンケート調査の実施を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問","question":"今、説明があり、アンケート調査は３,０００世帯ということで説明がありましたけれども、その調査とは、ここの陳情に書かれてある、「利用者ニーズを的確に把握し」ということに応える内容でやるという理解でいいのか、そのことを１点伺いたいと思います。","respondent":"高山子ども育成課長","answer":"２点目の保護者・子どもの意見というのをどのように捉えられるかという点につきましては、繰り返しになりますが、今回の調査につきましては、保護者の意見を中心としつつも、子どもの意見もいただくような形での調査形式で進めてまいりますので、そうした意味におきましては。","id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"そういうところの、１８時まででいいですという家庭はともかく、それ以降も、少なくとも１９時までは見ていただきたいという方に対しては、利用者アンケートでどの程度の割合でいるのか、少なくても実態的にはあるということであれば、それも受けとめて検討しようというふうになるのだろうと思うのですけれども、具体的な１つの例を挙げて質問ですが。","respondent":"高山子ども育成課長","answer":"まさに利用者の満足度、現制度、制度改正後の今のすまいるスクールの仕組みについて、どの程度利用者と保護者の理解が得られ、そして満足度が得られているかというところを調査するものですので、例えば利用時間でありますとか、あるいは利用料金なども含めて。","id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"アンケートをするということなので、それはそれとして、今も質問してご説明があったので、ぜひやっていただきたいということで、見守っていきたいと考えていますが、実施時期はいつなのかと、それから来年度に向けて、そういう検討したものを活かせるというか、具体的に具現化するのは来年度からと受けとめていいのかどうか、その２点をお願いします。","respondent":"高山子ども育成課長","answer":"その関係で、適用の時期につきましては、分析の中身によって費用等を伴って、一定程度予算立てをしないと実現できないようなものにつきましては、平成３１年度を検討期間とする見直しに反映させてまいりたいと考えております。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"最後にしようと思ったのだけれども、申しわけありません。利用料金についても調査をとるような説明でした。上げるのか下げるのか、そこは不鮮明なのですけれども、上げるということではない方向で検討もしていただきたいと思っているのですが、その辺についての感触というのは、もしあれば伺いたいと思います。","respondent":"高山子ども育成課長","answer":"同時に、他区と比較いたしまして、特に品川区のすまいるスクールの利用料金が過大に負担を強いているということでもございませんし、また同時に、減免の制度もこの月額の利用を導入する際に検討して、導入した経緯もありますので、そうした減免の制度も含めまして。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"私はできれば上げない方向で検討していただきたい。その理由は、やはり子育て費用の負担感です。そういう負担感を拭っていくということが大事だし、これは少子化を克服する大きな条件になっていると考えていますので、検討するというところでは、負担感のところと、できるだけ負担を和らげるという角度で検討をするべきだと考えていますので、意見として申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"下のところで、トワイライトステイのサービスもあるけれども、料金負担が非常に大きくなると。この中身も具体的に、トワイライトステイの料金体系とかを教えていただきたいと思います。もう少し下のところで太い字で、区の対応として、利用者ニーズを的確に把握し、不断の見直しを図ってまいりますと書いてあるのですが、この辺はいつ、どのような中身で見直しをしていくのか、この３点をまずお伺いします。","respondent":"高山子ども育成課長","answer":"３点目の不断の見直しにつきましては、まさにすまいるスクール事業を継続的にいいものにしていく、利用者そして保護者に資する事業として展開する上で、行政のみでニーズについて一方的に考えるのではなく、利用している保護者と児童からの直接の意見を踏まえて。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点目の３年生までというところは、放課後の生活の仕方の多様化と、子どもの成長に合わせてといった意味においては、特にここに書かれているのは、ひとりで過ごすことが困難な支援学級や支援学校在学の４年生、６年生ということで書かれているので、子どもの成長・発達をと考えたら、個別に特別な配慮の必要な、例えば障害者差別解消法とか、成長に合わせた対応をしていくという意味では。","respondent":"高山子ども育成課長","answer":"我々としても最大限努力はしてまいりますが、すまいるスクールが本来持ち合わせます集団生活の中での学びと成長という部分においては、ある程度事業の中で実現していける中身については、全てをかなえるということはなかなか難しいという状況もあるかと思いますので。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは意見です。地域に住んでいる子どもが、教育と同じくひとしく選んだところで、よりスムーズに一日が過ごせるという立場においては、ぜひ差別なくというか、その子に合った利用方法を考えてほしいと思います。いろいろな手だてがあるので、それを選んでほしいというのではなく、そこの要求が満たされるようなすまいるスクールになっていただきたいと思うのですが、この点はいかがでしょうか。","respondent":"高山子ども育成課長","answer":"なかなか重い課題だとは思いますが、そうした職員の資質向上ともども、今後考えていくべき内容ではないかと考えておりますので、決してその必要性がないということを申し上げているつもりではなくて、受け入れる体制の底上げというのも一方では必要だと考えておりますので。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ総合的に。最後に、ここに、子ども・子育て会議において多くの委員から意見を求めたうえで検討するようにしてくださいとありますが、今後の制度について、ここは当然、識者の方もいろいろな方が参加をしている会議ですので、ぜひここのところは活かしていっていただきたいと思いますが、最後にお考えをお聞かせください。","respondent":"高山子ども育成課長","answer":"そうした議題として、もとより想定しているものですので、今後議題として取り上げていくことは十分考えられると考えております。","id":"exchange-058"},{"speaker":"渡部委員","kind":"意見","question":"友達と遊びたいから。だから、そこに関して利用しない方は、必要ないから利用しないのであって、利用される方にとって使いやすいすまいるスクールである必要が私はあると考えますから、そこはアンケートを３,０００もサンプルをとる。３,０００もという言い方は変かもしれないですけれども、３,０００は立派な数でして、そんなにとるのだなと思っていて、その中でいろいろなお話があると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"つる委員","kind":"質問・要望","question":"結論を出すで、態度は不採択です。そもそも論で、アンケートをとる統計調査の基本では、そうしたとり方が基本だということも伺いました。ただ、この陳情にあるアンケートというところを取ってみれば、先ほど冒頭に言ったとおり、既にやられるということですので、それをまた、アンケートに寄せられる声を中心に、見直すべきところは見直していただくということを、しっかりとやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"採択を主張したいと思います。子どもたちが、本来放課後ですから、学校が終わった後、勉強勉強と、勉強も大事ですけれども、どう楽しく遊んで、お友達と交流できるのかなど、幅広く意見が聞かれるようなアンケートにしていただきたいと思っています。どの子も大切に、成長と発達を支えていくすまいるスクールであってほしいと思う観点から、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"石田（し）委員","kind":"質問","question":"結論を出すで、不採択です。理由は、ほかの委員も言っていらっしゃることですが、アンケートは３,０００サンプルとるということなので、特段、それ以上のものが必要というのはどうなのかなと思って、ぜひその範囲内でしっかりと声を聞いていただいて、必要なものに関してはしっかり見直しも含めて、やっていかれるかと思いますので、この陳情に関しては不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ１つだけ、３,０００世帯ということで、１万のうちの３,０００ということですから、かなり有効なものになると思うのですが、ただ、支援が必要な方々にどのぐらい届くのかなということがあるので、そこはなかなか難しいのでしょうけれども、そういうのを抽出して、またアンケートを依頼するというのもなかなか難しい面もありますけれども、ぜひ支援を必要とされて通われている方の意見を十分に集めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862391?Template=document&Id=4958#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":55543,"voices":173}},{"id":"h30-20181210-5","meetingId":"h30-cm12","date":"2018年12月10日","dateIso":"2018-12-10","committee":"総務委員会","time":"午前１０時００分～午後 ２時３６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を87件抜き出しています。","topics":[{"id":"topic-01","title":"「議案審査」を行います。 初めに、(1)第８４号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","agenda":"「議案審査」を行います。 初めに、(1)第８４号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"公費負担の額は、区長選挙が７円５１銭で、１万６,０００枚、区議会議員選挙が新たに創設されて７円５１銭で４,０００枚とのことですが、この公費負担額の算定根拠を教えてください。","respondent":"秋山選挙管理委員会事務局長","answer":"７円５１銭についてですけれども、これは公職選挙法に規定をされておりますので、それを条例でも横引いています。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これは公職選挙法で定められているものなので、どうすることもできないと思うのですが、通常であれば、枚数が多ければ多いほど単価は下がるということが考えられますが、これは別に変えてくれとかではなくて、枚数が多ければ単価は下がるということを頭の中に入れておいていただきたい。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"ビラを公費負担とした理由を伺いたいと思います。それから、条例で定めるところにより無料とすることができるということは、できる規定なのかと思うのですけれども、選挙管理委員会としてどういう判断をしたのか、その理由についても伺いたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"今回、法の改正の趣旨は、候補者の政策等を有権者が知る機会を拡充するためということで、従前、公職選挙法では、お金のかかる選挙をやめるというか、そのためにいろいろ規制がかかっていましたが、今回、候補者の政策を有権者が知る機会を拡充させるということで。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"理由はわかりました。具体的に説明していただきたいのですけれども、この新たに使えるビラというのは、いわゆる選挙期間中も、名前、顔写真、政策を記すことができるというものなのか、あと、選挙管理委員会に届け出たというところですけれども、これは立候補のときに届けるのでしょうか。最後に、紙のサイズにも条件があるのか。改正する条例の内容をご説明いただきたいと思います。","respondent":"秋山選挙管理委員会事務局長","answer":"使用できるビラですけれども、サイズはＡ４に決まっておりまして、内容に関しては特に基準はありませんが、頒布責任者の氏名、住所、印刷者の氏名を記載しなければならないということがあります。それから、証紙の貼付が必要になります。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"今の続きみたいなのですけれども、政策を知らしめるための手法がありますね。ビラの使い方について品川区として何か規制があるのかないのか、その点について教えてください。","respondent":"秋山選挙管理委員会事務局長","answer":"この条例に関しましては、公費負担の条例になりますので、区として条例で使い道を定めているものではないのですが、公職選挙法上、ビラの頒布方法は決まっておりますので、使い方はそちらに定められております。","id":"exchange-005"},{"speaker":"伊藤委員長","kind":"質問・要望","question":"１点だけ私から要望ですけれども、この条例が仮に可決した場合、これは全ての立候補者にかかわることだと思われるので、例えば、立候補予定者説明会とか、そういうときにはぜひ、具体的でわかりやすい説明をしていただきますようにお願いをしておきます。他にございませんか。ないようですので、以上で質疑を終了いたします。自民党・子ども未来からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"順番を変更しまして、(6)の第８９号議案、第二戸越幹線整備工事（上流部シールド）請負契約","agenda":"順番を変更しまして、(6)の第８９号議案、第二戸越幹線整備工事（上流部シールド）請負契約","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"区立宮前坂広場に深さ３０ｍの立坑を掘ると説明がありましたが、この辺は道が狭いのだけれども、ここから残土を搬出するのではなくて、西品川公園まで持ってきて出すのか、それとも、この区立宮前坂広場公園で残土を搬出するのかということを確認します。","respondent":"持田河川下水道課長","answer":"残土に関する搬出のご質問ですが、区立宮前坂広場での工事につきましては、道は狭いのですが、この場所から残土を搬出するという形で考えてあります。","id":"exchange-007"},{"speaker":"いながわ委員","kind":"質問・要望","question":"狭いですし、そこは坂になっていると思うので、４ｔダンプなのか、６ｔダンプなのかわからないですけれども、もちろん大型のものは入れない。どれぐらいの残土が出るかわからないですけれども、結構なダンプの台数が出入りするのでしょうか。それと地域への説明とかはお済みになっているのか、それとも、これからなのか、教えてください。","respondent":"持田河川下水道課長","answer":"地元への説明ということでいきますと、今回こういった形で契約を締結しました後には、しっかり事業者とともに地元で工事の説明という形で、ダンプでの搬出なども含めて説明をしっかりと行っていきたいと考えています。","id":"exchange-008"},{"speaker":"いながわ委員","kind":"質問・要望","question":"とにかく狭い道路なので地響きとかいろいろあろうかと思いますので、可決した暁にはしっかりやっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"公園を利用されている方や、その周辺の方への説明は丁寧に行っていただきたいと思います。それで、この第二戸越幹線自体は、いつ完成するのか。今後の見通しだけご説明いただけますでしょうか。","respondent":"持田河川下水道課長","answer":"第二戸越幹線の事業につきましては、現段階では、平成３６年度の完成という形で、少し時間もかかりますが、事業を進めているところです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"おそらく仕入れ値も人件費も違ってくるというのが当たり前だと思うのですが、入札金額がこのようにぴったり合うということは、何か不思議だなと、入札価格が漏れていて、こういうふうになったのかというような疑問を私は抱くのですが、この辺について、経理課としてはどのように考えられていますか。","respondent":"立木経理課長","answer":"予定価格は東京都等の積算価格等から適正に算出しているものなのですけれども、あとは、それぞれの共同企業体で、積算した金額と予定価格を見まして、おそらく社内で戦略的な価格づけ等を行った上で入札をしてきているものと考えております。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"こういうものに本当に疎くて申しわけないのですけれども、概要書が１２ページに出ていて、そこに工程表があるのですけれども、今、審査している議案の工事自体は、平成３１年からの債務負担行為による工事だと、それで記載されている工程表は、すごくざっくりしたものなので、平成３１年に始まっている工程はないわけですが、この工程表でいうと、どこに当たるのでしょうか。","respondent":"持田河川下水道課長","answer":"それが終わりましたら、今の予定では平成３２年度の頭からシールド工に入っていくということで、全体の事業としましては、平成３０年度から平成３３年度までとなっています。","id":"exchange-012"},{"speaker":"吉田委員","kind":"確認","question":"平成３０年度だけれども、もう平成３１年に実際は入っていて、この真ん中の棒の当初からの分というふうに理解してよろしいですか。それだけ確認させてください。","respondent":"立木経理課長","answer":"契約自体は、こちらの議決をいただいた後、契約をするということで、工事自体が終了するのが平成３３年ということになりますので、その分までの債務負担行為を今年度中に定めするという形のものですので、契約ができましたら平成３０年度中に始まるという形のものです。","id":"exchange-013"}]},{"id":"topic-03","title":"第９０号議案、第二戸越幹線整備工事（下水道本管立坑整備）請負契約の変更","agenda":"第９０号議案、第二戸越幹線整備工事（下水道本管立坑整備）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの説明ですと、変更理由はシールドマシーンの到達部を補強する必要があるということですけれども、資料に記載してある変更内容は、どういうものなのか、どういう状況があって補強する必要が生じたのか、もう少し具体的にご説明いただきたいと思います。","respondent":"持田河川下水道課長","answer":"そういった中で、今年の７月に、第一三共の土地について譲渡の時期も決まりましたので、それにあわせてこの補強タイプのセグメントに変えまして、下流部にシールドマシンが到達しても構造的に大丈夫なような形に変更した。そういった理由により変更を行う案件です。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、あそこの公園は、山になって高いですね。この深さ約４０ｍというのは、路面から４０ｍ掘るということですか。そういうことでいいのでしょうか。","respondent":"持田河川下水道課長","answer":"そのとおりでございまして、公園のところを少し掘削をして１ｍほど下げた基盤面から４０ｍ、これから掘っていくです。","id":"exchange-015"}]},{"id":"topic-04","title":"平成３０年請願第２０号、国に対し「消費税増税中止を求める意見書」の提出を求める請願","agenda":"平成３０年請願第２０号、国に対し「消費税増税中止を求める意見書」の提出を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"委員長が冒頭説明されたとおりだと思います。１０％にすれば、消費不況が一層厳しくなることは明らかですので、消費税自体の是非ではなく、請願にあるとおり、来年１０月の消費税１０％は中止してほしいと、この１点で議論を通じて一致点が見出せたらと思いますので、各委員の率直なご意見をお伺いできたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"意見","question":"やはり、現在の深刻な財政難の中で、少子高齢化に伴い、増え続けている社会保障費の財源確保のため１０％にするというところです。ただ、少子高齢化に対応するための増税は、私は当然それは必要なのではないかと考えています。国も軽減税率制度、少しややこしい部分もありますけれども、そういった制度も導入していただきながら、１０％は当然必要ではないのかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから、品川・生活者ネットワークは、消費税という制度自体には必ずしも反対ではない。さきほど、中塚委員の発言でありましたけれども、消費税そのものへの反対意見ではなくて、今回の１０％引き上げへの中止を求める意見書というのは、区民のそういう声を代弁する区議会としてはあってもいいのではないかというふうに品川・生活者ネットワークは考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"医療費が上昇しているから何とかしなければいけないと一方で言われているわけですから、この辺はしっかりやっていただきたいという思いの中で、その財源はどこだと言ったら、やはりどこかで確保していかなければいけないことだと思っていますので、８％が１０％になるというのは、私はやむを得ない。それから、委員長、今回は理事者に何も聞いてはいけないのですか。","respondent":"伊藤委員長","answer":"そんなことはありません。例えば、現状の方向性であるとか、制度の考え方などについては、当然、聞いてくださって結構です。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問","question":"わかりました。それが国の役割だと思っています。これは、平成３１年度の予算には載っていなければいけないことだと思いますし、むしろ平成３０年度予算ですでに準備をしていかなければいけない段階なので、補正なり何なりを組んででも積極的に行う必要性があるものはやるべきだと思っているのですけれども、その辺について行政側としてはどうお考えなのでしょうか。","respondent":"品川財政課長","answer":"過去を見れば、いろいろと対策も打っているというような状況もありますけれども、現時点で具体的にどのような対策というのは、まだまだとることは難しいかというふうには考えております。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"たしか品川区は商店街連合会を通して、地元の商店街を通して、どうしますかなどという、そういう話はちらっとされている、動き出しているのは出しているので、さっき言ったレジのシステム系を変えると、普通の飲食店のものは３００万円ぐらいかかるという話も漏れ聞いているので、さらに言うのであれば、今度、国がこの税率を上げたときに、クレジットカードを推進すると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、今、日本の国の借金は１,０７０兆円を超えて、本当に財政再建しなければいけない時期に来ています。私は、それだけは避けるべきではないかといつも思っております。今回、タイミングが悪い消費税増税中止を求める意見というのはわかりますけれども、国の将来、次の世代のことを考えたら、消費税増税はやむを得ないというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"一方で、やはり事業主にとっては大きな負担が生じるわけですから、そこにも目を向けていかなければいけないということで、ここは理事者に確認をさせていただきたいのですけれども、既に国では２０１６年度から軽減税率の対策補助金を創設しておりまして、レジの導入とか買い替え、システム改修などへの支援をしておりますが、区の中でこういうことの周知はどこでされているのか、また今現在。","respondent":"伊東税務課長","answer":"区といいますか、これは税務署のほうで、さまざまな機会を捉えて、各種団体、税関係の団体とかに軽減税率の話ですとか、先ほどのレジの改修費用等の補助金の関係の話ですとかを行い進めているというふうに聞いております。","id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"消費税は大事な財源でありますし、年金、医療、介護はもとより、これから進めていく幼児教育の無償化や、また、給付型の奨学金の大事な財源にもなっていくわけでありますから、ここで消費税が上がることがとまってしまったら、財源が確保できない、いくべきところに給付がいかないという、そういう事態にもなりかねないので、公明党としては、この消費税の１０％というのは、上げた上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"それぞれご意見ありがとうございました。消費税そのものの捉え方については、なかなか一致点を見出すというのは、今のご意見を聞く限り難しいのかなと私も思いました。単に財源が足りないイコール消費税増税では決してないだろうと考えています。ただ、皆さんのご意見を伺う中で、この厳しい経済の中で１０％にしてよいのかというところでは、さまざまな一致点はあるのではないかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"そんなにお金がないなら、どこかで経費を削減するとか、そういうことをやりつつ、法律をつくっている議員の皆さんも、自分たちの給与、ボーナスなどを削減した上で、国民に理解を求めるというのならわかるのですけれども、片やじゃぶじゃぶお金を使っておいて、片や赤ちゃんから寝たきりのご老人の方まで全員に負担のある消費税からとっていくというのは、私は大半の国民には理解されないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"なので、やっぱりタイミングの問題とか、もっとほかに財源はないのかというようなことも考え併せた上で、社会保障の財源確保について結論を出すべきだと思いますので、そういう意味でも、今回のこの８％から１０％への増税というのは、一地方自治体の議会として、区民生活を鑑みた場合に、中止を求める意見書というのは妥当性があるのではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"中塚委員","kind":"意見","question":"本日結論を出すということと、一言述べますけれども、消費税そのものについては一致していないと思いますけれども、この不景気の中で、来年１０月に１０％に引き上げるべきではないというのは、多くの皆さんの共通する考えだと思いますので、その点をもって意見書を出したいと思います。結論としては、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本日結論を出すということで、この請願に関しては不採択でお願いします。ただ、その政府で埋めきれない部分は、ぜひ品川区も緊急経済対策をしっかり打ち出して、いろいろな所管に分かれるかと思いますが、そこはしっかりとやって区民がマイナスにならないよう、不利益を被ることがないようにフォローをしていただきたいということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、本日結論を出すということと、先ほども申し上げましたが、国の借金、また、福祉を拡大していくためには、次世代の子どもや孫たちにツケを回してはいけないということを思えば、中止するという意見書には反対をします。本当に大半の国民にとってかなりの負担になると思いますが、そこは理解していただきたいというふうに思います。今回の請願に関しては、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"繰り返しになりますけれども、消費税そのものへの反対の意見書ということではなく、今回の消費税増税中止を求める意見書ということであれば、意見の中身はまた考える必要はあるかと思いますけれども、今の時点で区議会として意見書を出すということはありではないかというふうに思いますので、今日結論を出すということで、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そこには高齢の入居者がいらっしゃる中で、会社ががらっと変わってやり方や経営方針が変わってしまうということは危惧する部分なので、やはりしっかりと指導などを行う中で指定管理を継続していくという流れを、私の頭の中で考えているのですが、それはそういう感じなのですか。私の会派、民主党時代からずっと要望していたのですが、労務監査というのもたしか今、試行的やられていると思います。","respondent":"柏原企画調整課長","answer":"そのことによって区のセルフチェック以外で外部のチェックが入るということで、ほかの外部チェックについても今検討しているところですが、そういったものを入れながら、公平性を担保していきたいと思っているところです。","id":"exchange-033"},{"speaker":"いながわ委員","kind":"質問・要望","question":"しっかりそういうようなものが機能して、しっかりとした指定管理者の管理をしていただき、あと、創意工夫のある自主事業の実施を妨げると資料に書いてあるのですけれども、品川区がＡをやってくださいと、Ｂはやってはだめですよ、こういう事業はやってはだめですよと言えば、創意工夫を阻害するとか、妨げるという話なのですけれども、やはり指定管理制度全体を考えたら、独自性とか自主性、創意工夫、創造。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"指定管理者制度について、現状の何を課題と捉え、どこが課題と考えているのかをご説明いただきたいと思います。冒頭の説明で、いわゆるガイドラインに沿うという説明だったのでしょうか、指針を検討しているとの説明がありましたけれども、この指針というのは、現在は非公開だけれども、公開を行うということでよろしいのか、そこについてもご説明いただきたいと思います。","respondent":"柏原企画調整課長","answer":"課題といいますか、認識といたしましては、指定管理者制度は、平成１７年以降行ってきているところです。当時は管理委託のところから引き継ぎで指定管理に移っていったという状況であります。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"チェックのあり方について、外部によるチェックを含めて今検討しているということですけれども、指定管理者制度の課題の１つに、議会に議決を求める際の資料や、また区民への情報公開も課題として捉えていただいて、検討を進めていただきたいと思いますけれども、この点について、お伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"前段のほうのご質問については、今後の資料等のあり方であるとか、選定の透明性といったところを含めて、どういった形の資料のあり方がいいのか、今、検討していますので、どういった形がいいかは引き続き検討させていただければと考えています。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"前半の今後の課題ですけれども、情報公開については強く求めておきたいと思います。そのためにも、陳情にあるとおり制度をよく理解し、制度運用できるよう人材の育成は必要な視点だと思いますけれども、この指定管理者制度の改善に向けた制度設計や人材育成について、今後どのように行っていくのか、重なる部分もありますけれども、改めていかがでしょうか。","respondent":"柏原企画調整課長","answer":"今後の指定管理の考え方の部分ですけれども、先ほどと重なる部分はありますが、例えば、募集をかけたときに一社しか来ないような場面で、これはやはり事業の困難性であったりとか、特殊性というのはどうしてもありますので。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区がどのレベルを求めていてというのがもう少し明瞭でないと、確かに法人としては手が挙げにくいのではないかと思いますが、その辺の今の現状、上限額も決めずに公募をして、指針も示さずに公募していて、それで自由な発想を阻害しないようにそうしているという、何かちょっとその辺が、何をどう目指しているのかがよくわからないので、その辺をもう少し詳しく手順、どういうふうな募集の仕方をして。","respondent":"柏原企画調整課長","answer":"説明会等での質問のやりとりなどがありますので、公開で質問が来たことに対しては、それをもとにしながら、その場で答える、返事を出す、いずれにしても一社だけに返すのではなくて、全てに対して、こういう質問にこう答えたということを流したりしておりますので。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"少しはわかりました。そうなると、やっぱりそちらのほうが応募しやすいというのは現実的にあるのです。もちろん安定的な事業を行うというためには、同じ法人がという面もあるかもしれませんけれども、競争原理とか、そういうことを考えると、いろいろな法人が手を挙げやすい、その中で品川区がどういうふうに選定していくかということがすごくまた品川区としての力量も求められるのではないかと思います。","respondent":"柏原企画調整課長","answer":"そういった中で、先ほどの議論にもありましたけれども、その内容や考え方などを入れながら、区の指定管理者制度をどういった形でお示しできるかというのは十分検討しながらやっていきたいと思います。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことについて区としてもスキルを上げていかなければいけないと思うのです。後の評価ということと、まず最初の意欲ある事業者が手を挙げやすいような制度の運用の仕方というのは、ぜひ検討していっていただきたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"意見","question":"本日結論を出すということでお願いします。今回のこの陳情は、区として、今現在、やるべきことをやっておられると思いますので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"新妻副委員長","kind":"意見","question":"本日結論を出すでお願いいたします。ただいまご説明をいただきましたとおり、現在、しっかりやっていただいているということとともに、指針等についてもしっかりと検討されているというお話がございましたので、そのことも含めて、この陳情は不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問","question":"本日結論を出すということと、趣旨採択でお願いします。その理由は、福祉施設の継続性は大事だと思います。一方で、新しい法人の応募により、新しい風を入れて活性化させるという点もあわせて大事だと思います。その手法はさまざまありますが、陳情にある制度改善や研修などの必要性について、その趣旨は理解できますので、趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本日結論を出すで、不採択です。先ほど質問したように、指定管理者制度に係る基本方針など、いろいろあろうかと思いますが、今度新たにお考えの社会保険労務士を入れた労務管理は、実現に向けてしっかりと検討していくという説明がありますので、しっかりそれは公平性の担保がなされるよう、行っていただきたいと思います。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問・要望","question":"陳情の趣旨は、ガイドラインの作成と人材研修の実施を求めるということですが、区として、さまざま取り組んでいる中で、こういう陳情が出たということは、区民、また事業者から見えにくいため指摘されてたと思いますので、今後とも区民や事業者にわかりやすい制度に向けて、明確なガイドライン等を作成したり、いろいろと努力して、品川区の指定管理者制度をよりよいものにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出すということと、採択を主張したいと思います。内部の指針があるということは不勉強で今日知りました。一般的には品川区指定管理者制度活用に係る基本方針しか見れないわけです。指定管理者がどういうふうな事業者かは、区民のサービスを利用する人にとってはとても重要なことだというふうに思いますので、それを区議会から区に求めるというこの陳情については採択が妥当ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"確かにこの文章のとおりでなくても、例えば、指針でもいいわけですし、とりあえずはガイドラインなり指針の作成ということで、人材研修というのは、それに伴うものですから、この文章のとおりではないという意味では、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-05","title":"第８５号議案、（仮称）品川区立障害児者総合支援施設新築工事請負契約の変更","agenda":"第８５号議案、（仮称）品川区立障害児者総合支援施設新築工事請負契約の変更","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"それと、この（仮称）品川区立障害児者総合支援施設新築工事に関しては、地中埋設物を撤去しなければいけないため、その分、費用がかさんでしまうというのは、当初見込んではなかったので、その追加費用は全然問題ないと思うのですが、それ以外の躯体ではない（仮称）品川区立障害児者総合支援施設給排水衛生設備等に関しても、多いものだと５００万円の費用がプラスになっているのでけれども。","respondent":"小林施設整備課長、飛田障害者施策推進担当課長","answer":"１つ目につきましては、所管課の障害者福祉課のほうで利用者向けに、１１月１５日に、２回に分けて説明会を開いたということです。説明会では、利用者の方から代替施設は早めに決めてほしいという話をいただきましたので、こちらのほうでも早急に動きまして、現在、こみゅにてぃぷらざ八潮３階の講習室で話を進めているところです。","id":"exchange-048"},{"speaker":"いながわ委員","kind":"質問・要望","question":"よく理解できました。それでも、もしかしたらご納得されない方もいらっしゃるかもしれないですが、そこは根気よく、品川区の施策としてやっているものですので、理解を求めるよう頑張っていただきたいというと言い方はおかしいですけれども、ご努力をしていただければと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"今回の工事の延伸に伴う契約金額の変更ということですが、第４回会定例会に契約議案が提出されたわけですけれども、いつの時点で金額の変更が必要だと判断されたのか伺いたいと思います。いつの時点で４月の開設が延び、契約金額を変更するという判断に至ったのか、その状況を伺いたいと思います。","respondent":"小林施設整備課長","answer":"今回の変更理由における、近隣配慮、これは振動、騒音、いろいろな要望等、それから、地中障害物関係は、工事の前半のほうにありましたので、そこにかかった時間は当然あったのですけれども、その間、何度も建築工事業者、電気工事業者、空調工事業者。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"経理課か、障害者福祉課か、どちらに聞いていいのかわからないのですけれども、契約議案として上程するにあたり追加の金額が出てくる関係もあるのでいろいろ精査しなければならないでしょうが、１０月上旬に一定の判断をしたのであれば、速やかに議会や利用者の保護者に説明する必要があったのではないかと思うのですけれども、現時点で振り返ってみてどう思われるか、ご見解を伺いたいと思います。","respondent":"小林施設整備課長","answer":"今回、４カ月の延伸ということで、業者も含めて打ち合わせが済んだ後、先ほどのご質問にありましたけれども、人件費にかかわる経費とか、そういうものを出していって、今度は、そちらの経費が妥当なのかをまた精査をして、いろいろそういう準備を行い。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問","question":"経費などの積算もあるでしょうから、固まった時点で変更の議案を出すということはよくわかるのですけれども、４月の開設が間に合わないということ自体は、１０月上旬の判断で、利用者はもちろん、議会にも示すことができたと思うのです。その点を振り返ってみて、やはり、直接利用される方へのとりわけ丁寧な説明が必要だったのではないかと思うのですけれども、その点はいかがでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"区民の方にも、もちろん早く説明しないといけないというところで、早急にどういうふうに周知をしようかと考え、今回、１１月１日の広報しながわに説明会の開催を掲載し、１１月１５日に説明会を２回に分けて実施したところです。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"とりわけ利用者にとっては、４月から、どこに行くのかという問題にかかわってきますので、ほかの施設とは少し性格が変わってくると思いますので、今後はしっかりと利用者への丁寧な説明を強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"吉田委員","kind":"確認","question":"気になるのが、本当に今、この４カ月延伸ということで、きちんとでき上がるのだろうか。今度、ここでこの契約を通すというのは、本当に責任があると思うのです。４カ月延伸の契約できちんと立ち上がるということを確認しないといけないかというふうに思っております。１０月に判断されたということですけれども、今は１２月ですから、それからまた進んでいる部分があるわけですね。それをお聞きします。","respondent":"小林施設整備課長","answer":"今現在、そういう状況で進めていて、その状況で、先ほど言った会議を何回も開いて、今後、どの程度の工期が必要で、今言った４カ月、これは業者からも言われている数字です。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"決算特別委員会の中でも、危険負担条項というのですか、もし不測な事態が起きた場合は区が負担するという契約だということは確認しましたけれども、そのほかに、やっぱりそういう報告がきちんと、これはもう工程管理上、現時点では難しいのではないかという報告は、事業者のほうが上げるべきという条項も入っているのではないかと思うのですけれども、その辺、どうなのでしょうか。","respondent":"小林施設整備課長","answer":"徹夜だとか突貫工事で工事を進めていくには、少し危ないのかなというところも論議をしながら、定例会議で話し合いをして、１０月の上旬にいろいろと検討していったところ、いろいろやっていったのですけれども、最終的に一定の判断を下したです。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問","question":"だから、それをきちんと管理していく、ここまで進む予定だったけれども、今はここまでしかできていないということを、もう少し細かくやるべきだったのではないですかと、それがきちんとされていたのですかということなのです。私も本当に素人なのでわからないのですけれども、施工管理にはそういうものが入るのではないですか。だから、それがどう機能していたのでしょうかということなのです。","respondent":"小林施設整備課長","answer":"それが初めの段階でそれを取り戻せるよう打ち合わせをし、努力をしたところです。ただ、先ほども言いましたが、１０月上旬に、このままいくと事故にもつながる可能性もあるので、一定の判断、本当に苦渋の決断をし、４カ月の延長となったところです。","id":"exchange-056"},{"speaker":"吉田委員","kind":"意見","question":"突貫工事で何が何でも２月竣工を目指すべきではないと判断されたのも理解できるのです。だけど、それがなぜ、実際に細かくそれだけ打ち合わせをしていて、工程表だと、本来ここだけれども、今はここまでしかいっていないという現実はそこで突きつけられるわけですよね。事情はよくわかります。そして今回、これで大丈夫という判断をされたのかがよくわからないので、その辺をもう１回だけ。","respondent":"小林施設整備課長","answer":"そういう努力を業者がやっているところも我々は見ておりますので、そういうところを見て、ずっと進めていたところなのですけれども、繰り返しの答弁で申しわけございませんが、１０月の上旬に、苦渋の選択をしたです。理由はそういうものもいろいろあります。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことがないように、工程管理のところも、現実的なところを見据えながら、きちんとされていかないと、結果として、事業者への努力を求めながら、結局こういうふうに突然延伸ということになってしまったので、その辺は今後はそういうことがないように、ぜひ工程管理をきちんと、そのための工程管理ではないのかというのがどうしても疑問が残ってしまいますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"須貝委員","kind":"質問","question":"本体工事もおそらくこういうわけで、今、工事を止めなければいけないということは、社内でもきっと話が通っていると思うので、その中で、４カ月ぐらいなら、民間ではこういう工事費が増額するということは、私はないと思うのです。区の契約条項には、工期が延びた場合には、その分、増額しなければいけないというルールがあるのですか。その点についてお聞かせください。","respondent":"小林施設整備課長","answer":"そういうことを考えて、４カ月延びることによる人件費、あと、仮囲いだとか、積み上げの仮設だとかあるのですけれども、そういった４カ月分の経費を見込んで、今回、変更を提案したです。","id":"exchange-059"},{"speaker":"須貝委員","kind":"質問・要望","question":"いろいろな皆さんからご意見があったと思うのですが、トラブルなり何かあったときは、仮に延伸するなら延伸するで先に言って、そして、いや、実はこういうわけで早くなりましたと言ったほうが影響が少なかったのではないかと私は思うので、今回も事故のないように工事を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ご説明ありがとうございました。延伸になったということで、工程表については、やはりそのとおりになかなかいかないと私は思っています。そこで１点だけ確認ですけれども、先ほど、週１回、業者との打ち合わせがあるとおっしゃられたのですが、参加しているのは、ジョイントベンチャーの現場監督、もしくは下請け、孫請けなのかどうか、お聞きしたいと思います。","respondent":"小林施設整備課長","answer":"参加する業者につきましては、建設共同企業体、建築でいくと３つの会社が共同でやっているのですが、今回はナカノフドー建設の所長、副所長、場合によっては専門の工事担当者、いろいろその中でも分かれておりますので、基本的には所長と副所長は入っています。","id":"exchange-061"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。１つだけ確認をさせていただきたいのですが、当初、２月２８日に工期終了で４月開園という予定になっておりました。今回は、６月２８日に工期終了で１０月開園に変更となったということなのですけれども、この間の期間が、当初は工期終了から１カ月間ですが、今回、３カ月間あいている理由は何でしょうか。","respondent":"小林施設整備課長","answer":"そちらの仕様説明をまずその後にします。それと、その設備の使い方の練習をしたいという要望も上がってきましたので、今回そういうものも見て、３カ月後の１０月という形をとらせていただいたところです。","id":"exchange-062"},{"speaker":"新妻副委員長","kind":"質問","question":"当初は１カ月しかなかったということはそういうことをしないということですか。","respondent":"小林施設整備課長","answer":"その後の２カ月については、そういう機器の説明、それと慣らし、もう１カ月については、向こうの運営事業者の職員が１０月にオープンに向けてのレッスンというか、研修というか、そういう形になってきましたので、本来は２月のところの中でおさめようと思っていたのですけれども。","id":"exchange-063"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。とにかく利用者の方が一番心配されているところかと思いますので、これ以上の工期の延びがないということは担保されていることとは思いますけれども、またそこも確認をしていただきながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"必要な工事ですので賛成いたしますが、一言、まず利用者への丁寧な説明はしていただきたいということと、もちろん今回も工期をしっかり守っていただきたいと思いますが、やはり工事は安全が第一ですので、そこも強調した上で賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、その辺の区としての責任はとても重いものですし、こういう工期の契約を議会として議決をするというのも議会としての責任もとても重いわけですから、今回、賛成いたしますけれども、その辺は区として工程管理を含めてきちんとしていただきたいということを、あえて要望としてつけ加えさせていただいて、賛成といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"工事を管理する施設整備課の出席を求める内容の陳情ですけれども、さまざまな疑問や質問に答えるためには、事業の日程が変更される理由とあわせて、工事内容についてもさまざま質問に答えるために、施設整備課であったり、必要な職員の出席は必要だったのではないかと思うのですけれども、その点、いかがでしょうか。","respondent":"小林施設整備課長","answer":"事前に障害者福祉課と打ち合わせを何回も設けているのですけれども、その際に情報共有を図って、所管でも内容的なものは把握しておりますので、あくまでも今回のところについては、施設を利用する方への説明会ということでありましたので。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"そういう意味では、今回の障害児者総合支援施設に限らず、さまざま工事の説明をすることがあると思いますけれども、事業を進める担当課と、あわせて工事に責任を負う所管が出席をするというのは必要な対応ではないかと思うのですけれども、いかがかということと、今後、この陳情にあるように、説明会を開催すべきと思いますけれども、いかがでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"ですので、今、骨組みのところはでき上がったところという説明をしました。本当に１０月には開設できるのかというところで、そちらには１０月開設を目指して今頑張っているところですという説明をしております。","id":"exchange-068"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺の見解を教えていただきたいと思いますが、いかがでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"実際に質問票を出された方としては、たしか１５名程度いたのですけれども、そういうところでまた丁寧に対応していきたいと考えております。","id":"exchange-069"},{"speaker":"吉田委員","kind":"質問","question":"施設整備課が参加する説明会は行われないということなのでしょうか。その辺をお願いします。","respondent":"飛田障害者施策推進担当課長","answer":"どちらかというと、やっぱりこの施設の運営面について皆さんから聞きたいというお声をいっぱいいただいているので、そちらのほうに時間をかけたいと考えております。今のところは、施設整備課からの説明は時間の関係でもできないかと考えております。","id":"exchange-070"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。今後のこともありますし、確かにこういう視点の説明も必要だということを、私もこの陳情を見て気がついたというようなところもありますし、ぜひそれは検討の方向で考えていただきたいと思います。工事という以上、どうしても遅れとかそういうこともありますし、それは妥当な理由であれば皆さん納得するわけです。もし何か施設整備課のほうで見解があればお伺いいたします。","respondent":"小林施設整備課長","answer":"先ほども所管のほうでお話ししましたけれども、今回の説明が利用者のための説明ということと、なおかつ、１時間以上、質疑応答を行ったということと、さらに、その場で質問ができなかった方、しづらかった方につきましては、質問票ということで丁寧な対応を行っているところです。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのときに、工事の専門的な説明がその場ですぐきちんとできるという人が同席する説明会について、ぜひ今後検討していただきたいと思います。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど質問したのですけれども、確認したいのですけれども、例えば、騒音に伴う近隣配慮とこの陳情に書いてある1)と、車両出入口の縮小の2)、これは要するに、近隣への配慮なわけですね。だって、工事をしながら説明しているというのはおかしな話ですから、このニュアンスからいくと。そうなってくると、また延伸する可能性も出てくるという考えも１つあるという認識でいいのでしょうか。","respondent":"小林施設整備課長","answer":"やはり、二手から工事をやるところ、１つのところからやり始めたものですから、施工の方法だとか手順だとか、全て見直しを行い、先ほどの打ち合わせを何回も繰り返して、工法から手順から全てを変えて１つのところからやって。","id":"exchange-073"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。今もさまざまありましたけれども、利用者の方がまず第一ですけれども、近隣の方々への配慮というのも大事かと思います。１１月１５日の説明会は、大きくは利用者の方のためのものであったというふうに認識をしているのですけれども、工事期間が延びるわけですので、近隣の方々への配慮ということでご説明は今後どのようにされていくのかというところを１点だけ確認をさせてください。","respondent":"小林施設整備課長","answer":"今回、第８５議案から第８８号議案を提案し、議決いただきましたので、その後、契約という形で変更契約を結びます。変更契約後に速やかに近隣を回って、これは１軒１軒訪問して、個別対応による説明をしていこうという考えを持っています。","id":"exchange-074"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。その中で、例えば地元町会、または団体なりからまとまった形での説明会の実施についても、ご要望が出るようであれば、それはまたしっかりおこたえいただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"新妻副委員長","kind":"確認","question":"本日結論を出すでお願いします。結論としては不採択です。丁寧な説明をしていただいているということも確認できましたけれども、また今後も引き続き丁寧な説明をお願いして、不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"中塚委員","kind":"意見","question":"本日結論を出すということと、採択でお願いいたします。理由といたしましては、とりわけ説明会のあり方ですけれども、今回のご担当となる障害者福祉課の説明はもちろんのこと、やはり工事、その方法、スケジュールについても質疑があることは十分考えられますので、両方の出席が必要だと思います。よって、陳情の要旨や理由等に賛同しますので、採択ということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"いながわ委員","kind":"意見","question":"結論を出すということで、不採択。理由は、先ほど言った説明をするというのは当然やるべきことなので、それがどうこうというよりは、むしろ１日も早く、安全にスムーズに竣工していただくことを祈っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"須貝委員","kind":"質問・要望","question":"本日結論を出すということと、今回このような陳情が出ていますが、本当に珍しいケースだと思います。今後、区民の信頼を損なうことがないように努めていただきたいと思います。この件に関しては、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどのいながわ委員からご質問がありましたけれども、やっぱり今後の工事の適切な工程管理を区に求めるというのも陳情内容に入っております。ぜひその辺、工事管理の所管課主催、所管課主催と限らなくてもいいという気もしますが、所管課が入った説明会の実施と、適切な工程管理ということは、ぜひ区に求めていきたいと思いますので、この陳情については採択をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"}]},{"id":"topic-06","title":"「」を聴取いたします。 初めに、(1)専決処分の報告","agenda":"「」を聴取いたします。 初めに、(1)専決処分の報告","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ、損害賠償額の算定といいますか、決め方について伺いたいのですけれども、車の場合は、保険の中でいろいろ金額が決まっていくのかと思うのですけれども、今回のような、ブロック塀とエアコンの室外機等の場合は、修理費と書いてありますが、実際は新しく設置するための撤去費や設置費等なのか、この損害賠償額の決定の経過についてご説明いただきたいと思います。","respondent":"島袋人権啓発課長","answer":"こちらは、区の契約しております保険会社との内容に基づきまして確定させていただいたものでございまして、修理費とありますが、撤去費、新たな工事費など全てのものを含んです。","id":"exchange-082"},{"speaker":"須貝委員","kind":"質問・要望","question":"前回も申し上げたのですけれども、皆さん、忙しいのだから、車に安全装置をつけて、バックして物に当たりそうだったらとまる。人にぶつかりそうになったら、そのときもとまる。やっぱりそういうふうに安全にお金をかけて、もし区民に万が一のことがあったら、ご本人も、ぶつけたほうも大変です。だから、そういう工夫をやっていく時期に来たのではないかと思いますので、要望だけいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そもそも前にも言いましたけれども、保険を使うということは保険料が上がるということですから、それは人権啓発課の所有の車だけが上がるのか、それとも品川区の庁有車、リース以外の品川区が保有している車全部の保険が上がるのか。そういう部分も含めて、今後やっぱり全体的に考えていかなければいけないと思うのですが、車のリースをどうこうではなくて、保険に関してはわかる範囲で教えていただきたい。","respondent":"立木経理課長","answer":"リースか購入かという部分に関しましては、どういったものが一番いいのかというのは、いろいろ研究している最中でございまして、現在、区長車、議長車、それから新たに入りました電気自動車はリースで行っておりますが、耐用年数や金額などの兼ね合いの中で、その都度その都度。","id":"exchange-084"},{"speaker":"いながわ委員","kind":"意見","question":"今後、事故を起こしたら、例えば掛け金が１００万円上がります。でも、それは１回起こそうが、２回起こそうが１００万円増えて終わりなのか、それともどんどん上がっていくのか、その仕組みがわからないのですが、検討していただければと思います。事故を起こした方も、何カ月か運転をしてはだめですという話なのか、それとも１回、教習所に行ってもらうのか、いろいろ考え方もあると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"}]},{"id":"topic-07","title":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"質問の項目を正確に覚えていないのですけれども、本日の陳情の審査にもかかわるところなのですが、本多議員の指定管理のご質問で、モニタリングに関する部分だったと思います。その試行というのが具体的に、今、どのように行われていて、現段階の検討段階がどの辺まで来ているのかとかなどについてもう少し詳しいご説明があればしていただきたいという質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうです。検討の中にそれが入っているのだと思うのですけれども、客観性を担保するため社会保険労務士と公認会計士へのモニタリングの委託の検討が試行的に進んでいるということだったのですが、その検討段階、どういうふうに検討されているのかということと、現在どの辺まで検討が進んでいるのか。できることなら、いつぐらいから本格実施になるのかとかまでわかれば教えていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/643576?Template=document&Id=2124#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":58974,"voices":255}},{"id":"h30-20181211-6","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"区民委員会","time":"午前１０時００分～午後 ２時０９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"だから、それを大前提に行政も事業計画の中に社会実験であるとか、チャレンジというのは冒頭で打ち出すべきぐらいなものとまず考えますが、その辺のお考え。それと、そうやっていく中で第一歩が踏み出せれば、２回目あるいは２年目・３年目に改善していくのが世の習いだと思うのです。最初からパーフェクトを求める事業はおそらく民間も含めて易しいことではないと思うのです。その辺のお考えを２つ目に質問。","respondent":"立川文化観光課長","answer":"行政の立ち位置ですけれども、一番行政が重要だなというのは、さまざまな主体を結びつける役割、そこは信頼していただけていると自負しておりますので、行政としましてはさまざまな団体が、団体同士ではなかなか交流が進まないところを、それをまずくっつける場を設けるとか。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問・要望","question":"品川区も広いですから、多くのイベントやっています、近隣に同じ人がかぶればノウハウは共有できるのですが、もっと全区的にノウハウだとかおもしろみのある企画をほかで生かすのが、多分、行政が役割として求められている、「つなぐ役割」、情報センターであり総合マネジメントの部分だと思うのですが、行政マンだけがやれるかと言うと、多分物理的にとか人手的にも難しいと思うので。","respondent":"立川文化観光課長","answer":"定評のある方は全国各地の自治体のアドバイスをしていますので、観光や文化芸術・スポーツといった分野でも施策についてご意見、またまち場のいろいろな課題を解決するためにご意見をいただけるような仕組みを今後検討・研究していく必要があるのかなと考えております。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"でも、受け手からしたら、１位は何だろうとか上位の方に関心が行くではないですか。それはときによってテーマによって違っていいと思いますし。容姿に限らず、例えば笑顔が素敵だとか、好感度、今は動画の時代ですから、「ようこそ品川へ」というテーマで３０秒コメントしてくださいとか、何か感じいいねとか、そういうのを総合的に判断する「ミス品川」でもいいし、「何とか品川」でもいいのです。","respondent":"立川文化観光課長","answer":"ただ、遊び心は、タイトルとかそういったもので強調できると思いますので、事業によってはその辺を発信力として活用してやっていくというのは、大変貴重なご意見だと考えています。","id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"やり方はほかにもあるのですけれども、伝わるかどうか。正しいことを言っていても難しすぎて伝わらなかったら意味がないし、人と人なので、伝わり方の手段としてやっていったらどうかと思います。それも１つかなと思います。前も伺ったことあるのですが、品川区が何かしらでもっと上位に行ってほしいなと。これは多分オール品川で気持ちが１つになれると思うのです。それを最後に教えてください。","respondent":"立川文化観光課長","answer":"一方で、その辺は港区や中央区、渋谷区、新宿区、実際何もしなくても人が集まるような地域と品川区が張り合うようなことはしたくないと考えております。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"意見","question":"今まさにご答弁いただいたことに魅力を感じます。大田区に対しての敬意があって、ライバルという。今聞いた中でも具体的な工場めぐりだとか、視察と同じ趣旨ですよね。そう言い合える課長同士の連携で、やはり連携ができているからこそライバルと言えたり、そういうのを意識されるってとても大事なことだと改めて思いましたので、またそういう情報があったらぜひお知らせいただけるといいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"この一覧表があるから私もわかったのですけれども。しかも、これ見ていると、平成二十四、五年ごろから平成２８年ごろにかけて各区ともいろいろな計画を出されている。全然勉強できていないですから、素朴な疑問として思ってしまったのですけれども、そこら辺を解説いただければありがたいなと。","respondent":"立川文化観光課長","answer":"区ではショートトリップと言っていますが、その辺も、いわゆる従来型の観光ではなくて日常生活の中にそういった観光を意識していこうといったことが平成２０年前後から各区で広がってきたと捉えています。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう住民の要望なり、あるいは口に出して言う要望ではなくても、何となくそういう雰囲気が平成２０年ごろからできていったという、実態としてあったということですかね。","respondent":"立川文化観光課長","answer":"一覧表にお示ししました、いわゆる各区の観光関係のビジョンやプランの作成年度、改訂して新しい年度のところもありますけれども、ざっと見ますと平成２０年ごろから始まっていますので、そういったまち場のご意見であるとか、議会からの要望だとか。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、外から人を呼び込む観光というよりは、住んでいる人に楽しんでもらう、気持ちよくなってもらうというか、そういう趣旨の観光ということですか。","respondent":"立川文化観光課長","answer":"ここ数年外国人旅行者が増えておりますので、そういった方々にもまち場に出たときにまちの資源、日常生活などに触れてもらうことで楽しんでもらう、そういったところで都市型観光は展開されております。","id":"exchange-008"},{"speaker":"おくの委員","kind":"意見","question":"例えば、品川区としては、今のご説明では、日常的なものが、住民のためのものもあるし、それから、外から来る方のため、両方兼ねているのだというお話ですけれども、品川区としては目標というか、平成２８年策定の都市型観光プランの目標としては、これだけ外側から呼び込みたいとか、持たれているわけですよね。","respondent":"立川文化観光課長","answer":"平成２８年に都市型観光プランをつくりまして、観光のコンセプト・目標についてもう一度ご説明いたします。それまでも観光に関するプランはありまして、平成２８年に改訂をしています。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"平成２８年からまだ２年ですが、効果はこれぐらい上がったとか、こういう流れになってきたよとかいうのはあるのでしょうか、ないならないで仕方がないなと思うのですが、まだ２年たっていないわけですから。","respondent":"立川文化観光課長","answer":"外国人観光客、シニア世代、こういった方々が具体的なターゲット、マーケットの考え方です。実際に商店街などで聞きますと、やはり日本の商店街自体が物珍しいということで訪れていただける方は増えています。","id":"exchange-010"},{"speaker":"大倉委員","kind":"質問","question":"回遊性を上げていくために、例えば、大井競馬場のイルミネーション、入場料１,８００円は少し高いというお話もあったと思うのですけれども、例えば、そこで終わりではなくて、水族館から大井競馬場に行くとか、大井競馬場終わった後に商店街に行くと楽しめるみたいな、割引とか連携とか、そういうのがうまくできないかなと非常に感じたのですが、そういうようなうまく回遊していく。","respondent":"立川文化観光課長","answer":"そのつなぎ役として行政としてできることがあると思いますので、その辺については検討していきます。","id":"exchange-011"},{"speaker":"大倉委員","kind":"意見","question":"そのためにも、やはり先ほど言った分析とか調査とか、チャレンジしていくところでもしっかりとそのチャレンジがどうだったかということも精査しながら進めていくといいと思うので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論をお伺いするのですが、この資料を今回つくったと思うのですけれども、１番が千代田区、２番が中央区、３番が港区となっていますけれども、この順番の根拠は何ですか。","respondent":"立川文化観光課長","answer":"こちらは行政順ですので、いわゆる市区町村の整理上の順番です。品川区は９番ということで昔から決まっていて、背番号みたいなものです。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"それで、続けてお伺いしますけれども、例えば、個人的な考えでいいのですけれども、いわゆるこの品川区の文化観光課長として答えていただくと、必ず品川区のことが出てしまうと思うのですけれども、今日この都市型観光でほかの区が出ているのであえてお伺いしますが、例えば、課長のご出身はどこだかわからないですけれども、友人なりご親戚の方なりが地方から来たときに、東京観光をしたいと言ったときに。","respondent":"立川文化観光課長","answer":"常々意識しております。区内でお話ししますと、区内においては、八潮にある新幹線の基地です。それから、広町の山手線の基地、区外におきましては、近いところで東京タワーのふもとに行って見上げてもらいます。お金を払って上までは行かないと。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"話を戻しますが、と言いつつ、歴史館の特別展等においても過去やっていたら申しわけないのですけれども、伊藤初代総理大臣のことはあまりやられていないような、今回も明治維新という形で特別展をやられていたけれども、そんなに伊藤さんについてはあまりやっていないと思うのですけれども、大井の人間としてはこれからまた都市型観光の１つとして盛り上げていっていただきたいのですけれども。","respondent":"立川文化観光課長","answer":"過去に取り上げたかどうかはいま確認できないのですけれども、全国的に有名な方ですので、歴史館等と連携して、どういうふうに伊藤博文公を品川の観光資源としてアピールできるかは研究していく必要があると思います。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"今年のいつだかにも伺っているのですが、都市型観光に力を入れている区を幾つか以前教えていただいたと思うのですけれども、それをまた教えてください。","respondent":"立川文化観光課長","answer":"そのとおりの答えができないかもしれないのですけれども、近隣では、港区、大田区、その辺は間違いないです。","id":"exchange-016"},{"speaker":"田中委員","kind":"意見","question":"でも、先ほどあったように、品川区としては、まず住民に地域を楽しんでもらうためにというお話をされていたと思うのですけれども、どちらなのかを聞きたいです。","respondent":"立川文化観光課長","answer":"都市型観光の考え方としましては、その挨拶文にあるとおり、来街者の方に満足していただきたいということがあるのですけれども、ターゲットとしましては、先ほどお話ししたとおり、区民、区内在勤・在学者、または近隣区民、沿線市民。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどあったように、新幹線の基地だったり、中央公園なども電車が通る公園だということで子どもたちにも大人気です。そういうものもあるので、イベントだけを盛り上げていくとかではなくて、ここにも書かれているように、生活文化に根ざした資源という、今ある資源を活用してほしいというのを強く要望したいです。何かあったら一言いただければと思います。","respondent":"立川文化観光課長","answer":"ただいまご指摘のありました、いわゆる生活文化、身近な資源、こちらは大変大切だと。同時に新たな観光資源として区の目玉になるようなものも必要かなと、総合的に施策については推進していきたいと考えております。","id":"exchange-018"},{"speaker":"本多委員長","kind":"質問","question":"私から１点だけ質問させてください。もしないならこれから働きかけしていくのか、その辺だけ簡潔に教えてください。","respondent":"安藤文化スポーツ振興部長","answer":"今の大森貝塚、大井貝塚という名称自体について、今実際に動きがあるかと言うと、特にありません。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"大井という地名は井戸から来ているということで載っていて、違うかもしれないですけれども、逆に大森という地名は、どこから、どういう語源というか来ているのか、わかれば。何で大森貝塚なのという思いがあって。改めて品川区が元祖でいいのですよね。それももっと強く言っていただきたいのと。何で大森という名前がついてしまっているのというのも、まさに委員長と一緒の考えなので。","respondent":"安藤文化スポーツ振興部長","answer":"藤原委員のご質問の中でも、貝墟と貝塚の話ですけれども、かつてお答えしましたとおり、品川区の大森貝塚が正解ではないですけれども、正しい場所です。大森の由来については知識がありませんので、今ここで答えることは難しいです。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/997088?Template=document&Id=2828#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":17951,"voices":57}},{"id":"h30-20181211-7","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"厚生委員会","time":"午前１０時００分～午後 ２時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)「第３期品川区地域福祉計画（素案）」およびパブリックコメントの実施","agenda":"はじめに、(1)「第３期品川区地域福祉計画（素案）」およびパブリックコメントの実施","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ご丁寧な説明ありがとうあります。パブリックコメントの実施についてというところで、地区懇談会をされています。それから、策定委員会が３回行われてきましたけれども、ここで出された意見というのもこの中に紹介もされているところですけれども、これは議事録などは公開されているのでしょうか。そこの点についても教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"ほとんどの地区が支え愛活動会議にお邪魔をして、ご説明または意見交換をさせていただいたところ、その支え愛活動会議につきましては、それを構成するメンバー各地区でそれぞれです。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ありがとうございました。パブリックコメントをただ閲覧して区民の皆さんが意見を言うというのはなかなか難しい部分があるのではないかというふうに思いますので、一般区民、活動に参加している方だけではなく、一般区民に対しての説明会、これを説明していただく機会をぜひつくっていただきたいと思うのですけれども、その点について１つ。","respondent":"大串福祉計画課長","answer":"２点ご質問をいただきました。住民への説明といったところですが、前期だけでも１４回、また、これからもずっと各地区を回らせていただきます。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これからもずっと地域センターごとに懇談会をされるということなのですけれども、その懇談会のところに一般区民もどうぞ参加してくださいという形で、関心のある方は参加をして意見も言えるような、そういう場面をぜひつくっていただきたいと思うのですけれども、この市町村地域福祉計画策定ガイドラインというところにも、やはり策定上の留意事項というところでは、住民参画によって策定される計画と。","respondent":"大串福祉計画課長","answer":"したがって、そこのところに一般区民をといったものは、その支え愛活動会議、あるいは町会長会議のほうでのご判断になってくるところかと思いますし、また、そうした中でお話をするですので、一般の区民の方が入るのは少し難しいというふうに思っております。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だけれども、さまざまないろいろ思いは持っていらっしゃると思うのです。そういうところの声も広く聞くという、こういう計画ができるときというのは一番の機会なので、ぜひ説明会を行っていただきたいと強く要望しておきたいと思います。","respondent":"大串福祉計画課長","answer":"基本的には、この第３期地域福祉計画につきましても、メンバー構成については今現在検討中ですけれども、各会の方、皆様お集まりいただいて、特に重点施策に位置づけているものについての事業の進捗状況をご確認いただき、ご意見をいただきながら。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もし、その推進委員会のメンバーなども、ここに書けるのであれば知らせていただきたいということと、それから、１年間に１回ということなのですけれども、そうしますと、品川区がおおよそのところをまとめて、推進委員会にかけて、ご意見をいただいて、そのご意見をもとにしてまた１年間のまとめをつくるような、そのようなイメージになるのでしょうか。","respondent":"大串福祉計画課長","answer":"この計画は本当に多くの部・課にかかわってくるものですので、そちらと調整しながら、おっしゃるように、我々のほうで一定程度資料をつくらせていただいて、それを委員会にかけさせていただいて、我々のほうからの説明、またご意見。","id":"exchange-005"},{"speaker":"こんの委員","kind":"質問・要望","question":"人と人とのつながりという、その共生社会の中で生まれてくるものというのは、想像できるようで想像できないと言うか、でも、想像しながら、こういった理想に向かっていくという活動であったり、私がそこでいつも思うのは、人と人とのつながりだからこそ、その困っていらっしゃる方にかかわっていこうとする人がかかわりやすい環境をつくっていただきたいなと。そうした考えはいかがでしょうか。","respondent":"大串福祉計画課長","answer":"そうしたところでのちょっとした気づかいであったり、そういったものからまずは始めてみてはどうだろうといったところで、この計画では最初のところを提案させていただいていると、最終的には包括的な相談支援といったところで、行政であったり。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"章は普通、基本目標とか理念とか定義というのは別の章にして、経緯というのは別ではないですか。その辺を丁寧にしていただきたいというのが１つです。いきなり４０ページ、４１ページを見たときに、その体系図との位置関係がどうなっているか、この施策の１）は、この図で見ると、ああ、ここに位置しているのだなというのが、最近の計画はそういうふうにつくっているものではないですか。","respondent":"大串福祉計画課長","answer":"体系図との関係です。どういう形で入れられるか検討はしてみたいと思います。一定、色分け等はさせていただいているところですが、もう少しわかりやすくといったところで、検討させていただければと思います。ありがとうございました。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川の地域包括支援センターは、３職種配置されていないので、ほかのところは結構地域包括のところで、地域の課題を全部洗い出して、体系立てて、それをどう地域づくりに生かしていくかというふうなところを地域包括が中心になって行っていると聞いているのですけれども、その辺のところは、品川区の場合は、それが支え愛・ほっとステーションになるのか。","respondent":"大串福祉計画課長","answer":"したがいまして、各課の個別計画、各部の個別計画で取り組んでいる事業につきましては、あくまでも個別の計画の中に委ねるといったスタンス、あくまでもそうした中で一定程度網羅的に行われるような事業。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本来であれば、やはり厚労省が求めている地域包括ケアシステムの拠点は地域包括支援センターがなるべきだと言っているので、そこのところが支え愛・ほっとステーションがそういう形になり得るのだろうかという思いが、私はするのですけれども、その辺についていかがでしょうか。","respondent":"大串福祉計画課長","answer":"そうした中では、高齢者においての在支、高齢者に特化した形での専門機関、こういったところの連携も図りながら地域での課題の抽出、または解決に向けた考えといったものをコーディネートしていくことも求められているということで、こちらにも一定。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"そこで、医療も権利擁護も、それから総合相談もという、そういう位置づけにされていて、それが地域包括ケアシステムの中心で進めるということになると思うのですけれども、そこのところが３職種配置されていないままコーディネートだけのところを品川区が行っていくというシステムだと、無理があるのではないかという思いがするのですけれども。","respondent":"大串福祉計画課長","answer":"我々品川区においては、これまでも２０在支をつくって、そうした中で地域の高齢者の関係については従前にならって、また、各地区１３に分かれての地域センターの役割であるとか、そこに改めて支え愛・ほっとステーションを配置したといったところでは。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"最後に要望だけ。私はやはり改めて、その３職種配置の地域包括支援センターはどうしてもしっかりとつくっていただきたいという要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田（秀）委員長","kind":"質問","question":"私から１、２点お伺いします。各町会、いろいろ四苦八苦しているではないですか。確かに、３世代同居しているところは、例えば孫に当たる子どもたちは結構おじいちゃん・おばあちゃんが、小さいころからそういうふうに一緒にいると、認知症になったりしても、それはそれで対応も結構違うというのが、もう現実にあるではないですか。それは違うでしょうというのを、地域でずっと言っているわけではないですか。","respondent":"大串福祉計画課長","answer":"我々としてはそうした動きをよく捉えて、この計画の中でご紹介しながら、地域の皆さんと今後、地域福祉の向上推進、あるいは共生社会の実現を進めていきたいと考えているところです。いただいたご意見については検討します。","id":"exchange-012"}]},{"id":"topic-02","title":"国民年金第１号被保険者の産前産後期間の保険料免除","agenda":"国民年金第１号被保険者の産前産後期間の保険料免除","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"そういうところからすると、抜けないやり方、例えば出生届は必ず出すので、そのときにこれをまたもう１回、リーフレットを渡すとか、その方が国民年金か、厚生年金かというのはわからないので、もしも国民年金だったらというようなことになるのかもしれないのですけれども、そういうふうな形で、国民年金なのに申請を忘れないチェックであったりとか、その辺の周知の仕方は。","respondent":"三ツ橋国保医療年金課長","answer":"非常に、周知の仕方は広く周知したいと思っているところですが、この出生届の部分は非常に難しい問題がございまして、そのあたりもよく勘案しながら、できる限り広く周知をしてまいりたいと考えています。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"せっかくこういう形で４カ月間の国民年金が免除されて、それも払ったという形で年金が受け取れるという制度ができたのに、申請しなかったためにそれが適用されないということがないような形での取り組みをぜひ工夫していただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-03","title":"産後ケア日帰り型事業の拡充","agenda":"産後ケア日帰り型事業の拡充","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"現状ありがとうございました。１１時から３時の間で、この客室でしていただくケアの内容について、もう少し具体的にご説明いただきたいのですけれども、いわゆる４カ月未満までのお母さんなので、その期間、自分のお子さんを連れてきて、一緒に、あるいは預けてご自分だけという場合もあるのでしょうかね。","respondent":"榎本荏原保健センター所長","answer":"満足度という形でアンケートをとっているのですけれども、話を聞いてもらえたかというのは、もらえたと、できたという方が９７％で、ややできたという方が３％ということで、ほぼ１００％で、５項目ぐらい聞いているのですけれども、できなかったという回答は。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"拡充ということで進めていっていただきたいのですけれども、訪問型、宿泊型もあるし、それで検討していってもらいたいのですけれども、前に質疑を行ったとき、今回も東京医療保健大学ということで、そのときに助産師会という話が出たのではないかと思ったのですけれども、助産師会との連携というのはどうなっているのかというところをお聞きしたいのと、今回、これで完全に運営委託になるということで。","respondent":"榎本荏原保健センター所長","answer":"助産師会との関係ですが、１つはこの日帰り型の産後ケア事業は助産師会とよりかかわって、つくり上げるのに１年近く、東京医療保健大学と助産師会と区と３者でずっと話し合いを進めて、こういった形でつくって、ケアの内容も含めてつくり上げてきたというのが１つあります。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。私が聞き違えていたのかと思ったので、何かあまり連携がとれていなかったようにとっていたので、その辺は続けて連携をとってください。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"この中で課題はやはり相談員の体制だと思うのですけれども、区として課題はどういうふうに捉えているのか、それから、相談員に対する研修体制とか、その辺まで考えているのかどうか、その辺はどうでしょうか。","respondent":"松山障害者福祉課長","answer":"もう１つは、研修についてですけれども、こちらにも拠点相談支援センターからのご意見というのがありますけれども、初任者研修のみではなかなか難しいのではないか、また在支のほうからもさまざまな障害がある中でやはり勉強していかなければならないということで。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区としていつごろから実施を考えているのかというのと、それから、障害児者総合支援施設、今度できるところに区の分室をつくるということで、こういうところもいろいろな研修の場に使えるのではないかと思うのですけれども、この辺はどういうふうに考えているのでしょうか。","respondent":"松山障害者福祉課長","answer":"実施予定ですけれども、恐らく来年、まだ３月までに最終報告ということで、地域自立支援協議会に報告をさせていただいてからということになりますので、来年度につきましては年度途中ということで、４月からの実施は難しいというふうに考えております。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もう１点だけ。皆さん積極的にやるという考え方もあるのでしょうけれども、その中で具体的に、負担面、費用負担なども出てくると思うのですよね。当然、研修に出せばその分の負担が出てきますが、その辺は区としてはノータッチと言うか、フォローを考えなくていいのかというのが１点気になっているところです。","respondent":"松山障害者福祉課長","answer":"今すぐに何か具体策というのはまだ考えておりませんけれども、また意見交換の場を、今回ヒアリング調査をして終わりということではなく、またフィードバックしたり、いろいろな場面で意見交換もする中で、皆様方から意見を頂戴しながら考えていこうと考えています。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"まだこれから課題もあるし、地域の中で相談しやすい体制をつくっていく点では、ぜひうまく進めてもらいたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"ヒアリングをして対面式で聞き取りをしてくださっているということで、大変丁寧に聞き取ってくださっているなと思います。そこで少し参考までにお聞きしますが、在宅介護支援センターは７カ所ということで、全体で何カ所のうち７カ所で、なぜここの７カ所で実施されようと思ったのかということを教えてください。","respondent":"松山障害者福祉課長","answer":"やはり具体的に、どのようにこのことを進めていくかというイメージがなかなか湧かないということと、あとは地域バランスを考えまして、６圏域で１カ所以上はというところで選定したものです。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"それを今回、一緒にできるような体制をとってくださるということだと思うのですけれども、いろいろヒアリングの声も出ていましたけれども、今まではどういうふうにそのご相談者の高齢福祉の部分、障害福祉の部分、どのような形でご相談されていたのか、改めて状況を伺います。","respondent":"松山障害者福祉課長","answer":"高齢障害であったり、あとは若くして障害を負っていた２号被保険者の方への対応ですけれども、比較的多いのは、障害を受けて高齢者になられる方というのは多くあります。","id":"exchange-023"},{"speaker":"こんの委員","kind":"質問","question":"その方が困っていらっしゃる、サービスが必要なところ、手当てをしなければいけないというところが、他課と連携がとりやすい状況であったかどうかというのが、先ほどのお声で１つあったかと思います。では、在支に置くとこういったところはきちんと手当てされていくのか、その辺のところはどうなのでしょうか。","respondent":"松山障害者福祉課長","answer":"もちろん在支ありきではないということは認識しており、民間支援事業所の誘致というのも、やはり推進していかなければならないと考えています。","id":"exchange-024"},{"speaker":"こんの委員","kind":"質問","question":"先の方向性のお話をいただいてありがとうあります。今、課長がおっしゃった中のワードとして、家族丸ごとという、そこは非常に大事だと思います。ご家族もろもろ見ていくと、生活そのものはどうなのか。そうなると、そのほかの課との連携というのも考えられると思うのですが、その辺はどのようにお考えですか。","respondent":"松山障害者福祉課長","answer":"障害の方はかなり高齢、６５歳以上の方も多くありますし、２号被保険者の方も多くありますので、まずその分野できちんと連携を実践的に図るような形で、具体的に進め、そのほかの分野につきましても同時並行でこれまでの連携を生かしつつ進めていきたいと考えています。","id":"exchange-025"},{"speaker":"こんの委員","kind":"提案","question":"その連携とともに、先ほどもありましたけれども、研修をしていくというところで、区のサービスをどれだけご存じで、その場で提案できるかというのが非常に大事であると思うのです。いい体制をつくってくださる、これは期待しておりますので、その辺のところのご相談の受け方と対応力と連携のとり方というところをお願いしたいと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"確かに委員のご指摘のとおり、相談されたときに、相談員の知識や、例えば区の制度の知識、あるいは近隣区を含めた地域資源ですとか、あとはご本人の状況や家族を含めてアセスメントするということ等々、かなり高度な対応力を要求されることかと思います。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、ヒアリングの結果では、在宅介護支援センター７カ所に聞き取ったのが１０項目にわたって、寄せられた意見が書かれているのですけれども、聞き取りというのは大まかにこの項目でどういうご意見ですかという、そういう感じで対面で聞かれたということなのでしょうか。","respondent":"松山障害者福祉課長","answer":"お答えになった方というのは、在支の場合は管理者の方とケアマネージャーと聞いております。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この７カ所がゆくゆく指定特定相談支援事業所を併設する可能性のある在支というふうになっているのでしょうかということが１つと、それから、在支のケアマネがそのまま障害者のケアプランを組むというのは、なかなか難しいという意見が多く出ていると先ほどのご報告でもありましたけれども、そういうことで言うと、在支で指定特定相談支援事業所を一緒にやると言っても。","respondent":"松山障害者福祉課長","answer":"指定特定相談支援事業所の基準ですけれども、管理者１人、これは兼務が可能だと考えています。は相談支援専門員は専従ということで１名以上ということになっています。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もともと持っている資格と、実務経験というのがあると思うのですけれども、そのもともと持っている資格というのはどういう資格で、実務経験がどれくらい必要になるのかということを教えていただきたいのと、あとはそれを研修したからといってすぐにそのまま新しいところにぽんと行くというふうにはなかなかならないのではないかと思うのですけれども。","respondent":"松山障害者福祉課長","answer":"区といたしましては、どういった研修が必要なのかということも、拠点相談支援センターに専門員がおりますので、どういったカリキュラムを組んだほうがいいのか、研修プログラム等も含めまして、またご意見を頂戴しながら考えていきたいと思っています。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"東京都の研修を受けて、さらに研修をしながら、それで配置されるというふうなことになってくるということですけれども、考え方としては、在支ありきではないということで、これから自立支援協議会にこのことも報告をしながら、またさらにヒアリングも進めながら、いろいろ検討されて方向が出されていくと思うのですけれども、もしも在支と一緒にやるというふうなことになるとしても。","respondent":"松山障害者福祉課長","answer":"今後課題をもう少し明確に整理して、１つずつ解決策があるのかどうかというのは、ご意見を頂戴しながら考えていくということになろうかと思います。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そして広く障害者の皆さんからご意見を伺うという形にぜひしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、来年度につきましては、障害児者の方に対しましてアンケートを、今後の計画に向けて実施する予定です。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回在支にもしも併設するというふうになったときに、やはり連携というのはかなりされていく、どちらにしても、本当に障害と高齢は切り離せない部分があるので、連携というのはそうでなくてもされる部分というのがあると思うのですけれども、そういう点で言うと、さまざまなところで申し上げてきたのですけれども、地域包括支援センターで、やはり保健師や社会福祉士や主任ケアマネという。","respondent":"松山障害者福祉課長","answer":"ただ、現実的にはこれからということになりますので、具体的には１つずついろいろな課題をクリアしながら進めていきたいと考えています。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当に今、課長が言われたように、障害を持っている方は医療にかかる割合も多いですし、欠かせないところでもあると思いますので、私はこれを機会にぜひ、併設ということになるのであれば、保健師、社会福祉士、主任ケアマネの３職種配置の地域包括支援センターという形でぜひつくっていただきたいということで、要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"若林委員","kind":"確認","question":"確認です。２ページの6)の地域ケア会議でのケース協議ということで、これは在支の方から拠点相談支援センターの方に対する目線で、障害の担当の方が業務的にいっぱいで相談しにくいのが現状と、こういう区の認識はありますか。","respondent":"松山障害者福祉課長","answer":"ケース会議についての認識ですけれども、実際に障害者の拠点相談支援センターの中には、非常に業務が多忙であるということで、ご自分たちもそう思っている部分がありますが、これが全ての意見なのかというと難しい部分もあると思います。","id":"exchange-034"},{"speaker":"石田（秀）委員長","kind":"提案","question":"ほかによろしいですか。私から１つだけ確認させてください。それがいい、悪いと言っているのではなくて、私の聞き違いかもしれないので確認します。そこの確認だけ教えていただきたい。","respondent":"松山障害者福祉課長","answer":"確かに、総合支援施設は指定管理ということなので、指定管理者が施設をまず活用していただきまして、当然ながら総合支援施設ですので、指定管理者と区が連携をとりながら、一緒に福祉カレッジも含めまして、研修をしてまいりたいと考えています。","id":"exchange-035"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"国保の問題でこの質問をお願いしたいということなのですけれども、１点は子どもの均等割無料化を求めますということでの質問に対して、区から、子どもの均等割を無料化するとなると、一般会計の法定外繰入を増やすことになると、そして国から、法定外繰入は削減・解消すべきということを言われているので、それをさらに増やすようなことはできないので、子どもの均等割無料化はできないという。","respondent":"三ツ橋国保医療年金課長","answer":"これまでも区は納付相談や財産調査など丁寧に実施し、必要に応じて執行停止も実施しており、今後も留意事項を踏まえ、判例・法令等を遵守し、適正な滞納処分に努め、国保制度の安定性や公平性を引き続き図ってまいります。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"直接給与や年金を差押さえる場合は、この１０万円であるとか、プラス４万５,０００円というのは残しますということで、以前もそういう答弁があったのですけれども、ただそれが預金口座に入ってしまった場合は差押さえることができるという考え方、それで改めていいのでしょうか。","respondent":"三ツ橋国保医療年金課長","answer":"２番目の質問、差押禁止の部分ですが、副委員長が先ほど言われましたように、預金に入った場合は転化される、私も申し上げましたが、その部分ですので、今までどおりのことを実施してまいります。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"主張だけします。区長が判断すれば、国が削減・解消すべき法定外繰入というものではないところでできるということなので、私はぜひ、ほかの自治体でもされているわけですから、保険料減免額に充てる、国もそういうところでは言えないわけです。","respondent":"三ツ橋国保医療年金課長","answer":"生活が厳しい方につきましては、今までも必要に応じて執行停止、また生活保護や就労支援へのご紹介を実施しております。引き続き、個々に応じた納付相談など、窓口や電話にて丁寧に対応してまいります。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246103?Template=document&Id=3526#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":56592,"voices":121}},{"id":"h30-20181211-8","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"建設委員会","time":"午前１０時００分～午前１１時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)平成３１年１月区営住宅入居者募集","agenda":"はじめに、(1)平成３１年１月区営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区営住宅の募集は７月と１月の年２回だと思いますけれども、直近の７月の募集戸数と入居者数の数字があれば伺いたいと思います。この間、倍率が５０倍を超えて推移しているのですけれども、この倍率について、区は倍率が高いと考えているか、低いと考えているか、伺います。","respondent":"森住宅課長","answer":"７月の募集の結果ですが、１１戸募集しておりまして、９戸で入居済み、２件が審査中です。倍率は５０倍を超えていて、基本的には高い倍率だと認識しております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"応募件数がもしわかれば後で教えてください。いわゆる若い世代はどれだけ家族向けについて募集しているのか知りたいので伺います。あわせて、単身・家族向けにかかわらず、応募者の所得の程度というか、所得分布は区としては把握や分析しているのでしょうか、伺います。","respondent":"森住宅課長","answer":"それ以下の方が残りの４０％になります。収入の内訳ですが、１０月現在の状況ですが、一番収入の低い第１分類の方が７９.４％、３４０世帯です。年齢構成については、６５歳以上の方が６０％ということで、高齢の方が多いと考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"２０代・３０代・４０代・５０代の方は大体何％になるか伺います。そもそも若者は単身者向けには応募資格がないと。単身の若者が実態として高家賃のため品川区内で暮らすことは大変厳しいハードルがあるという今のこの状況は問題ではないのか、区の認識を伺います。その改善の何らかの施策を講じる必要があると思うのですけれども、いかがでしょうか。","respondent":"森住宅課長","answer":"割合としては全部合わせますと７０程度ですので、確かに入居者の方の高齢化が進んでおりまして、若者の世代が入るところがなかなかないですけれども、基本的には区としては、民間住宅ストックが大分ありますので。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"この状況について問題意識と言いますか、少し問題・課題があるのではないかと思うのですけれども、いかがでしょうかと伺いましたので、もう一度お答えください。","respondent":"森住宅課長","answer":"今後、居住支援協議会等も含めまして、そういった住宅確保が難しい方のためにどういう施策がとれるのか検討していきたいと思います。","id":"exchange-004"}]},{"id":"topic-02","title":"西五反田二丁目地区のまちづくり","agenda":"西五反田二丁目地区のまちづくり","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、駐車場が目黒川の両岸にあったと思うのですけれども、それは両岸の駐車場を撤去することになったのでしょうか。目黒川沿いの歩道の整備時期は大体いつごろを想定しているのか。パーク２４の本社ビルとしてということですけれども、細かいことで申しわけないですが、新日鉄興和が持っているビルにパーク２４が賃貸で入って本社ビルになるのでしょうか、伺います。","respondent":"稲田都市開発課長","answer":"駐車場の撤去の範囲なのですけれども、これは目黒川の、高速道路の脇のパーク２４側の通りと、それから、向かい側の大崎橋から五反田大橋までの路上の時間貸し駐車場ですけれども、それをなくそうかと、今まさに警視庁と協議中でして。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"２０１７年２月の建設委員会で質疑があったときに、大街区化のプランをつくった段階で、大きな地主やそういう可能性のある企業には回って、このプランのＰＲをしたというご答弁があったのですけれども、この大街区化というプランは、にぎわいゾーンの中あるいは区内でほかに大街区化を進めようと働きかけているところや、アンケートをとっているようなところなどが具体的にあるのでしょうか、伺います。","respondent":"稲田都市開発課長","answer":"広報紙等でこの大街区化というのをこの地区でプランをつくりましたということで、２回ほど話は出しております。それから、西五反田一丁目のほうも大街区化できないかということで調査等は進めております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"一丁目のほうの調査というのはどのような調査というか、どのような段階なのか。一丁目のほうからもそういった要望が出ているということなのでしょうか伺います。","respondent":"稲田都市開発課長","answer":"特に地元からやりたいとかそういう要望があるわけではありませんが、この地区は区画整理等はやられているのですが、狭隘な敷地であることから、適した場所があるかどうかということで、建物の老朽度とか道の幅とか、そういう部分を調査している状況です。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"この敷地の大街区化によって１３階６５メートルということで、高さについてはほぼ１.５倍になって、容積もそれにともなって相当な大きさになったと思います。私はこういった手法を完全否定するつもりはないのですけれども、こういった手法を一般化して機械的に広げることはできないし、やるべきではないと思うのですけれども、区のお考えをお伺いします。","respondent":"稲田都市開発課長","answer":"ただ、むやみやたらに進めるものではなくて、やはり権利者であります地域の皆様方が相談に来たり、どうかというところで、区は地域の皆様方の意見を聞きながらやっている状況です。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"この大街区化促進に向けてのプランを五反田で行おうとしている取り組みなのですけれども、この範囲内のところには、有名な会社や銀行もありながら、そうではない会社のビルなどもあると思うのですけれども、今そのプランについての合意形成はどのぐらい進んでいるのでしょうか。","respondent":"稲田都市開発課長","answer":"そういう中で、地区の方々が自分たちの建物も古くなったし、道も狭いし、どうしたらいいかと、そういう話が出てくれば、この大街区化という考え方もあるということで進めております。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"将来的には都市計画決定とかそういうことになっていくのですか。","respondent":"稲田都市開発課長","answer":"今回のこの大街区化のプランに基づいてということでは、都市計画決定をするとかいうものではありませんで、その他の都市計画の手法を取り入れたほうがいいというまちづくりになれば、都市計画決定するとかいう場面が出てくるかと思いますが。","id":"exchange-010"},{"speaker":"筒井委員","kind":"提案","question":"そのプランどおりになるのは大体どのくらいを予定しているのですか。それとも提案しただけであって、ガチガチにプラン通り完成することは求めていないのでしょうか。そのあたりの区のお考えをお知らせください。","respondent":"稲田都市開発課長","answer":"委員おっしゃったように、打ち上げただけというのは無責任過ぎるのですが、このまちはこのような状況ですので、地域の皆さんに、こういうまちづくりをやってはどうですかという提案をしているものですので、いつまでに完成とか。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"パーク２４が新社屋になるということで、駐輪場を、機械式のパラソル型みたいなものを、モデルケースとしてここのところにつくるということなのですけれども、今後まちづくりの手法として、一企業を応援云々かんぬんというのは抜きにした場合、地下にある程度の規模の駐輪場をつくる場合に、そのパラソル型の、周りに対する地盤等々の影響は大丈夫なのですか。","respondent":"稲田都市開発課長","answer":"この地下の利用というのはこれからいろいろと有効に考えていかなければいけないです。そういう意味では、地下を掘るということは周辺の地盤への影響は当然考えなければいけません。","id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"ただ、かたいところばかりではなくて埋め立てた場所もあるでしょうし、地盤がやわらかいところもあるでしょうけれども、そのあたりのところで、これが設置できる場所と設置できない場所はあるのでしょうか。それとも、技術面が発達しているのでどこでもオールマイティにこのような駐車場はつくることができるのでしょうか、どちらですか。","respondent":"稲田都市開発課長","answer":"ただ委員おっしゃったように、予期せぬこともありますので、つくれる場所、つくれない場所、例えば、地下水位が高過ぎて浮力が生じてしまってなかなか難しいとか、そういう現象があるかもしれませんし、必ずしもできるとは今この場では言えませんけれども。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問・要望","question":"教えていただきたいのですけれども、平成２６年のプランの資料と今の資料を見比べていて、確認なのですけれども、このオープンスペースの整備というところを見ると、先ほどご説明にもあったように、時間貸し駐車場をなくして、これは一方通行だったものを両面通行にして交通利便性の向上を図るということなのか、両面通行になるということなのでしょうか。","respondent":"稲田都市開発課長","answer":"そこを今回整備しまして、車の出入り口も北側の方に持っていき、歩道をつけて安全な通行をするという形で考えております。それと、河川管理用の通路もだぶりますが、現在区道として供用しているところですので、基本的には区の道路管理者と協議します。","id":"exchange-014"},{"speaker":"横山委員","kind":"確認","question":"１点だけ確認なのですけれども、このあたりの地域は、浸水ハザードマップを見ますと、浸水時の水の深さが１～２メートルあたりで、近隣が２メートル以上なのですけれども、地下２階が全て機械式駐車場なのでしょうか。例えば、増水の際にはどのようになるのか確認させてください。","respondent":"稲田都市開発課長","answer":"駐車場は機械式駐車場です。委員ご指摘のとおり、ここは目黒川沿いですので、そういう浸水対策ということで、浸水防止板といったもので対応します。","id":"exchange-015"}]},{"id":"topic-03","title":"第二戸越幹線整備工事（上流部）ついて","agenda":"第二戸越幹線整備工事（上流部）ついて","exchanges":[{"speaker":"横山委員","kind":"質問","question":"１点お伺いします。こちらの全体事業の完了見込が平成３６年度なのですけれども、こちらは将来的な接続管の部分も含めての予定でしょうか。その場合、１時間５０ミリを超える雨量に対してもということですけれども、５０ミリ、７５ミリとかそれぐらい対応ということで想定されているのでしょうか。現在わかる範囲で教えてください。","respondent":"持田河川下水道課長","answer":"１点目の事業の終了見込の平成３６年度というスケジュールは、今ご質問いただいたとおり、上流部から下流部までのシールドと、あとその接続の部分も含めての予定で今のところ進めております。","id":"exchange-016"},{"speaker":"安藤委員","kind":"確認","question":"戸越第一幹線にその宮前坂広場のほうからつなげるということなのですけれども、その戸越幹線のさらに下をシールド工法でトンネルが通るということでよろしいのか。そこも確認させてください。それと、シールド工法による住民への影響はあるでしょうか。そのあるなしを含めて、その工事の住民への説明はどのようになされるのかお伺いします。","respondent":"持田河川下水道課長","answer":"２点目の工事の影響ですが、工法はあまり地上等には影響ができるだけ出ないものを選んでいますが、万が一もありますので、施工前にはいわゆる家屋調査をして、施工後何かあれば当然そこで再度調査をしてという対応をとるように進めております。","id":"exchange-017"}]},{"id":"topic-04","title":"ヒカリの水辺プロジェクト","agenda":"ヒカリの水辺プロジェクト","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"恐らくタイマーだと思うのですけれども、どういう形でやっているのか。これは買い取りという形になっているのか、メンテナンス等の契約みたいなものは結んでいるのか。要するにいろいろなところで同時に点灯するということで、どういうふうにやっているのかいつも疑問に思っていたのですけれども、それについて教えてください。","respondent":"持田河川下水道課長","answer":"メンテナンスにつきましては、設置した後にはそういったメンテナンスの契約が必要と考えておりまして、今年度設置ですので、来年度になりましたらそういった設置されたもののメンテナンスですとかいう形での別途契約をして、メンテナンスをしていく予定です。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"イベントのときに配色を変えるということなのですけれども、色の変化ですとか動きのあるという。大崎のあたり、目黒川を見ていても、すごくきれいだなと思うのですが、こういったものについては誰が調整をして、事業者にお願いするのか、それとも区の職員が簡単に完璧にできるような仕組みになっているのか教えてください。","respondent":"持田河川下水道課長","answer":"今のところ所管のほうで想定していますのが、メンテナンスの中で色の変化等はそれほど難しい作業ではなくて、コンピュータの切りかえで可能と聞いておりますので、ある期間からある期間までは何色でということを区で決めて、その期間だけ色を変えるですとか。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"東京２０２０大会のことが書いてあって、常設とあるのですけれども、機械は設置したら無期限で運用していくものなのか伺います。それと、今回の整備計画３つですけれども、この経費は幾らぐらいなのか。先ほどメンテナンスの契約という話もありましたけれども、それも含めてどれぐらいになるのでしょうか。そして、国や都や区の負担割合はそれぞれ何％ぐらいになるのか、わかればお伺いします。","respondent":"持田河川下水道課長","answer":"１点目の期間ですが、今回常設ということで、基本的には設置しましたらずっとと言いますか、大会後も含めまして水辺のにぎわいということを考えていますので、一般的な照明のようなイメージで、基本的には夜になればライトアップしていくというように考えております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"結構区が単費で出しているなと思ったのですけれども、８,６００万円とか９億という話がありましたけれども、イニシャルコストとランニングコストという点では、もう少しどういう感じになるのか、設置したときにはこれぐらいかかって、毎年これぐらいかかってしまうというのがあれば、もう少し教えてください。","respondent":"持田河川下水道課長","answer":"ランニングコストについては、先ほど申しましたが、全部ライトが完成した暁には毎年１,０００万～２,０００万ぐらいの維持管理費がかかってくると考えております。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"結構イニシャルコストがかかるものなのだなと思いましたけれども、１度つけたら大体何年ぐらいもつのでしょうか。","respondent":"持田河川下水道課長","answer":"つけてみないとわからないところもありますが、一般的なこういった電気関係のものにつきましては、１０年で全てが壊れるわけではないと思いますが、１０年が１つの目安、耐用年数だと聞いております。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。なるべくもちをよくしていっていただきたいと考えています。これは特に京浜運河のところなどに設置する場合、海水の関係でさびとか発生しやすいとか、地域によって耐久の程度は違ってくるものですか。海水の関係とか。教えてください。","respondent":"持田河川下水道課長","answer":"やはり運河のエリアにつきましては、海水の影響は多少はあると考えております。今、設計中ですが、使う製品や電気の接続については、海水がかぶらないようなカバーをするですとか、そういった対応になると考えております。","id":"exchange-023"},{"speaker":"松永副委員長","kind":"質問","question":"私からは整備概要のライトアップ箇所についてなのですが、新品川橋と品川橋、荏川橋と箇所がばらばらになっているのですけれども、その理由について教えてください。もう一つは、新品川橋に関しては、イメージのほうなのですけれども、これを見ていると上のほうもライトアップしたほうがいいのではないかと思うのですが、いかがでしょうか。","respondent":"持田河川下水道課長","answer":"次に新品川橋の桁につきましては、橋梁の高欄が縦の転落防止の柵はなく、横方向の柵が３本ほどあって、ライトアップの効果が出にくいと所管では考えておりまして、ここについては桁のライトアップのみにしたところです。","id":"exchange-024"},{"speaker":"松永副委員長","kind":"質問","question":"この３つの橋についてなのですが、この桁側面と高欄は、先ほどの説明でわかったのですが、ライトアップ箇所は下と横の部分ということで、３橋に関して、何でこういうふうに分けたのかお伺いしたので、それについて伺いたいのですが。","respondent":"持田河川下水道課長","answer":"そういったデザインも生かせるようにということで、その２橋については高欄のライトアップをするというコンセプトで考えております。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問","question":"旧東海道の品川宿のこのあたり、ライトアップということは、明るくすることが目的なのですか、それとも、周りの暗さを醸し出すのが主眼なのか、どちらに力点を置いてこの事業を進めようとしているのですか。","respondent":"持田河川下水道課長","answer":"ただ、当然周辺の環境等もありますので、明るくし過ぎることについても、これは影響がありますので、所管として考えましたのが、ある程度暗い中で橋梁だけがぽっと浮かび上がるような形のライトということで、今回はこの桁および高欄のライトアップを考えました。","id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"暗さゆえの文化というのもあるので、そこら辺は、旧東海道周辺は歴史のあるところなので、よろしいかなと思うのですけれども、そこのところはどうお考えですか。","respondent":"持田河川下水道課長","answer":"護岸につきましても、ライトアップはやっていきたいと考えていますが、護岸にツタが垂れ下がっているところがあったり、また護岸も場所によって状況が変わります。護岸も明る過ぎるとまたまぶしいということもありますので、照らし方など慎重に検討していきます。","id":"exchange-027"},{"speaker":"松永副委員長","kind":"質問・要望","question":"私はここら辺の地域ではないので、この地域の方に怒られてしまうかもしれないですけれども、必ずしも明るさだけが美しいものを醸し出すわけではなくて、ましてやこの地域は歴史のある場所なので、そのあたりのところの強弱を加味しながら、将来的に進めていっていただきたいと、これは要望で、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-05","title":"本日は防災対策","agenda":"本日は防災対策","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"主催は避難所連絡会議ということなので、区民防災組織ということですから、大分そこのところを意識されたのかなと思って、本当に実践的な訓練が行われたなと私自身は思っています。以前議会でも何度か要望しましたけれども、障害者の方の団体に直接お話を伺うことは予定されているのかどうか、まずそこを確認します。","respondent":"古巻防災課長","answer":"障害者団体のご意見の反映ということですけれども、今現在、障害者福祉課と協議いたしまして、今、１３の障害者団体にアンケートを実施しています。このアンケートの結果を踏まえて、内容について運営マニュアルに反映していくことで考えております。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。１３団体ということで私たちが考えていたよりも幅広くお声を取り入れるのかなと思うのですけれども、やはり直接面と向かってお話を伺わないとわからない部分もあると思いますので、１３団体とは言わないまでも、できれば少しお話を伺っていただきたいと要望しておきます。これは答弁は結構です。多分そういう声はあると思うのですが。","respondent":"古巻防災課長","answer":"とは言っても今現在の基準で言うと、３.３平米に２人と今ご紹介いただきましたけれども、そういう形で面積換算しておりますので、現実的な物理的な制約もある中で、いかに工夫していくか、そこは避難所というか学校も含めた。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いっぱいあるのですが、とりあえずそれだけ申し上げておきます。それから、今回の新しい防災ハンドブックのほうで若干伺います。このデザインを見ると、東京防災のような非常に親しみやすいデザインに変わったなと感じているのですけれども。すごく基礎的というか単純なことなのですが、今までわが家の防災ハンドブックだったのが、しながわ防災ハンドブックに変わった理由について伺います。","respondent":"古巻防災課長","answer":"今までわが家の防災ハンドブックということで、「わが家」ということをタイトルとして載せておりましたけれども、もう少しさまざまな観点からということもあって、「品川区の防災ハンドブックです」ということが前面に出るようなタイトルに変えたという考え方です。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"もう一つだけ伺います。今後のスケジュールで、来年５月中旬から６月中旬にかけての配布ということなのですが、先ほども若干ご説明あったのですけれども、浸水ハザードマップについては、これも議会で何度もご答弁いただいているのですが、かなり古い東京都のデータを使っているということで、更新に間に合う、これには反映されるということでよろしいでしょうか。","respondent":"古巻防災課長","answer":"今現在、東京都の正式な公表の時期がまだ出ていないのですけれども、基本的にはそれに間に合わせて更新をかけるというスケジュールで考えております。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"ですから、防災対策というのは、予防となる防災対策が何と言っても中心に座っていなくてはならないことを前提にしつつ伺います。災害で戻る家を失って、こういった避難所もそうですが、仮の住まいでの生活を余儀なくされる方というのは出てくると思います。この避難所運営における行政の役割とか責任について、災害救助法との関係でどのように考えておられるか、改めてお伺いします。","respondent":"古巻防災課長","answer":"避難所運営に関しての区の役割・責任ですけれども、基本的には避難所は区が指定するものですから、最終的には区が責任を負うというのが、法的なたてつけではそういったことになると思っていますので、今ご質問いただいた点については。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは大事な視点だと私も思っています。ぜひ、災害救助法ということで、そちらの責任を果たせるような役割をこれからも努力していただきたいと思います。少し伺いたいのは、新たにマニュアルに加える視点ということで、要配慮者、女性、子ども、ペットに関する対応等がありますけれども、具体的にはどういうことを反映していくのでしょうか、そこら辺をもう少し伺いたいと思います。","respondent":"古巻防災課長","answer":"具体的な中身については、今、目次でしかお示ししていませんけれども、例えば、要配慮者に関しましては、基本的なスペースの決定に関しての考え方、段差や上下移動が少ない低層階にしてくださいとか。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"今回私は三木小に参加したのですが、確かに避難行動要支援者の方の部屋が１階に配置されていまして、ここですということでご案内もありました。そして、そこで交流が生まれると。それと、体を動かしやすいという点でも段ボールベッドの配備ですね、それはこのマニュアルの中にどのようにガイドラインとして入っているのか伺います。","respondent":"古巻防災課長","answer":"トイレにつきましても、数はできる限り避難者全体の中で足りるような数を確保するように努めているところですし、また、仮設トイレ等も備蓄している中で、なるべくトイレが足りなくならないような形での確保を今後も進めていきたいと思います。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"寝食分離のところは、アドバイザーからはそういうアドバイスがあったということなのですが、やはりある程度実際の避難所の運営に反映されていかないと意味がないと思うのですけれども、ぜひ、そういうアドバイスもあったわけですから、具体的にそういった視点を改定の中に入れていただきたいと思うのですけれども、いかがでしょうか。いざというときに１２万人分の確保というのは難しいのでしょうか。","respondent":"古巻防災課長、曽田災害対策担当部長","answer":"さまざまな避難所運営に関することについては、優先度を考えながら進めることも重要だと思いますので、必要なところ、生活に密接にかかわるところについて、まず、食べる、飲む、トイレの問題。実際にどうなるかと言いますと、発災後、全国を見て、被害を受けていない会社で協定先が作成を開始します。それから配布するということですから、時間的にも量的にも全然足りないのです。協定を結んでいるのは品川区だけではありません。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"キューバだってすごくやっていますよね。ですので、段ボールベッドというのはそういう意味では、避難所生活を整える上で最低限必要だと思っていますので、今の協定だけですと不十分だなということがわかりましたので、ぜひ必要数はどれぐらいなのかを定めた上で、それを確保できる方策をこれから整えていただきたいと要望したいと思います。最後の質問ですが、ハンドブックのほうから１点だけ質問します。","respondent":"古巻防災課長","answer":"今ご質問のあった事項ですけれども、６章の「(1)区の取り組み」の中に、各ご家庭への助成ということで制度一覧を掲載しまして、お問い合わせ先も庁内のしかるべき所管をご紹介する形で、わかりやすく掲載する予定ですので、そのように進めております。","id":"exchange-037"},{"speaker":"横山委員","kind":"提案","question":"何点かお伺いします。避難所運営マニュアルなのですけれども、上下水道の安全点検や確認についてなのですが、こちらはマニュアルのほうにどういった状況によってこうしてくださいという内容は掲載されていくのでしょうか、教えてください。プールの水の利用方法ですとか、ポンプをどうやって使ったらいいかとか、そういったあたりも掲載されているのか確認できたらと思います。はそちらからお願いします。","respondent":"古巻防災課長","answer":"さまざまな広域の取り組みにつきましては、これからどういった形でそういう仕組みを取り入れられるのか、また、どう取り入れることが効率的なのか、そういったところを十分に、いろいろな事例がありますので、研究を進めてまいります。","id":"exchange-038"},{"speaker":"横山委員","kind":"確認","question":"最後に、こちらのハンドブックについてなのですけれども、災害時などでもすぐ手にとれるようにということで、一家に１冊配付されるのですけれども、ふだん例えば、携帯電話やパソコンなど、１人１人が家族で確認できるようなデータであったり、スマホ版やアプリなどの展開はどのように考えているのか。こちらは日本語版だけなのでしょうか、多言語の対応をどのように考えているのか教えてください。","respondent":"古巻防災課長","answer":"カタログポケットは基本的には多言語対応ということで、翻訳機能を使ったものですけれども、多言語にも対応して、また、音声でも聞けますので、ひとまずその対応をした上で、冊子としての多言語版・音声つきのものも今後、年度は変わってくると思いますけれども。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"私も日曜日に行われた防災訓練に参加しましたけれども、そのとき仮設トイレの組み立て訓練を行いました。あのくみ取り式の仮設トイレは何年前のものでしょうか。と言うのは、今、品川区の組織にない名称が横に書かれていたので結構古いのかなと思ったのですけれども。おおよそでいいのでお知らせください。","respondent":"古巻防災課長","answer":"正確に何年前とは、多分学校によって違うと思います。ただ、かなり前から仮設トイレについては、ほかの避難所も配備していると聞いておりますので、具体的な数字が言えないのですけれども、それなりの年数がたったものだと思います。","id":"exchange-041"},{"speaker":"筒井委員","kind":"意見","question":"」と聞いたら「使ったことない」という声も聞いたので、そろそろ古いので、あの組立式仮設トイレの洋式化をぜひお願いしたいのですけれども、その点の見解をお知らせください。","respondent":"古巻防災課長","answer":"洋式のものも、委員がご覧になったものとまた違うタイプかもしれませんけれども、洋式の便器をセットするような形の洋式の組立トイレも配備を進めていますので、それと組み合わせて、洋式化については、通常の公衆トイレ等も洋式化のご要望が出ていますけれども、そういった中で。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。この東京防災、東京くらし防災、しながわ防災ハンドブックの３冊、区民の手元に行くのですけれども、どれも重要な内容が書いてあると思うのですけれども、まず区民が読むべき優先順位としては、しながわ防災ハンドブックが最優先になるのでしょうか、その点ご見解をお知らせください。","respondent":"古巻防災課長","answer":"最後の６章以外にも、マンション対策などを踏まえた区の取り組みを記述しておりますので、東京防災、東京くらし防災が一般的な内容とすると、しながわ防災ハンドブックについては、品川区に特化したものと考えております。","id":"exchange-043"},{"speaker":"松永副委員長","kind":"質問・要望","question":"先ほど、このしながわ防災ハンドブックの外国語版に関しては、後ほど順次やっていくというお話だったのですけれども、避難所運営マニュアルのほうで、外国人への対応というのがないのですけれども、あればあるでいいのですけれども、もしなければつけ加えていただきたいと思うのですが、いかがですか。","respondent":"古巻防災課長","answer":"当然、外国人の方への配慮は、掲示物とか、そういった基本的な配慮については記載していく形で考えていますので、今ご提案いただいたような中身はできるように進めてまいります。","id":"exchange-044"},{"speaker":"松永副委員長","kind":"質問・要望","question":"もし避難所で通訳が必要であれば私たちを使ってくださいという団体もありますので、ぜひそうした団体の方々との連携も含めて進めていただけたらと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/602656?Template=document&Id=4252#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":30499,"voices":121}},{"id":"h30-20181211-9","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"文教委員会","time":"午前１０時００分～午後 ０時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","topics":[{"id":"topic-01","title":"平成３１年度入学希望申請の状況","agenda":"平成３１年度入学希望申請の状況","exchanges":[{"speaker":"鈴木（博）副委員長","kind":"質問","question":"この数字をもとに戻してもいいという理由は何ですか。","respondent":"篠田学務課長","answer":"例年の数字が大体３割程度ですので、一応教育委員会としては、３割ぐらいの方が外に出るということで、７割ぐらいの方が利用されるだろうということで、考えているところです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"小学校も中学校も、抽選校が増えているということですけれども、増えている理由をどういうふうに、教育委員会は分析しているのでしょうか。それが１点。東海中学校を先ほど例に挙げて説明されたのですけれども、受入数に対して、圧倒的に入学予定者が多いですよね、７１人と。そのあたりを教えてください。","respondent":"篠田学務課長","answer":"それから東海中学校周辺の話ですが、確かに中学校全般に、受入枠に対して入学予定者数が上回っているところがあるのですが、これは例年同じような形でございまして、先ほど申したように約３割のお子さんは私立へ流れますので。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"例年３割は私立に行っているという問題ですが、たしか私の記憶では、違っていたら訂正しますが、小中一貫校をつくるときの理由に、私立へ流れないよう公立離れを防ぐ、たしかそういうことがあったと思うのですけれど、それについて、３割という数字はどういうふうになっているのか。当初の一貫校をつくるときの教育委員会の考え方に対して、現状はどういうふうにしていっているのか、その辺について伺います。","respondent":"篠田学務課長","answer":"過去の推移を見てまいりますと、中学校進学での流出といいますか、そちらを志望される方はここ数年、大体３割程度という形になってあります。昨年度は若干高かったのですけれども、総合すると大体３割程度です。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"私立に行くというのはそれとして、先ほどおっしゃったようにそれぞれの家庭の教育方針、選択の問題ですので、別に悪いというつもりは全然ないのですけれども、しかし公立離れをとめていきたいという説得のされ方もあって、一貫校というものが進んできた。しかし私立に３割が流れているという数字に、変化はないというふうに見ていいのですか。その辺について伺います。","respondent":"篠田学務課長","answer":"これは品川区で取り組んできた結果の数字ですので、逆に言いますと何もしなければもっと、私立に流れる数は増えていた可能性も十分考えられる中で、こういった結果が出ているというふうに見ているところです。","id":"exchange-004"},{"speaker":"つる委員","kind":"質問・要望","question":"もう一つは、もしかしたらこの間、毎年この報告の中にあったかもしれませんし、今回の学事制度審議会の中でももちろん内部ではきちっと分析されていると思うのですが、この増減の出入りがあって、１つの中学校、小学校等を基盤として、どこに希望して転出しているのが多いのか、逆にどこから来ているのが多いのか、そのフローといいますか、それがわかるようなものが資料としてあって、それをもとに。","respondent":"篠田学務課長、熊谷指導課長","answer":"これはやはりそのことが持つ影響力というのがかなりありますので、一応そういったものは、当然検討の中で土台では使っておりますけれども、一般には公開していない形で持っているものです。本区におきましては、９年間の一貫教育をしっかり定着させて、子どもたちの学力をつけてきたという自負がありますので、こちらについては引き続き、自信を持ってやってまいりたいと思います。","id":"exchange-005"},{"speaker":"つる委員","kind":"確認","question":"だからそういう意味で、評価という部分でしっかりやっていただければと思います。先ほどトレンドなのか、そういうものは実際あって、いろいろな形で制度に生かしていただけるということで分かりました。それを表に公表してくださいという話ではないですけれど、しっかりとそうしたものを持ってやっていただいているのかなという、確認でした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問","question":"一方で公立は、生徒を確保するために私学のようにさまざまな手を打つというか、いわゆる広告を打つとか、そういうことはしないわけではないですか。だけど公立学校というのが存在していて。教育委員会として、公立の学校にみんな来てほしいのか、いわゆるスタンスの問題で、そこはどのように考えているのか。","respondent":"篠田学務課長、熊谷指導課長","answer":"基本的なスタンスとしましては、当然区民の方は地元の学校に来ていただくというのが一番、本当に私どもはそのために取り組んでいるということが大前提です。そのための取り組みをかかすことはないということでやっているものです。ですので、もちろん公立学校としてぜひ、本区の教育には、先ほども申し上げたように力を入れて、そして自信を持ってやっておりますので、来てほしいという思いはありますが、ただやはりさまざまなお考えや子どもたちのそれぞれの特徴。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問","question":"これをなぜ聞いたかというと、いわゆる品川区の教育委員会としても、さまざまやっているわけではないですか。その辺はもう少し、もし本当に地元の学校に来てほしいというのであれば、私は一つのアピール方法として、品川区はこういうことをやっているよというのは、もっとアピールしてもいいのかなと思います。これだけ見ると、足りていないわけではないですか。","respondent":"篠田学務課長","answer":"ただ、いずれにしましても結果的に先ほどの延山小学校のように、当初２学級でその学区のお子さんを受け入れられる予定であったけれども、増えてしまった、超えてしまったという場合には、必ず教室数を確保し、必ず学区のお子さんが入れるように対応していくというものです。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"もう毎年のことなのですけれど、今回小学校のほうですが、希望選択をとって抽選になった学校で、兄弟枠で何人申し込みがあって全員待機とか、５人兄弟枠で申し込みがあって２人だけ入れたが、３人は待機になってしまったとか、そういうところがあれば数字と合わせて教えてほしいです。受入枠６０のところは、７０入れるわけじゃないですか。もう受入枠を出さないほうがいいのではないですか。","respondent":"篠田学務課長","answer":"ただ、確かに委員ご指摘の形で受けとめられる方にとっては、納得がいかない部分があるのではないかですので、出さないこと自体がどうかというのも検討してみないと何とも言えないのですが、やはり一定程度。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"小学校１３校のうち、１０校が全員待機ということで、逆に３校はどういう状況なのか、教えてほしいです。受入枠は、たしか１０年ぐらい前は出していなくて、抽選になりそうな学校だけ、何人と入れたのです。どこの学校も枠があるのだから、全部出すべきだと言った記憶が、鮮明に残っているので、１０年前は出していないです、多分。兄弟枠の数のところだけ、教えてください。","respondent":"篠田学務課長","answer":"それから京陽小学校ですけれども、８名の方が希望されまして、７名の方が受け入れられて、１名が待機になっている状況です。日野学園は２６名の兄弟枠のご希望がございまして、１９名が受け入れられて、７名が待機されているという状況です。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"今回の表を見ると、抽選校が小学校は２校、中学校は、３校増えているといった状況の中で、今、兄弟枠の話があったのですが、そちらでなくて、抽選にかかわる人数は全体で、小学校と中学校、何人この抽選に臨むのかという人数と、抽選に漏れて待機になる数、これは予想かと思うのですが、何人ぐらいになるのか、教えてください。","respondent":"篠田学務課長","answer":"抽選の人数ですが、合計数が出ていないので、後ほどお答えいたします。それから待機の人数が、小学校は全部で３２６名、中学校も同じく３２６名が待機になってあります。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はこの作業を、もうちょっと区民にわかるように知らせてほしいと思うのです。そういった意味で、選択制がなかったときと、始まってからの現在と、事務量がどのぐらい違っているのでしょうか。その負担が増えている分、本当に効果があるのかどうか。人もお金もかけてやっていることで、それが本当に子どもたちや保護者の方々にとって、よい方向に行っているのかどうか。その辺はいかがでしょうか。","respondent":"篠田学務課長","answer":"事務量自体、単独では増えているものもありますけれども、当然集約されているものもあるということで、極端に事務量が増えているといったことはないと、認識しています。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"受験勉強をして受験する、落ちてしまう場合は本当にがっかりするでしょうけれど、公立の学校で、自分の実力とは関係なくして選ばれないということ、この１０月に受付をして、１１月末に抽選ということで、待機者が３２６名ですか、小中学校それぞれともにいるという、待たされて決まらないということが、この時期の成長している子どもたちに与えるダメージとか、その手前で選ぶ努力というか。","respondent":"篠田学務課長","answer":"それから学校選択制の評価ですけれども、学校選択制自体は、品川の学校を変えていくという大きな目標がある中で取り組んできたものですので、開かれた学校にこれがつながってきたという過去の経緯もありますし、きちんとした形で。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、学校選択制の評価のところで、開かれた学校になってきていると、それは一部自分の地域以外のところにも目が向いているという意味ではあるかもしれません。全体に網をかけてしまって満足度が９０何％ありますと、そういったつかみ方ではなく、希望してこの選択制を使った方が、実際にどうなったのかというところまで、しっかりと検証していただきたいと思いますが、いかがでしょうか。","respondent":"篠田学務課長","answer":"それからマイナス面のお話で、地域での絡みというお話もございましたけれども、その辺のことに関しましては、今回、学事制度審議会の中で、全体の制度の見直し等もあって、例えば小学校の選択でこれまでブロック内で選べていた学校を、近隣校に限定するといった形で。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"校舎等いろいろな設備関係がどうか。個人的にいろいろ聞くと、教員がどうか。建物は、古い学校は本当に、よくしていただきたいと思いますし、一生懸命教員の方たちの声を聞いて育てていただければ、いい教員がたくさん増えると思うのです。私は、学校選択制はプラス面よりもマイナスのほうがずっと多いので、本当にやめていただきたい、これは意見を言って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかお尋ねします。やられていないとすると、選択の仕組みが変わったときの方式はどういうふうになるか、検討する予定があるのでしょうか。現状の認識でしょうか、兄弟枠がこれだけ待機になってしまうというところの認識と、今後の対応をお尋ねします。何対何とか、そういうことを高校のほうはやっているのですけれど、中学校はそれは特にないのでしょうか。","respondent":"大関教育総合支援センター長、篠田学務課長","answer":"それから区立の小学生が連携校の中学校に実際に出向いていって、中学校の授業を体験するなどしながら、ぜひ上がってもらいたい連携の中学校を実際に生で子ども自身が体験してもらうことで、地域の中学校を選んでもらおうという努力は。やはり兄弟が別々の学校になってしまいますと、ご家庭での負担等もありますので、できるだけ入れていきたいというのはあるのですけれども、一方で、学校選択の際に、これまでも周知はしてきているのですけれども、入れたとしても。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"意見","question":"それぞれありがとうあります。もう一つは、中学校の指導の話が先ほどあったのですが、小中一貫というのとまた別で、生徒指導とかそういう面で、中学校の教員の方が区立中学、しっかりやられていると思うのですけれど、そのあたりのお話をお願いします。","respondent":"大関教育総合支援センター長","answer":"生活指導面に関しましても、中学校と小学校、義務教育学校もあわせて、生活指導主任が毎月実施して、実際に生の様子を見ていただいたり、情報共有をして、小学校の教員を通じて、今、どこどこの中学校はこういう状況だという部分は。","id":"exchange-017"}]},{"id":"topic-02","title":"平成３０年 特別区人事委員会勧告に対する対応","agenda":"平成３０年 特別区人事委員会勧告に対する対応","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"非常に単純なことなのですが、公民較差という、この示されている金額が４桁で、今までこの間は３桁、１００円台、２００円台と低い金額だったのですが、今回９,６７１円と、こんなに数字が違っているというのは、なぜこんなふうに違いが出たかというところを教えていただきたいと思います。","respondent":"熊谷指導課長","answer":"月例給の公民較差の要因ですけれども、人事委員会によれば、平成３０年４月に実施しました行政系人事・給与制度の改正に伴い、職員構成に変化があったことによる影響というふうに聞いております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"職員構成の変化というか、具体的にわからないのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"そうなのだけれど、ここだって具体的に示されているから、当然ご存じのことと思いますので、教えてください。わかる範囲で結構です。","respondent":"熊谷指導課長","answer":"こちらにつきましては、本日総務委員会でご説明するところですけれども、実際に今申し上げたとおり、こちらの行政系人事・給与制度の改正で、職員構成に変化があったことから、給料表がそれについて偏りが見られたというところしか、私のほうではご説明できないところです。","id":"exchange-020"}]},{"id":"topic-03","title":"大崎図書館分館の開館","agenda":"大崎図書館分館の開館","exchanges":[{"speaker":"南委員","kind":"質問","question":"蔵書数が示されているのですけれども、移転をしていった大崎図書館と合算してみたほうがいいのか、よくわからないのですけれど、この４万点という規模は、品川区内１０カ所ある図書館のどのぐらいか伺います。","respondent":"横山品川図書館長","answer":"分館の資料、４万点の予定ですが、区内の図書館でいいますと、源氏前図書館が３万８,０００点、大井図書館が４万６,０００点、二葉図書館２万８,０００点ですので、小規模な地区館と同等の蔵書数の予定です。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"裏面にレイアウト図が示されていて、ちょっと小さくてあまりよくわからないので、１点だけ伺いたいです。２つのパートに分かれて設定されているということはわかったのですけれども、入り口から入って、この辺が不鮮明なのですが、入り口が大体どこまであって、右側のほうは児童の図書ですか。多目的室のほうに行く、行き方がちょっとこれではわからないので、よろしくお願いします。","respondent":"横山品川図書館長","answer":"入り口から左側一帯が一般の書架になりまして、ここに一般図書も、児童図書も、絵本のスペース等もあります。真ん中に事務室が配置されていまして、その右側にトイレスペースと廊下がありまして、突き当たりが多目的室で、こちらで行事等を行う予定になっております。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この図の中で、前は読み聞かせのとてもすてきなお部屋があったのですけれども、その読み聞かせはどういうところで行われるのか、教えていただきたい。多分、細長くあるのは書架ですよね。座って読む場所というか、席はどのぐらい確保されているのか、その辺も教えてください。","respondent":"横山品川図書館長","answer":"読み聞かせのスペースですが、こちらの多目的室のほうで行う予定になっております。書架ですが、委員ご指摘のとおり細長い部分が書架になります。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私もそうなのですが、疲れてしまって座って読める場所があったり、本の選定ができるとありがたいなと思うので、ぜひ、なるべく多くの席を確保していただきたいと思います。ここは地下ですよね、半地下ですか。そういった面で動線がどうなのかなと思いながら見ていたのですが、もちろん２方向避難になっているかと思うのですが、その辺の災害時の対策というか、避難ルートはどうなっているのか。","respondent":"横山品川図書館長","answer":"委員ご指摘のとおり、こちらは芳水小学校の地下部分になります。出入り口としては、ロビーの１カ所があるのですが、そういう意味では１階の平面に面しておりますので、災害の際には最悪、窓からも出られるような形で対応しようと思います。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"多目的室のところで行事をされるということで、乳幼児の読み聞かせもここでやってくださるということなので、多分広いスペースかなと思います。ぜひ充実した読み聞かせをしていただきたいと思いますが、読み聞かせも含めて行事はどのぐらいの間隔でやられるのか、教えてください。特に読み聞かせのところを。","respondent":"横山品川図書館長","answer":"そのほかに、季節ごとに例えばぬいぐるみおはなし会であるとかさまざまな行事をこれから実施していく予定ですし、今年度実施しております高齢者支援事業についても、こちらで拡大していこうと考えています。","id":"exchange-025"},{"speaker":"つる委員","kind":"確認","question":"地図上でしか私もわからないのですが、表の図でいうと、若干ですが、体育館とかぶるところがあるのですよね。多目的室のほうは、位置的にはステージ直下になるのですか、あとは事務室とかその辺も、音の影響とかいうのは躯体の関係で、専門的なところでしっかりされていると思うのですが、この辺の配慮など、そういう意味では大丈夫か確認だけ、お願いします。","respondent":"横山品川図書館長","answer":"こちらは学校改築の途中で図書館の併設が決まりまして、その際にご心配いただく声をいただいておりますので、図書館の工事の際には特に音の伝導について配慮していただくように、業者の方にお願いしているとともに、音になるべく影響のない、多目的室やトイレ。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"細かい部分ですけれど、この図書館部分にＡＥＤは設置されるのでしょうか。もしされるのであれば、どのあたりに設置しますか。","respondent":"横山品川図書館長","answer":"ＡＥＤについては各図書館に設置していくところですので、分館についても設置していきたいと考えています。場所については、まだ引き渡し前ですので、そちらを確認してから設置場所を確定していきたいと考えています。","id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。先ほど飯沼委員とのやりとりの中で、収容人数は決められていないという話だったのですが、そこを改めて、何の収容人数が決められていないのか教えてください。","respondent":"横山品川図書館長","answer":"図書館の性質上、１日そちらに在館される方は少なくて、入れかわり立ちかわり、もしくは席を利用しないでご利用なさる方も多いという形で、出入りの人数はカウントしているのですけれども、定員はここまでなので入ってはいけませんということはできませんし。","id":"exchange-028"},{"speaker":"石田（し）委員","kind":"質問","question":"でも出入りが多い施設というのはたくさんあって、その施設のキャパシティに対して、どれだけの人が入れるかというのは、ある程度決まっているものですよね。要は利用のときにそれ以上とか、以下とかいう部分はないのかもしれないけれど、一定の収容人数というのは、設定しておかないといけないのではないのかと思うのですが、その辺もう一度教えてください。","respondent":"横山品川図書館長","answer":"法令上で、例えば消防法で１００人とか１,０００人とか、大まかな規定の制限はあると思うのですけれども、図書館を建てるとき、何人予定でというような決まり自体はない形になります。","id":"exchange-029"},{"speaker":"石田（し）委員","kind":"質問","question":"そうすると、法律上の何かしらは、あるわけですよね。収容人数はあると思うのですが。大まかに、例えば２８８人ですとかいうのではなくて、３００人ですというものなのかあれですが、何らかの法令上のもので、収容人数というのはあるのではないか。施設はどこでもそうだと思うので、それを教えてください。","respondent":"横山品川図書館長","answer":"そのような意味ですと、席で各図書館をご案内しているような形で、非常に出入りの人数よりは少ない形ですが……。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"で、体育館の下というのも、半地下というのはどこのことかなという関係で、多目的室に結構な人がおいでになったとき、もしもの場合にはどうするのかなと、ちょっと気になったので、そのあたりの避難も含めて、２方向避難との関係も含めて教えてください。","respondent":"横山品川図書館長","answer":"多目的室の前も窓で、外に出られる状態、多目的室の前は駐車場になりますので、段差としてはそんなにない状態になっています。２方向避難については、出入り口としては１カ所しか設けていないのですが、消防法についてはクリアされている状態で、建築されていると聞いております。","id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"２方向避難との関係で、今わからなかったのですが、消防法でクリアされているということはわかったのですけれども、２方向避難が設定されていなくてもいいという、そういう理解でいいのですか。","respondent":"横山品川図書館長","answer":"申しわけございません。２方向避難について、これでいいというような確認のところまで把握しておりませんので、後日確認します。","id":"exchange-032"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問","question":"もう一つは、園によってだと、全園でないと思うのですけれど、４歳児も午睡時間をなくしている、４歳児の当初からではないと思うのですけれど、そういうふうにしているところがあると聞いているのですけれど、その点についての見解を伺いたいと、品川の保育内容ということに関して、伺いたいと思います。","respondent":"佐藤保育課長","answer":"２点目の４歳児も、ですが、こちらに関しては基本的に午睡をする取り扱いです。お子さんの体調や状況によって、午睡をしない場合もあるかもしれませんが、それは個別に対応しています。基本は５歳児からというふうに考えております。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"１日過ごせる体力がついているというふうな説明でしたけれども、小学校に上がれば当然午睡の時間はないし、当面は午前中授業だけれども、２学期あたりから５時間以上も入ってくるというふうに思っているので、そういう点で体力をつけていくということは大事だなと思うのですが、その１日過ごせる体力という点で、個々の子どもの状況によっても、発達とか生まれた月とか、一律にしていくというのもなかなか。","respondent":"佐藤保育課長","answer":"４歳児に関しましては、ある時期から午睡を取りやめるとか、どういう感じでやっていくかというのは、今後の研究課題かと考えております。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"とりわけ保育園は１日保育ですし、子どもによっては朝早くから夕方遅い時間まで、保育園での保育されている状況もあるわけですから、そういう点ではやはり、成長、発達の段階にある子どもの保育というのは本当にきちんとした、過去のいろいろな経験、蓄積の上に捉えていくべきではないかと思いますので、きちんとした考え方のもとでの指導が必要なのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"写真入りで、すごく網羅した、初めてですよね、こういった研修の中身がきちんと書かれたものは。よくつくっていただいたと思います。この資料は、どういう方が携わってつくってくださったのかというのが一つ。研修というのは本当に、保育の質を向上させていく上で日々大事なことですけれども、研修の中身を作成するのは、どういった方が携わっているのか、その２点を教えてください。","respondent":"佐藤保育課長","answer":"２点目のご質問にもつながりますけれど、研修の中身というところもその現役の園長、ＯＢの園長も５人ほどいらっしゃいますけれど、そういった中で、これまでの蓄積に応じた効果的な保育の研修について、さまざまな研修を実施しているところです。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この研修の中身というのは、公立の保育園と私立の両方とも、多分主に認可保育園であろうなと思うのですけれども、今みたいに保育施設がいろいろできてきている中で、品川区のお子さんに対する責任といった意味で、すごく頑張っていると思っているのです、私立園が増えて、大変だなとは思っているのですけれど、その辺の研修のパイというか、品川区がどの程度まで。","respondent":"佐藤保育課長","answer":"区としての研修の実施といいますと、私立保育園等への働きかけだと思うのですけれども、私立は私立で、先ほどご説明したように各事業所や園の方針で保育を行っておりますし、その考え方は当然尊重されるべきですが、区といたしましては共通的なもの。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"保護者の方がされていて好評の１日保育士体験を、保育課の方がされるというのはとてもいいことだと思います。保育の入園申請にいらっしゃる父母の皆さんとか、子どものことをまず理解する、その子どもたちを思い描くことで、大変なときも頑張れると思うので、ぜひ皆さんに体験をしていただきたいと思います。","respondent":"佐藤保育課長","answer":"現場の保育士のほうも、保育課も頑張って保育士の確保をしておりますけれども、今後はどちらかというと出前形式みたいな、現場に訪ねていって、より保育を学んでもらうような形にしたほうがいいだろうという声が内部でも出ていますので、今年度は研修の再構築をしておりますから。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"出前もいいかなと思うのですけれども、人手不足は深刻です。本当に深刻です。そんな状況でお仕事をしているという、病児保育も全部は役に立たないのです。これはお願いしておきますが、課長だけの問題ではないので、部長にもしっかり聞いていただいたと思いますので、ぜひ検討の材料にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木（博）副委員長","kind":"提案","question":"保育園で生命を脅かすような事態、非常に大変な事態というのは事故で、食物アレルギーのアナフィラキシーショックもそうですが、例えば鉄棒から落ちたとか、転んだとか、宙返りしたときに肱が抜けた、けがをした、そういうときの初期対応を保育士がある程度できるようにするトレーニングというのは必要ですから、ぜひ事故対応を項目の中に入れていただきたいと思ったのですが、その点はいかがでしょうか。","respondent":"佐藤保育課長","answer":"委員ご指摘の事故の関係の対応についても、十分保育士のほうで学ぶ機会を設ける予定です。","id":"exchange-040"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"親との関係もすごく大事なので、コミュニケーション能力というのは非常に大切です。特に今はいろいろな親の方がいらっしゃるので、そういう研修も十分やるように、これは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問","question":"受けていないとしたら、異動で今後、保育園に行ったとき、どうなるのかというところを伺いたいです。どのようにして参加されているのか、参加されていなかったら、次の職場のためにどういうふうになるのかということです。それから、先ほど鈴木博副委員長からのお話でもあった、コミュニケーションのほうですが、現在は保護者に対する対応についての研修は、されているのでしょうか。","respondent":"佐藤保育課長","answer":"２点目の保護者支援に関しましては、今年度は保護者との良好な関係構築のためのコミュニケーション能力と、保護者ニーズが多様化しているという理解を進める関係で、講義等の研修を実施しております。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問","question":"児童センターにはいらっしゃらないのでしたか。いらっしゃったら、保育園のお仕事と違うので、その後についてどうなのか教えてください。","respondent":"高山子ども育成課長","answer":"その後、また保育の現場に戻れば、先ほど保育課長が答弁されましたように、改めて保育現場における研修体系に基づいて再教育ということになるかと思います。","id":"exchange-043"},{"speaker":"石田（し）委員","kind":"意見","question":"１点だけ。保育の質の向上と、今、特に言われているのですけれど、今回この資料を見ていても、保育の質なのか、保育士のいわゆる質というのか、研修だったり処遇改善だったり、そこが保育の質になっているのか。私はほぼほぼ保育士の、いわゆる働き方がどうなのかがイコール保育の質に見えるのですけれど、区としてどういうふうに考えられているのか。","respondent":"佐藤保育課長","answer":"３つ目が委員ご指摘の人、保育士の質。この３点と考えておりまして、どれもバランスよく進めていきたいと考えているところですが、本日の所管事務調査に関しましては、どちらかといいますと保育士の質を高めるという観点で、まとめさせていただいているところです。","id":"exchange-044"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"突然の報告だったので、受けとめられないのですが、これは７月１９日に都と合同検査に入ったということですが、きっかけは一体何でこの合同検査に入ったのか、保育士が適正に配置されていないというのはどこの部分に適正に配置されていなかったのか、まず２点お伺いします。","respondent":"佐藤保育課長","answer":"それで都と相談をした結果、合同検査が必要ではないかということで、７月１９日に行われたものです。７月１９日に実際に指導検査に行ったところ、朝の保育士の体制が１名不足しているというのを確認しました。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"朝の配置というのは、早番の保育の体制が、多分何カ所かでやられているところに、正規の保育士がいなかったということですか。非正規の資格のない人がやっていたということなのか、それも何人必要なところに何人しか配置されていなかったなど、もう少し具体的に教えてください。","respondent":"大澤保育支援課長","answer":"早番は７時半からになりますけれども、本来は７時半から２名、保育士がいなければいけないところを、１名しか配置していなくて、具体的には８時から出勤する職員が次のシフトになりますので、７時半から８時の３０分間、１名で対応していたです。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"朝の保育のところは、本当に１名しかいなかったということは、ほかに非正規の人がいたのですか。本当に重大な問題ですよね。何かあったとき、１人の保育士ではとても対応できないというところなので。この３０分ですけれど、どのぐらいの期間においてこれがされていたのか、その理由はなぜなのか。これは大問題だと思うのですが、そこのところはどう判断をされているのでしょうか。","respondent":"大澤保育支援課長","answer":"保育士の急な退職等により、体制が整えられずに平成３０年４月から１人で対応していたということでございました。私どもも大変、これは重要な案件だと考えております。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"急な退職ということですけれども、職員が確保できなかったという受けとめなのでしょうか。相談体制とか、私立なので、園で対応することかと思うのですけれど。この辺の防止策というか、公立だと職員が不足したらすぐ連絡が来ると思うのですが、防止策をどう考えていらっしゃるのかということと、この４６０万円というのは単純にその間の職員に対しての給与関係なのかどうか、そこも教えてください。","respondent":"大澤保育支援課長","answer":"返還額ですが、こちらにつきましては、保育士が規定どおりに配置されていることを前提に、加配している保育士に対する加算部分を、４月から７月分を返していただくという考え方です。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問","question":"今、毎月保育士の数は把握していますということにおいて、報告に不正があったのですか。正しい報告がされていたのかどうか。その辺は、人が確保できなかったという問題だけではないと思うのですけれど、その辺どうだったのか。報告上はちゃんとされていたのか数字がごまかされていたのかどちらですか。","respondent":"大澤保育支援課長","answer":"基準の保育士の配置としては足りています。ただ、シフト上、早番の方を２名入れていなかったという考え方になります。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今ここでいろいろ言っても仕方がないので、ぜひそういうことがないように、これは倫理の問題でもあると思うので、チェックできる方策を考えていただきたいし、事故がなかったからよかったですけれども、このときに大きな災害があったりしたら、たかだか３０分といっても、とても大事な時間帯だと思うので、ぜひ指導の面でのご努力を、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"その辺について説明がなかったので、伺いたいと思います。だからここは、２人の配置をしないと、受け入れも含めてできないという状況であったと思うのですけれど、その点についてはどういうふうに説明があり、どうなっていたのか伺います。それと３点目に、返還金額が４６０万円というのと、１０日分の１４万円という説明があったと思うのですけれど、この関係がよくわからないので、もう一度お願いします。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長","answer":"今回の指摘につきましてあざみ会は、もちろん反省しておりまして、８月からすぐに非常勤の方を雇ってシフトをきちんと整える対応をしております。４名受け付けた際は、本来ですと保育士は２名必要です。その４名を受け入れたにもかかわらず、保育士が１名しかいなかった、この状態が１０日あったです。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"その処分が適切だったのかどうかは、私は基準も何も認識もないのでわからないですけれど、適切だったのだろうという理解をしました。１名しか配置できなかったのが１０日間あったという点について、品川区としての見解と、こういう状況を出したことについて、区としての反省とこれからの指導を含めて、どういうふうに捉えているのか、伺っておきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"今回これに伴いまして、区の病後児に関する要綱、委託事業者との契約の仕様の変更、こういったことで、より正しいやり方でやれるよう、対応してまいります。","id":"exchange-052"},{"speaker":"南委員","kind":"意見","question":"病後児保育の受け入れについては、ここの保育園との変更というのは当然ですけれども、考え方として病気になってその後の何日間、１週間とか、そこをどういうふうに保育の手当をしようかというところなので、一定程度期間も予想できると思います。当然予約制になっているわけですけれども、そういう点で配置ができなかったのであれば、私は保育園側としては、気持ち的には、いい、悪い別にして……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"南委員","kind":"質問","question":"もちろんそのつもりで質問しています。受け入れたからには絶対、今日受け入れて、明日、保育を受け入れるということでは、病後児保育だから必ずしもそうではないと、私は思っています。その点について、見解があれば伺いたいし、なければ強力な意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"渡部委員","kind":"確認","question":"端的に、７月にそういうことがあって、８月から大丈夫ということで、そこはいいと思います。こういうことがあったときに、品川区内のほかの保育園はどうなのだろうと、当然聞き取りなり何なりなさっていただいたと思いますけれど、問題はないという確認だけさせてください。","respondent":"大澤保育支援課長","answer":"先ほど申し上げましたように、保育士の数、またシフト表は保育支援課でチェックしておりますが、今回のことを受けまして、９月１１日の私立保育園長会で、職員配置のルールにつきまして、改めて確認しています。","id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう１つは、どこからのお金をどこに返還するのでしょうか。４６０万円で４カ月なので、２５日で割ると１日４万円ぐらいでしょうか。加配している保育士の分の金額はどういうふうにして出ているものなのか、教えてください。","respondent":"大澤保育支援課長","answer":"８月から改善されていますので、４月から７月分の返還ということで、今回は考えております。４６０万円の金額ですけれども、運営費の一部になりますので、具体的には今後の運営費からの相殺という形をとろうというふうに考えております。","id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問","question":"運営費という大枠の中で、というお話ですね。その加配の分の４６０万円というのは、どういう計算で出たのか、教えてください。","respondent":"大澤保育支援課長","answer":"保育士が規定どおり配置されていることがまずあって、その上に加配をした場合の加算部分ですので、具体的には主任保育士加算、３歳児配置改善加算、特別支援保育加算の部分を返還していただくという計算になっております。","id":"exchange-057"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"細かいところまでありがとうございました。今、ほかの委員からもありましたけれども、非常に大変なことであったわけなので、今後このようなことが起きないようにお願いいたします。それも東京都からの話で発覚したということですので、区としても保育園行政についてはかかわりは非常に深いと思いますので、ぜひその辺をきちんと、先ほどの改善策をしっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862391?Template=document&Id=4960#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":42041,"voices":154}},{"id":"h30-20181211-5","meetingId":"h30-cm12","date":"2018年12月11日","dateIso":"2018-12-11","committee":"総務委員会","time":"午前１０時００分～午後 ０時２４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１２ページの財務４表増減額内訳が一番整理されていると思うので、ここから伺いたいと思います。その対比で、人件費は、何に当たるものなのかご説明いただきたいと思います。","respondent":"品川財政課長","answer":"ほぼ、委員がおっしゃったとおりです。基本的に、委託関係につきましては、この表の中では物件費という形で出しています。反対に人件費は、俗に言う区職員の給与、それから退職金等になるという形になってあります。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"そうすると、今まで行政がやっていたものが委託という形になると物件費で算出される。そういうところでは、このつくり方は区が特別につくっているわけではないのですけれども、実際の姿がわかりにくく実態との乖離が生まれてしまうのではないかと思うのですけれども、その点についてはどのようにお考えでしょうか。","respondent":"品川財政課長","answer":"要するに、前年度の退職人数等、例えば平成２８年退職人数と平成２９年退職人数など大きく数字が変わってしまうというふうな場合もありますので、なかなかこの表だけでは一概にいろんなことが示せるものではないと思っています。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは、一般的に民間の会社ですと、６ページの普通会計の貸借対照表を見れば、大まかなことはわかると思うのです。それで、公表にあたっては、ホームページに品川区公会計レポートを上げると思うのですけど、公表時期としてパンフレットは、「同時期」と資料に書いてありますけれど、どの程度の内容を掲載するお考えかお聞きしたいと思います。","respondent":"品川財政課長","answer":"いろいろ民間の貸借対照表とは、やはりどうしても行政の貸借対照表は違うやり方になってしまいますので、民間の財務諸表の知識でそのまま見てしまうと、いろいろ疑問点は出ると思いますけれども、行政の財務諸表のあらわし方にのっとって現在やっております。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうなると左右が一致しなくなるのではないかと、私は思って、それはどうなっていくのでしょうかというあたりはお答えいただいたのですけど、理解できなくて、その辺をどういうふうな扱いにしていくのか、ぜひ伺いたいのと、それからパンフレットには減価償却費は累計額だけがたしか載っていて、そのことが出ていないので、おっしゃったように、普通の民間の会計の知識で見ると。","respondent":"品川財政課長","answer":"いろいろ減価償却の点につきましては、現在のこのやり方ですと、民間の財務諸表と見比べていただくと疑問点が出てくるかと思うのですが、今、新しい公会計システムでやっておりまして、平成３０年度の決算から財務諸表を新しくつくるのですけれども。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"パンフレットもそのとき検討するということでよろしいですか。","respondent":"品川財政課長","answer":"詳細については、今現在、検討しているところですので、少しお待ちいただければと思います。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから公会計レポート、毎年きちんと見ているわけではないのですけれども、これはこういう状況であるみたいな、確かにレポートだなと思うのですけれど、もう少し評価みたいなところまで踏み込んだ表現がされると、せっかくホームページ上で公開されていますので、区民の方で財政のことがすごくよくわかる方もたくさんいらっしゃると思うので、そういう公表の仕方も。","respondent":"品川財政課長","answer":"表記の方法については、今後どうしていくか、検討していくということになると思います。他自治体で先行して、いろいろと新しい方式を用いた財務諸表を作っているところもありますので、そういうところも参考にして考えていきたいと思ってあります。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ検討していただきたいです。それから、ほかの自治体で既に始めているところには、成功している例もありますが、一回やってみたけど結局評価がうまくできなくて、議員の中での評価もうまくいかなくて、すぐに変更したという、ある意味、失敗しながら模索をしているところもありますので、ぜひそういうところも参考にしていただけるといいかと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"ということは、そのまま右側にいきまして貸借対照表の「資産」の「公共資産」の中に「道路、橋、公園、学校など」とありますが、これは、つくったときのコストがこのまま資産として残っているということなのでしょうか。教えてください。","respondent":"品川財政課長","answer":"「公共資産」のところです。公共資産については、今、普通建設費の費用というような形での積み方になっており、そういったところで固定資産という考え方とちょっとずれがあるというところが、今のやり方の問題点です。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"それと、ここには道路、橋、公園、学校とあるのですが、橋というのはやはり区で持っている橋もあるのですか。それで、公共施設の中で、おそらく土地も評価されていると思うのですが、公共資産の中の土地の評価は、ここに出す金額は、路線価をもとにして表記しているという解釈でよろしいのでしょうか。それとも別のやり方で算出した資産額をここに載せているのでしょうか。","respondent":"品川財政課長","answer":"ですので、基本的には路線価で、本来は固定資産という形も出したいというところがあるのですが、それは今度の財務諸表で多分なってくるのではないかと考えています。そこが、先ほど申しました検討次第ということになります。","id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"わかりました。資産において、投資などが７５６億３,０００万円とあります。この中には有価証券等も入っていますが、それに流動資産をたしあわせる総額１,０００億円を超えるというのは、すごい健全財政というのか、すごいと評価されるというのか。一応感想だけ述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-02","title":"特別区人事委員会勧告に対する特別区長会の対応","agenda":"特別区人事委員会勧告に対する特別区長会の対応","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"特別区人事委員会がどういう形でやるかわからないですが、もし来年やったときに、寄り戻しというか、一気にまた来るような気がするのですけど、そういう想定はせず、今回の引き下げに関しては従わないということなのか。来年、また調査をしたときに民間が低いという結果になったときは、ダブルパンチとなるのではないかと、すごく危惧するところなのですけれど、実際にどこまでお考えになっているのか。","respondent":"黒田人事課長","answer":"特別区全体の方向性としましては、特に主任の高位号給のところにかなり山があるということで、主任については係長職に任用するということで、労使との妥結の中でも係長選考を、特例選考というのを実施するということで、一定程度。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"前回の総務委員会での報告では、下げるというお話だったと思います。そして、毎年この基準でやりますということで、我々議会にも報告されているわけですが、では毎回、何かによって変わっていってしまうというのだったら、何も人事委員会の意見を聞く必要もないし、区は区の独自の考え方でやればいいという制度に見られてしまうのではないですか。その辺についてご見解をお聞かせください。","respondent":"黒田人事課長","answer":"今回は人事制度を改正し、８層制から６層制に変えた中で、職員構成が一過性というのでしょうか、どうしても階層を少なくしたことによって、一部ひずみが出たというところで、民間の比較の中でも、今、景気が緩やかに回復しているという中で。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"要は、毎年、人事委員会からこういうふうに勧告されるわけですから、やはりその辺に疑問を非常に感じますので、それだけはちょっと指摘しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"２つ伺いたいのですけれども、改定しないということは、具体的には条例の改正という手続にはならないということでよいのか。もう一つは特別区長会の見解を伺いたいのですけれども、今回、民間との比較で、とりわけ職員構成について比較したことで、こういう人事委員会勧告が出たわけですけれども、職員構成を比較することに合理性があるのか。特別区長会はそこをどう考えているのか伺いたいと思います。","respondent":"黒田人事課長","answer":"２つのご質問をいただきましたけれども、１点目の条例改正につきましては、今回、改定しないことを決定したですので、給料表の改定、特別給の改正を実施いたしませんで、条例改正を今回、提案しないということになりますので。","id":"exchange-014"}]},{"id":"topic-03","title":"上場株式等に係る配当所得等に関する住民税の税額再算定","agenda":"上場株式等に係る配当所得等に関する住民税の税額再算定","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"これは、品川区だけで起きていることなのかどうかというのが非常に興味深いところで、品川区の税務課が解釈を誤り税額の再算定につながってしまったというのか、２３区全体を見て、こういうことが、あちらこちらの区で間違った解釈をし税額の再算定になっているのか。できれば、増額分の一番多い人に幾らぐらいの増額になって、減額の方でどれぐらいが減額になるのかというのがわかれば教えてください。","respondent":"伊東税務課長","answer":"この解釈に関しましては、今、２３区レベルで聞いているところでは、２１区ほどが品川区と同じような解釈をしていたと聞いているところです。","id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今後の周知の部分で、郵送、送付するということですので、通常郵便なのか、どうなのかは別にしても、しっかり手元に届いて、配付して、中身を確認していただけるような形で、８０名程度ということなので、しっかり手元に届くようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"再算定ということは、つまりは間違ってしまったということだと思うのです。は具体的な手続の中でもそういうことが必要ではないかと思うのですけれども、その点を伺いたいと思います。あわせて、２３区の中で、品川区を含め２１区が今回こういう対応をするということですけれども、これに気づいたきっかけは何なのか。いつ頃気づいたのか。その点についても伺いたいと思います。","respondent":"伊東税務課長","answer":"それと、今回の発覚の経緯ですけれども、平成１５年の税制改正の中でこのような形がとられたということはあるのですけれども、そのとき、自治体まで、正確に説明が伝わり切れていなかったというところはあるのかと思っているところです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"いつ気がついたのかということで、今年の９月に、ある区からということであれば、品川区というよりも、２３区の中のどちらかの区がこの仕組みに気づいて、２３区の例えば課長会などで共有しながら対応を考えていたということになるのか、伺いたいと思います。私も大変不勉強であれなのですけれど、これは特別区だけの問題なのでしょうか。いわゆる全国的なことになるのでしょうか。","respondent":"伊東税務課長","answer":"課長会といいますか、その中で情報が漏れ伝わってきたということは確かにそのとおりでございまして、それでどうしていこうかという話があったところなのですけれども、そもそも平成２９年の改正の中で、そういうことが明確になったということも一方であったということで。","id":"exchange-018"},{"speaker":"中塚委員","kind":"意見","question":"こういったことがないよう、今後とも点検をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり私はこういうときは国に対して、通達が悪かったのではないかという、謝罪を逆に要求するようなことが必要ではないかと。これは、品川区だけというならわかりますけど、日本全国で、おそらく同じような状況だと私は思うので、本当に一度ぐらい、国に謝罪を求めますというような意見書を出していいのではないかと思いますけれど、いかがですか。","respondent":"伊東税務課長","answer":"平成１５年の改正で、平成１７年度からそうなったというところなわけなのですけれども、今回、こういうことが発覚しまして、都および国にも、そのときの状況、なぜ我々がそういう解釈になったのかというところについても説明を求めたところですが。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"１つだけ、かなうのであれば、私はやはり、区が悪かったというようなことは書かないで、区民に報告してほしいです。国の曖昧な通達によって、こういう事件を起こしてしまったということは、やはりそもそもどこが決めたんだという話ですから、私はちょっとそういうふうにしていただきたいという意見を言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"そこの家は、たまたま、聾というのですか、生まれつき難聴の人ですから、やはり声の出し方が、ちょっと違うわけです。企業に向けて、品川区は何かやっているのですか。もちろん、品川区の職員に対しての研修というのは、庁内だからあれなのですけど、大体、品川区の企業も大きな企業がありますので、そういうところにはどういう周知というかをしているのか、教えてください。","respondent":"島袋人権啓発課長","answer":"ですので、おのおののケースに関しまして、特に人権啓発課に上がってくるということではございませんで、まずは生活圏ごとの連携・情報共有から、その部門におけるケース対応までをしっかりと連携してやっているというのが、このシステムの流れです。","id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問","question":"それで、東京都が言っている警察がすぐ動くというのも、動くケースと動かないケースがあるというのは間違いないわけですから、それは本当にどこからどこが暴力なのか、警察も、動かないときは何度言っても動かない。数値は出ているわけですから、この背景に何があるかを、東京都に聞いたらそう言っていますというのはちょっと違うのではないかと思うので、しっかりやってくださいということ。","respondent":"島袋人権啓発課長","answer":"今後、私どもも、やはりこのアンケートをとったことによりまして、また次に何をしようかと、企業といろいろ検討しながら進めていくことができるかと思いますし、このアンケートを十分に活かしながら検討してまいりたいと考えているところです。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問・要望","question":"いまだに努力義務だと思っている会社もあるかもしれないし、小さくなればなるほど、そういうことが行われる可能性もあるし、大きければ、そこまで見えてこない部分もあると思いますので、そういうのをしっかりと、各企業とも連携をとって進めていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"そういう意味では、何が暴力に当たるのか、身体的なものはもちろん、言葉、経済的、性的、さまざまあるかと思うのですけれども、そういうことの周知も、講演会などさまざまなところで触れていらっしゃるとは思うのですけれども、幅広く伝えていって、私も含めて自分自身をそのとき点検できるような形になっていくと、一歩ずつまた進んでいくのかと思うのですけれども、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"私どもは、その手だてを整えるといいましょうか。何か心配だけれど、とりあえず電話してみて、安心していただく。あるいは重要なケースにつながりましたら、きちんと対応していただけるように努めるものが責務だと考えておるところです。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"暴力というのは感度の問題や程度の問題ではなく、個人の尊厳を力で奪うもの、踏みにじるものであって、相手がどう思うかというところだと思うのです。それほど批判しているつもりはないのですけれども、そういう意味で、ここで言っている児童、高齢者、障害者、配偶者への暴力やパートナーによる暴力とは何かを改めて伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"受けとめ方がいろいろありますので、相手のことを思いやる心というのが実は人権の一番の大もとだと思っているところですので、まずは相手を思いやる気持ち、そして「あなたのそばにいて大丈夫なんだよ」ということがわかるようなことというのが、本当にふだんの日常生活の中で。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、暴力のない社会の実現に私も力を尽くしたいと思います。続いて、性的マイノリティについて若干伺いたいのですけれども、資料にある３ページの一番下に、東京都が条例を成立させまして、性自認および性的指向を理由とする不当な差別をしてはならないとしているとありますけれども、区もこの立場と同じなのか。","respondent":"島袋人権啓発課長","answer":"条例に関しての区の考え方ですけれども、区におきましては、やはり人権尊重都市品川宣言がありますので、その宣言文と、やはりまだまだ知っていただけていない部分があるので、そちらを周知するのと同時に、やはり東京２０２０大会は、品川区も開催地域ですので。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまりは、実は理解促進なのか差別禁止なのかという議論がありまして、私は、差別を禁止するために理解を広げていきたいと思っているのですけれども、この議論があるだけに、品川区としては、この性自認および性的指向を理由とする不当な差別をしてはいけないと思っているのかどうか、確認させていただきたいと思います。","respondent":"島袋人権啓発課長","answer":"実は、品川区の人権尊重都市のチラシの後ろ、２３区唯一の人権宣言が２５周年を迎えましたという書き出しで書いているものの中に、やはり性的指向を理由とする偏見や差別をなくそうということで、同性愛者など性的指向に関する少数派の人々への根強い偏見があり。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"私もそのとおりだと思います。例えば、最近はどうなのでしょう、あまり聞かないですが、女性だからお酌しなければいけないとか、女性だから優しく接しなければいけないとか、逆に男性だから泣いてはいけない。そうした実態アンケートを実施したり、またこの間、求めてまいりましたが、同性パートナーシップ制度についても前向きに議論を進めていただけたらと思うのですけれども、あわせていかがでしょうか。","respondent":"島袋人権啓発課長","answer":"働き方ももちろん、多様な働き方も含めてなのですけれども、多様な人々が対等な立場でお互いを尊重し、支え合って、ともに生きていく社会というものが、ある意味、共生社会という言葉になるかと思っているのですけれども、この実現のために。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"なので、ぜひ、どこにやはり違和感や苦しみがあるのか把握するためにも、世田谷区などは実施しているのですけれど、アンケート調査の実施や同性パートナーシップ制度についても前向きな検討が進められたらと思うのですけれども、改めていかがでしょうか。","respondent":"島袋人権啓発課長","answer":"それが悩みだということがありますので、まずはそういったアンケートに自信を持って回答できるような雰囲気というのですか、そういった状況をつくるものも大事ですし、また人権の意識調査などでも、やはり性的マイノリティの方のこと等の設問を検討しておりますので。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"このパンフレットにありますけれど、しながわ見守りホットライン、２４時間つながりますと、こういうものを、町会の掲示板なり品川区のふれあい掲示板なりに、片隅でもいいですから、常時、皆さんの目に届くようにしていただいて、そういう電話をしたら相談窓口に対しての橋渡しということを今後もやっていただき、多くの人たちの声を聞いて、また励ましてやり、また相談に乗って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"最初に資料の、これが結局、様々な所管課が絡んでくるから、本日は人権啓発課からのということだと思うのですが、虐待防止ネットワーク協議会の役割と構成員で、これは、どういうときにどういうふうに、誰の呼びかけでどういうふうに開かれているのかとか、その辺の情報があれば伺いたいと思います。全庁的な仕組みだと思いますので、今お答えできる範囲で結構ですので、お答えいただきたいのですけれど。","respondent":"島袋人権啓発課長","answer":"なぜ７月に開催になってしまいますかというところなのですけれども、まず年度が変わりまして、７月に実施するに当たりまして、警察に、会議への出席をお願いするに当たりまして、非常に時間がかかるものなので、時間的には４月から動かないと間に合わないということで。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"本当に命にかかわるというところなのですけれども、基本、１１０番、警察署などだと、何かあったら、もう遠慮なく、どんなケースでも警察署や１１０番に通報していただければと言っていただけるのですけれど、命にかかわるかどうかという判断を誰がするのかということなのです。その辺が、どういうふうに考えられているのかということを伺いたいのと、それからＤＶの所管課は、人権啓発課ですか。","respondent":"島袋人権啓発課長","answer":"は夜間・祝日受付マニュアルというものがございまして、それに基づきまして専用ダイヤル対応をしていますが、本当に、先ほど委員のお話しされた、生命・身体に危険が及ぶと、通報を聞いて感じたときには、通報者本人に１１０番通報をお願いしています。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"人権啓発課としては人権啓発に関する施策を進めていらっしゃるわけですが、それぞれの所管の施策としては、まずは当事者同士の解決となってしまうと、うっかりすると、このしながわ見守りホットラインが、一番その内容を知られたくない施設に通報が行ってしまったみたいな、あなたたちで解決してくださいみたいになってしまう可能性があるので、その辺を、それぞれの所管でやるべきことは当然として。","respondent":"島袋人権啓発課長","answer":"所管課と人権啓発課のつながりというところですけれども、正直申しまして、やはり生活圏ごとの連携、情報共有が中心で、その後、こちらに上がってくるというシステムにはなってございませんので、まずは各ケース対応というところでしっかりと対応していただき。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"なかなかやはり人権という視点で全体をつなぐということは、まだまだ始まったばかりなのかと思いますので、それはぜひ人権啓発課がリーダーシップをとるような形で進めていっていただきたいと思います。さっきのデートＤＶなのですけれど、同じことがやはり夫婦間でもあり、経済的ＤＶのことが抜けているので、家庭内のＤＶにも、ぜひ意識を持っていっていただきたいと思います。これは要望です。","respondent":"島袋人権啓発課長","answer":"今まで「マイセルフ」の冊子なのですが、医師会だけに配布していたという経緯がございまして、第５８号からは、医師会、歯科医師会、薬剤師会にも配布するようにお願いしたところ、とても好意的に受けとめてくださいまして。","id":"exchange-035"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"試行中ということがどういう形で試行されていて、今、検討段階がどの辺まで進んでいて、もしわかれば今後の方向性ということをどのようにお考えか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"１点目は、社会保険労務士の労働環境チェックということを、これはアのところで平成２６年度からと記載させていただいてあります。実は資料にはないのですが、年度途中で区の内部の検討がありまして、平成２６年度の途中から始めたというものです。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"それと、(2)の事業・運営状況調査なのですけれど、財務状況の確認というところに、公認会計士が入ってくると理解していいのでしょうかというのが１つ。それから、財務状況は公認会計士だと思うのですが、利用者へのアンケートの内容などはどこで検討されて、どういうふうに実施されたのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"いわゆるこれは監査のようなものですから、非常に時間がかかるというのがありまして、それは社会保険労務士のほうの負担もあった部分がありますので、では評価の仕方について、例えば面接の時間を少し変えてみるとか。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。生活者ネットワークとしては、ぜひこの評価の仕方は、全施設を対象にしていただきたいというのと、結果についてぜひ公表していただきたいと希望いたしますが、その辺についてコメントはいかがでしょうか。","respondent":"柏原企画調整課長","answer":"ですので、例えばサイクル、これも毎年全部というのは到底、厳しいので、例えば何年かに１回、例えば５年という１つのサイクルがありますので、その中でどのタイミングでやるかとか、そういったことも含めて検討しています。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、少なくとも議会の中で指定管理者というのは決めていくわけですし、それから評価もしていると思います。評価というのは厳しい評価ばかりではなくて、こういう指定管理者はすごくやはりいいよねという評価にもつながるわけですから、ぜひその方向で進めていただきたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"多岐にわたって伺いたいと思いますが、資料に、社会保険労務士による労働環境チェックとありますけれども、どのような共通項目でチェックしているのか伺いたいと思います。例えば給与や年休取得率や休暇や超過勤務の実態や労働時間など、さまざま労働環境といっても把握の仕方があるかと思うのですけれども、どこを共通項目としてチェックされているのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"労働環境チェックのところですけれども、今ご指摘があったところ、いわゆる一般的に言われる労働の環境、休暇であったり給与の面であったり福利厚生であったり、法令に照らし合わせながらということで、この部分については、ほぼ全てチェック内容に入るというものです。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"それだけに、労働環境について、モニタリング評価の中なのか、また議決のときなのか、要するに議決や報告のときに、しっかり議会に資料を示していただきたいと思いますが、いかがかということと、従来、区は指定管理者で働いている者の労働条件については把握しないという立場であったかと思いますが、今回の動きというのは、区自身も、例えば平均給与だったり勤続年数だったり。","respondent":"柏原企画調整課長","answer":"お示しの仕方の部分ですけれど、どういった施設をどういったタイミングで出すかといったことも含めて、今、検討しているですので、中身についてはもう少々お時間をいただきながら、お示しできる形に持っていきたいと思ってあります。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん１点集中というわけではなくて、ここだけのテーマで聞いているという趣旨なのですけれども、先ほど伺ったのは、区はこれまで指定管理者で働いている方の労働条件は把握しないという立場だったけれども、今後は区も把握して、公表の仕方は今検討されているという話はありましたが、区としてもそれぞれの指定管理者、とりわけ社会福祉法人の労働条件を把握するという立場ということなのか。","respondent":"柏原企画調整課長","answer":"繰り返しの部分はあるのですけれども、公の施設としてきちんと運営、事業がなされているか、人云々ということにフォーカスするのではなく、事業を運営するためにきちんとした状態にあるかどうかというのを確認するという趣旨でやってきているものです。","id":"exchange-042"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"つまり、任意になっているということですよね。たしかにホームページ上も任意になっているのです。ただ、任意であるけれども、その表現というところはまた今後しっかりとご検討をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/643576?Template=document&Id=2126#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":41537,"voices":123}},{"id":"h30-20181212-14","meetingId":"h30-cm12","date":"2018年12月12日","dateIso":"2018-12-12","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時４２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","topics":[{"id":"topic-01","title":"改めまして、新公会計制度に関することのうち、財務諸表等の活用","agenda":"改めまして、新公会計制度に関することのうち、財務諸表等の活用","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"１ページ目に、官庁会計は、図のところに単式簿記・現金主義とありますけれども、品川区の新公会計制度というのは、要は企業会計で用いられている考え方の複式簿記・発生主義会計であるのかどうか、確認をお願いしたいと思います。複式簿記・発生主義とは、新公会計制度においては何を意味するのか、簡単に説明していただけないかと思います。","respondent":"齋藤会計管理者","answer":"なぜかというと、わかりにくいのですけれども、先ほどちょっと話をさせてもらった、１００万円の車を買うと、１０年後に廃車するときまで１００万円の価値があるものという形しかできません。それは現金の出と入りがないからです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"なぜあえて発生主義や減価償却という考え方を導入するのか、伺いたいと思います。","respondent":"齋藤会計管理者","answer":"何が言いたいかというと、インフラ資産というものは５０年、６０年と使うので、今の住民の方ではなくて、将来世代にも負担してもらおうという考え方。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"次に行きます。７ページの上のところに、新公会計制度導入で施設の統廃合を検討することが可能になると書いているのですけれども、なぜ導入することで統廃合を検討することが可能になるのかということを、改めて簡潔にお伺いしたい。最後に、ＰＰＰ／ＰＦＩでの活用も進んでいくと書いてありますけれども、なぜ進んでいくのか、それぞれ簡潔にお伺いしたいと思います。","respondent":"齋藤会計管理者","answer":"１つ目の統廃合の事例は、今までは非コスト情報しか出ておりませんでしたが、コスト情報が出ると維持管理が、例えば財政上、５つあるうち２つしかできない、３つしかできないということになったときに、選択をするにあたっての基礎的な資料となるということになります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"先ほど地元の事例なども詳細にご説明いただきながら、なかなか大変な状況だと考え聞いておりました。そういう状況になってしまうわけです。企業会計だったら利益を出すことが目的で動いていますから、それでいいのかもしれませんけれども、住民福祉の増進を使命とする自治体の公会計ではなじまないのではないかと思いますが、いかがでしょうか。","respondent":"齋藤会計管理者","answer":"先ほど図書館の例を申し上げましたけれども、例えば全部年金暮らしでお年寄りだから、住民で運営するから残してほしい、そういった議論もあるかもしれませんし、統廃合、廃止ありきではないのだろうと考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それが、納税の対価としてのサービスとして認識されるようになってしまう。これはもう削除されましたけれども、こういった全ての福祉サービスを見える化し、コスト主義で考えるやり方というのは、私は区民サービスの削減や低下につながってくると思うのですけれども、いかがでしょうか。新公会計制度で作成される財務諸表等の活用というのは、私は慎重にすべきだと思うのですけれども、いかがでしょうか。","respondent":"齋藤会計管理者","answer":"公会計制度はあくまでフルコストを見ていただく、あるいは財務状況がどのような状況か見せることでありまして、新公会計制度があると福祉サービスが削減されるということはないものと考えております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"意見","question":"私は現状のままで、新公会計制度の活用を進めるのは問題があると思います。この導入によって、施設の統廃合、受益者負担の適正化つまり負担増、あるいは民間委託の推進は、公共サービスの低下が加速することにつながると思います。現状のままで、新公会計制度の活用をどんどん進めていくということには反対です。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"確認","question":"例えば土地もそうですけれども、公園もそうですし、区有施設、また区が買い取った土地云々があると思うのですが、この中で、ほかの用途にすぐ使える土地、また売却もできるという土地、これは当面売却できない、３０年はだめとか、そういうものもあるので、その辺ももし数字だけでも書いておいていただければ、民間のものに準じて読み取ってくださいということなのですけれども、実際。","respondent":"齋藤会計管理者","answer":"最初のご質問、行政評価シートのことで、７００近い事業がありますが、大分職員は苦労しておりまして、来年度の決算議会でどれほどお出しできるかを検討中で、行く行くはお出ししたいと考えております。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"今、簿価が最後は１円という話でしたけれども、たしか民間は１０％を残すような、簿価を減価償却で残していると思ったのですが、もし行政が違うやり方なら、それをまた教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"須貝委員からもありましたけれども、説明を改めてお伺いさせていただいて、細かく教えていただきまして、ありがとうございました。そうなったときに、少し今の基金のあり方というのも、せっかくわかりやすくなったのであれば、もっと細分化して、それぞれにこれだけかかるというのが見えるような形に変えていってもいいのかなと思ったのだけれども、そういう考えというのはあるのでしょうか。","respondent":"齋藤会計管理者、品川財政課長","answer":"それが新公会計制度によって、数字的にも裏打ちをして、かつ委員の皆様をはじめ、区民の皆様に、よりご理解いただけるということだと思ってあります。基金の見せ方なのですけれども、当然こういう貸借対照表の中で、資産という形の部分で出していくことになりますので、そういう見せ方についても今後いろいろと検討していきたいと考えています。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"必要な施設は当然、更新をしていかなければならないわけです。総くくりで１,０００億円という形にするのか、それとも例えばこういうもので幾ら、こういうもので幾らというのがかかるから、こういうふうになるのだという見せ方でも、私はいいのかなと思いましたので、考え方としてお示しさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"ＩＣＴなどの活用に関することのうち、区民サービスの電子化","agenda":"ＩＣＴなどの活用に関することのうち、区民サービスの電子化","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ご説明ありがとうございました。区でもこうした仕組みというのを検討してはいかがかと思うのですけれども、お考えがあれば伺います。","respondent":"山本情報推進課長","answer":"こちらにつきましては、中野区が導入しているということで、調査等をさせていただきまして、導入等をどういった形でできるのかというところも踏まえつつ、関係所管と連携しながら研究をしていきたいと考えています。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"説明ありがとうございました。多分、私の選択できる学校はどこですかとか、通学区域はどこですかとか、ある程度質問も想定される。選択行動は平成３１年１０月から始まるわけだから、もう１年を切っているわけで、しっかりとしたシステムといいましょうか、きちんと開発をして、これはやってほしいと思うのですけれども、どうでしょうか。","respondent":"山本情報推進課長","answer":"学事制度変更にかかる問い合わせへの対応というところですけれども、まず、ＡＩチャットボット導入を進めるに当たりまして、一番大事なところが、良質なデータを作成して、それをＡＩに学習させていくというところが一番ポイントになってくると考えています。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"いいお話が聞けました。そこまで知らなかった。こっちも、要望という形でお話を入れていたのですけれども、絶対そこに質問が集中するのは想定されているわけだから、何とか頑張って１０月に、もっと言うと９月ぐらい、選択行為が始まる前に間に合わせてほしいという思いがありますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"だから、ＡＩを構築するまでに大変な労力が要るということなのですか。それを今日はお聞きしたかったのです。その聞きたいこともさまざまだから、その情報がなかったらＡＩは正確に回答できないわけですから、導入するには膨大な作業を要することなのかなというのを、本日質問したかったのです。ということは、これは相当の労力、時間がかかるのかなと思ったもので、それについてお聞かせください。","respondent":"山本情報推進課長","answer":"所管の状況によるのですけれども、所管のほうで、よくある質問等を既に電子化しているところもありますので、そういったところで導入を進めるということになりましたら、比較的負担は少なくなるのかなとは考えてありますが。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"今、千単位とかいうお話ですけれども、実際は千単位どころではなくて、万単位なのかもしれないと思うのです。そうすると、日本全国これだけ自治体があって、どこかで誰かがやってくれると、その情報を一部修正すれば、区も使いやすいのかなと。そういうところは実際ないのですか。","respondent":"山本情報推進課長","answer":"先行自治体の事例をそのまま、ほかの自治体も使えるようにというところなのですけれども、そこまで詳しく話は聞いていないのですが、そういった形でパッケージ販売とかを今、検討しているという事業者もあると聞いてあります。","id":"exchange-015"},{"speaker":"須貝委員","kind":"提案","question":"それはそれで議会に提案していただければいいのかなと思います。ただ、相当膨大な日数はかかるのだと思いますので、少しずつ、一歩ずつ、慎重に進めていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"情報推進課で技術的なアドバイスも含めて会議に参加をして、作成の主体は当然、委託先の業者ということで、課としては、アドバイスというか、アプリに関してはどの程度、区としてそういう情報というか、知識というか、蓄積があって、例えばこの1)番のアプリに対しては、具体的にこういうアドバイス等をしてかかわりましたとか、そういう具体例があれば教えていただきたいと思います。","respondent":"山本情報推進課長","answer":"かかわり方というところになりますけれども、例えば4)のしながわ予防接種ナビというところで、今年１１月から始まっているものになりますけれども、対象としてはお子さんを持った、予防接種を受けるような時期になった方がターゲットになってくるのですけれども。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"今後のＩＣＴ活用というところで、１つお伺いしたいと思うのですが、４の（２）番のデジタル化の推進ということで、今後考えていることで、オンライン上での手続の一元化とされているのですけれども、何かもう具体的にどういったことを行うお考えがあるのか、まずその点をお伺いしたいと思います。","respondent":"山本情報推進課長","answer":"国が指定した子育て分野４業務について、ここで手続の電子申請であったり、内容を確認できたりというところでの運用を始めてあります。こちらもこれから本格的に進めていきたいと考えています。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"そこで、具体的に、こういうものの一元化というのはどうなのかというところなのですけれども、亡くなった後のご家族の方が手続をする戸籍住民課だったり、国保医療年金課だったり、あるいは介護のことだったり、こうした煩雑な手続が、電子化によって一元化をされるということについて、どのようにお考えでしょうか。","respondent":"山本情報推進課長","answer":"ただ、具体的にどう進めていくかというところは、我々のほうには情報はおりてきていないところですけれども、早急に対応できるように準備等はしていきたいと考えています。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうした動きがあるということなので、区としてもそのお考えはお持ちだということですね。ぜひ進めていただきたい分野でありますし、国の動きを待たず、区としてどのようにされていくかというところを、もう一歩お聞きしたいところなのですけれども、本当にこの手続は煩雑なのです。こんな考え方はいかがでしょうか。","respondent":"山本情報推進課長","answer":"ワンストップサービスというお話かと思いますけれども、現状は各課それぞれ所管のシステムを使って、いろいろな手続を処理するということで、例えば国保と戸籍だと、今は別のシステムを使っておりますので、そこの連携というのはできない状態なので。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ研究をしていただいて、やはり品川区はそういったところまでしてくれるのだというところまで、ぜひつくっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"新妻委員","kind":"確認","question":"ご説明ありがとうございました。今、ここに４つ挙げられておりまして、若林委員から、所管課との連携がどうなっているのかという確認がありましたけれども、所管課から上がってきたことに対して情報推進課がアドバイスをするという形ですが、逆に情報推進課から、アプリでこういうことができるのだというアドバイスというのはされているのでしょうか。","respondent":"山本情報推進課長","answer":"情報推進課と各課連携の話かと思いますけれども、現在は各所管から上がってきたものに、情報推進課が後から入っていき、一緒に進めていくという方法で進めているところです。","id":"exchange-022"},{"speaker":"新妻委員","kind":"質問・要望","question":"その情報を持っているのは、やはり情報推進課だと思うので、各課の情報を１つにまとめて、これは１つにできる、例えばアプリがこういうふうに開発ができる、これは電子化ができる等々のアドバイスを、ぜひ情報推進課からしていただきたいと思いますし、それが区民サービスの向上になると思いますが、今後その辺はいかがでしょうか。","respondent":"山本情報推進課長","answer":"システムの連携といいますか、一元化というところは、こちらで必要な部分について研究を進めていきたいと考えているところです。","id":"exchange-023"}]},{"id":"topic-03","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"正副提案どおりの調査事項でまとめを行うことでよいと思いますけれども、幾つか意見を述べさせていただきたいと思います。庁舎のあり方のところなのですけれども、1)のところで、建物の寿命を鑑みれば、建て替えに係る必要な事項について検討を始める時期とありますけれども、これでは老朽化で建て替え待ったなしという印象を持ちます。しかし、庁舎の寿命というのは、あと１８年あります。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"ですから、報告を上げるときに、当然総意で委員会としての報告は出すにせよ、それぞれ各会派、個人からの意見というのは尊重されるべきなのでしょうから、特定会派から、これはだめとかというのではなくて、総合的に正副で判断をいただいて、つくっていただければと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/319862?Template=document&Id=6062#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":32402,"voices":69}},{"id":"h30-20181213-18","meetingId":"h30-cm12","date":"2018年12月13日","dateIso":"2018-12-13","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"の２の特定事件調査","agenda":"の２の特定事件調査","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"このオリンピック・パラリンピック教育実践事例集を見ますと、本当に地域に即したとか、それぞれの学校が非常にバラエティに富んだ内容になっているというところがあって、オリンピック・パラリンピック教育との関連という意味では、テーマがオリンピック・パラリンピックの精神、スポーツ、文化、環境となっていますから、そういう意味では非常に幅広い分野をテーマとして捉えているので。","respondent":"熊谷指導課長","answer":"東京都からは「こういったものがありますよ。」という事例が平成２７年度から示されており、それらが掲載されている東京都のホームページを活用することもあります。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問","question":"その平成２７年に東京都が示したものというのは、例えばどのようなものがあったのかをちょっと紹介していただけますでしょうか。","respondent":"熊谷指導課長","answer":"」と説明した、そうした授業で内容を紹介したものが事例の一つとして示されています。","id":"exchange-002"},{"speaker":"塚本委員","kind":"意見","question":"一般に私がそれまで承知していたのは、よくオリンピアンを呼んできていろいろな講演をしてもらうとか、そういう形がやはりスタンダードなのかななどと思っていたのですけれども、やはりオリンピック・パラリンピック教育というものは非常に幅の広いものだということと、そういう意味では各学校のオリジナリティを活かしていけるという方向性は、非常によい方向なのかなという思いを今日は強めて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしてこういうことを聞いているのかというと、この前、厚生委員会でも出てきて、福祉計画のときにも言ったのだけれども、各学校で例えば障害者、それから高齢者、そういう人たちと小学校が触れ合う場、これも教育の一つで行っていて、地域で支えるというのは福祉計画の中にもそういうのが入っていて、じゃあ、教育という形になると、今日もそうなのだけれども、どうしても各学校対応じゃないですか。","respondent":"熊谷指導課長","answer":"もう一つ、国際交流ということもレガシーとして残していく。そのために、今全校で「世界ともだちプロジェクト」に取り組んでいますけれども、それを継続していくことを考えています。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"お願いだけにします。ところが、どういうわけかあの福祉計画をつくったときは、教育委員会の方はお１人しか出席していなくて、基本的には協議会の中では福祉の部門の人が多いわけじゃないですか。授業でやるのと、実際に肌で触れるのと大分ちがうじゃないですか。今度ウィルチェアーラグビーもやられると言っていたけれども、そういう体験と今日みたいな授業というのは全然違うじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"１点だけですけれども、「世界ともだちプロジェクト」で気になったのですが、どこの国とどこの学校が交流するかということについては、どなたがお決めになるのでしょうか。","respondent":"熊谷指導課長","answer":"参加予定国の中からオリンピック・パラリンピックを開催した国プラス、４つの国の中から国割りの表がありまして、その中から選んでおります。選んだのは各学校です。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、東京都で一つのデザインをつくって、その中から各幼稚園や小学校、中学校、義務教育学校等が学校ごとに選んだという判断でよろしいでしょうか。","respondent":"熊谷指導課長","answer":"加えてスイスも追加しています。こうした東京都から示された、バランスよく五大陸が入ったグループから、それぞれの学校・幼稚園が選んだです。","id":"exchange-007"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"これは教育委員会なのかオリンピック・パラリンピック準備課なのかわからないのですが、このオリンピック・パラリンピック教育実践事例集の４９ページを見ていたときに、アワード校の下のところに、米印で平成３０年度から東京オリンピック・パラリンピック競技大会組織委員会の競技名に準じて「ブラインドサッカー」を「５人制サッカー」と表記しますと出ていたのですが、教育委員会はこれで表記して。","respondent":"辻オリンピック・パラリンピック準備課長、熊谷指導課長","answer":"私どもではいつもブランドサッカーという通称名でずっと通していたもので、大会組織委員会的に、競技名称としては５人制サッカーというのが正式なものです。けれども、都から表彰されるようなときには「５人制サッカー」という表彰になりますので、このようにブラインドサッカーと５人制サッカーを併記する形で、公的に正式名称はお示しするようにしております。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"もう一つ、八潮わかば幼稚園の説明の中で、日本人としての自覚と誇りをもってというところなのですけれども、子どもたちが育つ場の中には、今いろいろな国の子どもたちがいます。なのでその子どもたちに対する配慮というか、その部分についてもちょっとお聞かせいただきたいと思うのですが、いかがですか。","respondent":"熊谷指導課長","answer":"市民科のどの部分でというご質問だと思いますけれども、５つの領域の中で、人間関係形成能力というところがあります。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"私が気になったのは、その幼稚園の中にいるいろいろな国の子どもたちのことで、日本人としての自覚と誇りをその子たちに何か強く求めたりとかしていたら、ちょっとかわいそうだなと思ったので、そういうことはないという確認をさせてください。","respondent":"熊谷指導課長","answer":"やはり国際社会の中で生きていくためには幼児期から多様な文化について知るということが大事です。その際、日本の伝統、文化に誇りを持ってというところは非常に重要だと考えていますので、そこと国際理解との融合した指導をしていくという内容です。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"私は日本の伝統や文化というのは大切にしていきたいと考えていますけれども、やはりそれを大切にしていきたいかどうかというのは、子どもたち自身が考えることだと思うのです。なので、その辺はちょっと気をつけていただきたいなと思います。","respondent":"熊谷指導課長","answer":"それは自国の文化でもあり、他国の文化でもあります。自国の文化をしっかり知って、大事にして、そして我が町や自国を大事に思う気持ちがないと、他国のことも愛することができない、理解ができないと思っています。ですので、両輪だと考えています。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問","question":"私もちょっと質問させていただいて大事だというところがあると思うのですが、ほかの学校でも学び方の違いで、そういった貴重な２０２０年の東京オリンピック・パラリンピック競技大会を迎えられるような取り組みというところで言うと、先ほど石田秀男委員もおっしゃっていましたが、もう一歩踏み込んでみんなで組織としてこれをやっていくというような形はあるのかなと思いました。これは意見です。","respondent":"熊谷指導課長","answer":"それを意識してなくさないようにしていく。長野大会のときもそうなのですけれども、当時始まった一校一国運動が今でも続いている。今、始まったばかりの国際交流が、１０年後もつながっていくようにしていきたいと思っているところです。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"そのあたりというのは長野の場合、どのような形で行われてきているのか。今後東京というくくり、ないし品川区等では、その今もとにあったような形で継続して、もう既にこの今日いただいた冊子の５３ページにもあるとおり、決定しているものだけでも８つあるのですね。その支援という部分での具体的なところはどうやって支えていくのか教えてください。","respondent":"熊谷指導課長","answer":"実際、品川学園でもスカイプを通じた交流を行っているところなのですけれども、教育委員会におきましてもルネサンス予算という、学校がこんなことをやってみたいと考えている夢をかなえるような予算をつけているところですので、そうしたものを活用しながら。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"これは要望です。日本のパラの選手とかも接する機会はあると思うのですが、そういう教育の場でもそうした機会をぜひ海外のアスリートでパラアスリートと、という機会とか、サッカーとかでそういう機会はあると思うのですが、国同士とかそういったところの機会もこの世界ともだちプロジェクトを通じて、何らかの形で交流できるように考えてほしいと思うのです。何かあれば教えてください。","respondent":"熊谷指導課長","answer":"同じように、城南小学校の事例が１０ページから１３ページに出ているのですけれども、城南小学校では「品川を知る」ということで、昔と今の品川、品川寺の鐘がスイスとつながっているというようなことも含めて学ぶことで、町への愛着や誇りを持つような取り組みをしました。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"前半のほうのことは、今、中延小学校のところで確認させていただいて、非常にすばらしいなと、子どもたちの感想は大事だなと思って、なので別にどこの国であれ地域であれ、自分が生まれ育ったところに誇りを持てるように促していくという、そういったことも認めていく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このオリンピック・パラリンピックの学習の時間が１学年３５時間ということで、西川校長先生のほうからもありましたし、いろいろなところに出ていますけれども、この３５時間というのはどのように確保していくのかなというところで、ここに小学校、例えば延山小学校だったら市民科と体育科と書いてあったり、学校によっては市民科だけだったり、市民科と社会科という形で書いてあるのですけれども。","respondent":"熊谷指導課長","answer":"例えば図工でもいろいろな国の子どもたちの作品を見てそのよさを話し合うですとか、さまざまな教科できちんと意識しながら行っていくということが重要であると考えています。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところを、とりわけこれは日本人というところに当てはめて、そこでそれを「日本人としての自覚と誇り」という形で子どもたちに教えていくというのはどうなのかなという違和感があったので、ちょっとそこら辺のところをお聞きしたいのと、もちろん日本人として、その日本の歴史や文化をしっかりと学ぶということはもちろん大事なことだとは思いますけれども。","respondent":"熊谷指導課長","answer":"先ほど国旗のことが出てきたのですけれども、これは外務省のプロトコールによるものなのですが、やはり外国からのお客様をお迎えするときにきちんとしたプロトコールを知らないと、国際人として恥をかいてしまうので。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"負の歴史も含めて、そういうところをしっかりと学んでいくところは大事だと思いますけれども、その中で、日本人だからできるのだというような形でちょっとここには書かれているという思いがしましたので、日本人としての自覚と誇りというのが日本人だからというのではなく、やはりお互いに国際社会の中で理解し合うところで歴史や伝統をしっかりと学ぶという形で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"１点だけ伺います。今日の授業の内容も大変すばらしかったのです。１点伺いたいのは、今までの質疑の中で出てきていたら申しわけないのですが、この教育において文化プログラムについての扱いは、どのような形で子どもたちに教えていらっしゃるのか。やはりこのオリンピックの一部であるわけなのですけれども、当委員会での調査事項になっていますが、これについてその対応を伺いたいと思います。","respondent":"熊谷指導課長","answer":"平成２８年１月に「東京都オリンピック・パラリンピック教育」実施方針が出されているのですけれども、その中でも東京２０２０オリンピック・パラリンピック競技大会２年前に当たる本年度は、文化プログラムへの参加が、「文化」というテーマの中の「する。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問","question":"そうすると、この前のスクエア荏原でのUNITE HEART FESTIVAL、あれはしながわ文化プログラムだったのですが、あそこにもお近くの学校の生徒さんには参加するように促したということでしょうか。","respondent":"立川文化観光課長","answer":"いわゆるUNITE HEART FESTIVALにつきましての周知です。チラシにつきましては区内の小学校全校で配布するように依頼したところです。教育委員会のほうから直接というわけではなく、文化観光課のほうから各学校にお願いしたところです。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。オリンピック・パラリンピックという観点でのプログラムには、ぜひ品川の子どもたちも文化プログラムとして参加していただきたいということで、ぜひ連携をとっていただいて、教育委員会からもそういうことを推し進めていただきたいのですが、いかがでしょうか。","respondent":"熊谷指導課長","answer":"文化プログラムと子どもたちとのかかわり、段階的にも子どもたちが文化プログラムに参加する重要な時期にさしかかっていると思いますので、連携をとりながら、子どもたちにも、それから教員にも紹介をして、参加するように呼びかけてまいりたいと思います。","id":"exchange-021"}]},{"id":"topic-02","title":"の３のその他","agenda":"の３のその他","exchanges":[{"speaker":"鈴木（真）副委員長","kind":"質問","question":"先ほどのUNITE HEART FESTIVALの件、教育委員会でさっき話が出て、これは別の場でも話したのですけれども、ほかの区の関係の会合のときに、このフェスティバルがあるという報告がほんのちょっと出ました。そういうところがちょっとあったので、せっかくやるのにもったいないですから、これからいろいろなことをもう少し積極的にアピールしていってください。これはお願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"だからそれは無料でなくて有料でもいいのではないかというのをとても思ったのです。何だかすごく申しわけない気持ちになってしまって、その考え方をちょっと伺いたいと思います。もう一点、「パラスポで新発見。」はスクエア荏原を全館借りての大きなイベントなのでしょうか。この委員会の場では、前回、まだお答えできませんということだったと思うのです。","respondent":"立川文化観光課長、辻オリンピック・パラリンピック準備課長","answer":"UNITE HEART FESTIVALにおける手づくり体験コーナーの関係ですが、こちらはご参加いただける団体の判断ということで、区は関与していないといった状況です。パラリンピックスペシャルデーで使うところなのですが、スクエア荏原の全館ではなくて、ホールとアリーナとイベントホールということで、公園等は使う予定はございません。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問","question":"このパラリンピックスペシャルデーのことなのですけれども、公園のところは開放するということだったので、その当日利用されている方たちにも、中でこういうイベントをしていますよというような声かけ、わかるようなポスターが貼ってあったりとか、そういう促しはしてほしいなと思うのですが、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回は参加自由のパラスポーツ体験がちょっと目立たない感じなので、引っ張ってといいますか、いろいろな方に中に入っていただきたいので、積極的にやっていきたいと思います。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"当然私も手形を押しましたけれども、本当に重々それはやはり担当の所管の方がよくわかっていらっしゃると思うのですが、イベント自体、これに懲りてやらないということではなくて、今度やるときには本当にしっかり準備をされて、初めてのことですからいろいろなことがあるのは仕方ないと思うのですけれども、みんなが参加してよかったなと思えるイベントにしていただきたいと思います。","respondent":"立川文化観光課長","answer":"委員ご指摘のご意見はごもっともだと考えています。次回、挑戦する機会がありましたら、今回の敗因等を最大限活かしていきたいと考えております。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"意見","question":"ぜひまとめは必要だと思いますし、いろいろなやり方があるでしょうけれども、正副委員長で方向性を決めていただいて、当オリンピック・パラリンピック推進特別委員会の１年間の議論のまとめとして提出したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/478583?Template=document&Id=6548#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":26030,"voices":71}},{"id":"h30-20181218-10","meetingId":"h30-cm12","date":"2018年12月18日","dateIso":"2018-12-18","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","topics":[{"id":"topic-01","title":"ありがとうございます。それでは、このように申し出をいたします。 次に、(2)区議会防災訓練","agenda":"ありがとうございます。それでは、このように申し出をいたします。 次に、(2)区議会防災訓練","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料No.５で、全国伝統工芸品振興市議会協議会のことなのですけれども、「加入を考えると回答した２３市区議会」とありますけれども、大体、東京の市区町村でそういった手を挙げたところというのはどこなのか、もしわかれば教えてください。","respondent":"久保田区議会事務局長","answer":"正式にはこちらのほうは聞いておりませんけれども、区によって金沢市と連携をしているような区も幾つかあると聞いておりますので、そういった区は参加しようかみたいなことを考えているようなことは聞いております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"ぜひ確認をお願いしたいと思いますので、よろしくお願いします。","respondent":"久保田区議会事務局長","answer":"わかりました。その旨確認して、各会派のほうにお知らせをしたいと思います。それ以外にも、もし何か確認したいことがあれば、早めにおっしゃっていただければあわせてご確認させていただきたいと思います。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私もこれを読ませていただいたのですけれども、資料２の「要望内容（案）のイメージ」というところの、「販路の拡大」というところで、伝統工芸青山スクエアというところについての記載があるのですけれども、これはあくまでイメージということなのか、これに賛同して加入するということは、この場所を移動せよということも含めて賛同するというイメージになるのか。","respondent":"久保田区議会事務局長","answer":"特に先方のほうからこれについての説明はこの紙面以外にはございませんので、こういうものがここにあるということは私どもでも確認をしているところですけれども、例えば運営の実態とか、移転に関すること等については把握をしておりませんので。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"意見","question":"すみません、本当に調べていなくて発言するのは申しわけないのですけれども、私もちょっと調べてみますけれども、これがどういうところが運営をしていて、どういう関係性があるのか。こういうことを言ってしまって大丈夫なのかというところも含めて調べて、次の議会運営委員会で発言したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100622?Template=document&Id=5310#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":7147,"voices":35}}]);
